          terminalLayout,
          in: layoutBounds(forVisibleCount: visiblePaneOwnerSessionIds.count, in: workspaceBounds),
          path: "root")
      } else {
        layoutGrid(visibleSessionIds, in: layoutBounds(forVisibleCount: visibleSessionIds.count, in: workspaceBounds))
      }
      syncWorkspacePaneSeparatorViews()
    } else {
      hideWorkspacePaneSeparatorViews()
    }
    if shouldShowCommandsPanel {
      syncCommandsPanelChrome(
        in: resolvedCommandPanelBounds,
        isExpanded: shouldShowExpandedCommandsPanel,
        isFloating: shouldShowExpandedCommandsPanel && commandsPanelMode == "floating",
        reservedBottomBarHeight: reservedFloatingCommandsPanelBottomBarHeight)
      layoutCommandsPanel(commandSessionIds, in: resolvedCommandPanelBounds)
      syncCommandsPanelResizeHandle(
        in: resolvedCommandPanelBounds,
        isExpanded: shouldShowExpandedCommandsPanel)
    } else {
      hideCommandsPanelChrome()
      hideCommandsPanelResizeHandle()
    }
    updateOuterBottomPaneBorderCorner()
    syncPaneResizeHandleViews()
  }

  private func hidePaneResizeHandleViews() {
    let shouldRefreshCursor = paneResizeHandleViews.contains { $0.needsCursorRefreshBeforeRemoval() }
    for handleView in paneResizeHandleViews {
      handleView.cancelResizeHoverIndicator()
      handleView.isHidden = true
      handleView.frame = .zero
      window?.invalidateCursorRects(for: handleView)
    }
    if shouldRefreshCursor {
      refreshResizeCursorForCurrentPointer()
    }
  }

  private func hideWorkspacePaneSeparatorViews() {
    for separatorLayer in workspacePaneSeparatorLayers {
      separatorLayer.isHidden = true
      separatorLayer.frame = .zero
    }
  }

  private func configureWorkspaceSeparatorLayer(_ separatorLayer: CALayer) {
    /*
     CDXC:NativeLayout 2026-06-13-09:33:
     Workspace pane separators are visual-only one-pixel chrome. Keep them as
     layers owned by TerminalWorkspaceView so default AppKit dispatch sees only
     the real pane content and resize-handle views.
     */
    separatorLayer.backgroundColor = NSColor(
      srgbRed: 0x1E / 255.0,
      green: 0x1E / 255.0,
      blue: 0x1E / 255.0,
      alpha: 1.0
    ).cgColor
    separatorLayer.actions = [
      "bounds": NSNull(),
      "hidden": NSNull(),
      "position": NSNull(),
    ]
  }

  private func installWorkspaceVisualLayer(_ visualLayer: CALayer) {
    wantsLayer = true
    guard let rootLayer = layer, visualLayer.superlayer !== rootLayer else {
      return
    }
    visualLayer.removeFromSuperlayer()
    rootLayer.addSublayer(visualLayer)
  }

  private func syncWorkspacePaneSeparatorViews() {
    /**
     CDXC:WorkspacePaneSeparators 2026-06-09-17:46:
     Normal workspace split panes need a 1px #1e1e1e visual divider between pane surfaces. Derive separator geometry from paneResizeLayoutRecords so the line stays centered in the same reserved AppKit divider rail that owns resizing, without widening rail frames or overlapping pane content.
     */
    while workspacePaneSeparatorLayers.count < paneResizeLayoutRecords.count {
      let separatorLayer = CALayer()
      configureWorkspaceSeparatorLayer(separatorLayer)
      workspacePaneSeparatorLayers.append(separatorLayer)
    }
    for (index, separatorLayer) in workspacePaneSeparatorLayers.enumerated() {
      guard index < paneResizeLayoutRecords.count else {
        separatorLayer.isHidden = true
        separatorLayer.frame = .zero
        continue
      }
      let frame = workspacePaneSeparatorFrame(for: paneResizeLayoutRecords[index])
      guard !frame.isNull, !frame.isEmpty else {
        separatorLayer.isHidden = true
        separatorLayer.frame = .zero
        continue
      }
      installWorkspaceVisualLayer(separatorLayer)
      separatorLayer.frame = frame
      separatorLayer.isHidden = false
      separatorLayer.zPosition = 9_900
    }
  }

  private func workspacePaneSeparatorFrame(for record: PaneResizeLayoutRecord) -> CGRect {
    let separatorWidth: CGFloat = 1
    let dividerRect = record.rect.intersection(bounds)
    guard !dividerRect.isNull, !dividerRect.isEmpty else {
      return .zero
    }
    switch record.direction {
    case .horizontal:
      return CGRect(
        x: dividerRect.midX - separatorWidth / 2,
        y: dividerRect.minY,
        width: separatorWidth,
        height: dividerRect.height)
    case .vertical:
      return CGRect(
        x: dividerRect.minX,
        y: dividerRect.midY - separatorWidth / 2,
        width: dividerRect.width,
        height: separatorWidth)
    }
  }

  private func hideCommandsPanelResizeHandle() {
    commandsPanelResizeDrag = nil
    let shouldRefreshCursor = commandsPanelResizeHandleView.needsCursorRefreshBeforeRemoval()
    commandsPanelResizeHandleView.cancelResizeHoverIndicator()
    commandsPanelResizeHandleView.isHidden = true
    commandsPanelResizeHandleView.frame = .zero
    window?.invalidateCursorRects(for: commandsPanelResizeHandleView)
    if shouldRefreshCursor {
      refreshResizeCursorForCurrentPointer()
    }
  }

  private func hideCommandsPanelChrome() {
    commandsPanelChromeView.isHidden = true
    commandsPanelChromeView.frame = .zero
    commandsPanelReservedBottomBarView.isHidden = true
    commandsPanelReservedBottomBarView.frame = .zero
    commandsPanelCollapsedRightMarginView.isHidden = true
    commandsPanelCollapsedRightMarginView.frame = .zero
    commandsPanelTopSeparatorLayer.isHidden = true
    commandsPanelTopSeparatorLayer.frame = .zero
  }

  private func syncCommandsPanelChrome(
    in commandPanelBounds: CGRect,
    isExpanded: Bool,
    isFloating: Bool,
    reservedBottomBarHeight: CGFloat
  ) {
    commandsPanelChromeView.frame = commandPanelBounds
    commandsPanelChromeView.isHidden = false
    commandsPanelChromeView.layer?.zPosition = isFloating ? 250 : 0
    if commandsPanelChromeView.superview !== self {
      addSubview(commandsPanelChromeView, positioned: .below, relativeTo: nil)
    }
    if let firstCommandSessionId = orderedVisibleCommandSessionIds().first,
      let firstCommandSession = sessions[firstCommandSessionId],
      firstCommandSession.containerView.superview === self
    {
      addSubview(commandsPanelChromeView, positioned: .below, relativeTo: firstCommandSession.containerView)
    } else {
      addSubview(commandsPanelChromeView, positioned: .below, relativeTo: nil)
    }
    syncCommandsPanelCollapsedRightMargin(from: commandPanelBounds, isExpanded: isExpanded)
    syncCommandsPanelReservedBottomBar(height: reservedBottomBarHeight)
    syncCommandsPanelTopSeparator(in: commandPanelBounds)
  }

  private func syncCommandsPanelTopSeparator(in commandPanelBounds: CGRect) {
    /*
     CDXC:CommandsPanel 2026-05-30-07:35:
