    commandsPanelTopSeparatorLayer.frame = CGRect(
      x: commandPanelBounds.minX,
      y: max(bounds.minY, commandPanelBounds.maxY - separatorHeight),
      width: commandPanelBounds.width,
      height: separatorHeight)
