    }
    let script = """
      window.dispatchEvent(new CustomEvent('\(projectBoardImageResponseEventName)', { detail: \(json) }));
      undefined;
      """
    webView.evaluateJavaScript(script, completionHandler: nil)
  }

  private func handleManageFilesBridgeRequest(
    _ request: ManageFilesBridgeRequest,
    webView: WKWebView?
  ) {
    guard let webView,
      let entry = projectEditorSessionEntry(for: webView),
      entry.session.mode == "manage"
    else {
      return
    }
    let projectEditorId = request.projectEditorId?.trimmingCharacters(in: .whitespacesAndNewlines)
    if let projectEditorId, !projectEditorId.isEmpty, projectEditorId != entry.projectId {
      Self.dispatchManageFilesBridgeResponse(
        ManageFilesBridgeResponse(
          action: request.action,
          entries: nil,
          error: "Docs request was not sent by this project editor.",
          file: nil,
          requestId: request.requestId,
          rootName: nil),
        to: webView)
      return
    }
    let rootPath = entry.session.projectRootPath ?? ""
    let responseTarget = ProjectBeadsBridgeResponseTarget(webView: webView)
    Task.detached(priority: .userInitiated) {
      let response = Self.runManageFilesBridgeRequest(request, projectRootPath: rootPath)
      await MainActor.run {
        guard let webView = responseTarget.webView else {
          return
        }
        Self.dispatchManageFilesBridgeResponse(response, to: webView)
      }
    }
  }

  private nonisolated static func runManageFilesBridgeRequest(
    _ request: ManageFilesBridgeRequest,
    projectRootPath: String
  ) -> ManageFilesBridgeResponse {
    /*
     CDXC:Manage 2026-06-20-06:14:
     Manage file listing, previews, and saves can walk/read/write project files, so the WK bridge runs them from a detached task.
     Keep these helpers nonisolated because they do not touch AppKit/WKWebView state; response dispatch remains on the main actor.
     */
    do {
      let rootURL = try manageProjectRootURL(projectRootPath)
      switch request.action {
      case "list":
        return ManageFilesBridgeResponse(
          action: request.action,
          entries: try manageProjectFileEntries(rootURL: rootURL),
          error: nil,
          file: nil,
          requestId: request.requestId,
          rootName: manageDocsRelativePath)
      case "read":
        return ManageFilesBridgeResponse(
          action: request.action,
          entries: nil,
          error: nil,
          file: try manageProjectFilePreview(rootURL: rootURL, path: request.path),
          requestId: request.requestId,
          rootName: manageDocsRelativePath)
      case "save":
        return ManageFilesBridgeResponse(
          action: request.action,
          entries: nil,
          error: nil,
          file: try manageSaveProjectFile(rootURL: rootURL, path: request.path, content: request.content),
          requestId: request.requestId,
          rootName: manageDocsRelativePath)
      case "rename":
        return ManageFilesBridgeResponse(
          action: request.action,
          entries: nil,
          error: nil,
          file: try manageRenameProjectFile(rootURL: rootURL, path: request.path, newPath: request.newPath),
          requestId: request.requestId,
          rootName: manageDocsRelativePath)
      case "delete":
        try manageDeleteProjectFile(rootURL: rootURL, path: request.path)
        return ManageFilesBridgeResponse(
          action: request.action,
          entries: nil,
          error: nil,
          file: nil,
          requestId: request.requestId,
          rootName: manageDocsRelativePath)
      case "createFolder":
        try manageCreateProjectFolder(rootURL: rootURL, path: request.path)
        return ManageFilesBridgeResponse(
          action: request.action,
          entries: nil,
          error: nil,
          file: nil,
          requestId: request.requestId,
          rootName: manageDocsRelativePath)
      case "move":
        return ManageFilesBridgeResponse(
          action: request.action,
          entries: nil,
          error: nil,
          file: try manageMoveProjectItem(rootURL: rootURL, path: request.path, newPath: request.newPath),
          requestId: request.requestId,
          rootName: manageDocsRelativePath)
      default:
        throw ManageFilesBridgeError.invalidRequest("Unsupported Docs file action.")
      }
    } catch {
      return ManageFilesBridgeResponse(
        action: request.action,
        entries: nil,
        error: error.localizedDescription,
        file: nil,
        requestId: request.requestId,
        rootName: nil)
    }
  }

