  private nonisolated static func manageAppendProjectRootArtifactFileEntries(
    entries: inout [ManageFileEntry],
    rootURL: URL
  ) throws {
    guard entries.count < manageFileListMaxEntries else {
      return
    }
    let keys: Set<URLResourceKey> = [
      .contentModificationDateKey,
      .fileSizeKey,
      .isDirectoryKey,
      .isSymbolicLinkKey,
    ]
    let children = try FileManager.default.contentsOfDirectory(
      at: rootURL,
      includingPropertiesForKeys: Array(keys),
      options: [.skipsPackageDescendants])
    let sortedChildren = children.sorted { left, right in
      left.lastPathComponent.localizedStandardCompare(right.lastPathComponent) == .orderedAscending
    }
    for child in sortedChildren {
      if entries.count >= manageFileListMaxEntries {
        return
      }
      let name = child.lastPathComponent
      guard manageIsRootArtifactFileRelativePath(name),
        name != ".DS_Store"
      else {
        continue
      }
      let values = try? child.resourceValues(forKeys: keys)
      guard values?.isDirectory != true else {
        continue
      }
      let resolvedChild = child.standardizedFileURL.resolvingSymlinksInPath()
      guard manageURLIsInsideProjectRoot(resolvedChild, rootURL: rootURL) else {
        continue
      }
      entries.append(
        ManageFileEntry(
          depth: 0,
          kind: "file",
          modifiedAt: manageISOString(values?.contentModificationDate),
          name: name,
          path: name,
          size: values?.fileSize.map(Int64.init)))
    }
  }

  private nonisolated static func manageAppendProjectFileEntries(
    entries: inout [ManageFileEntry],
    rootURL: URL,
    directoryURL: URL,
    relativeDirectoryPath: String,
    depth: Int
  ) throws {
    guard entries.count < manageFileListMaxEntries,
      depth <= manageFileListMaxDepth
    else {
      return
    }
    let keys: Set<URLResourceKey> = [
      .contentModificationDateKey,
      .fileSizeKey,
      .isDirectoryKey,
      .isSymbolicLinkKey,
    ]
    let children = try FileManager.default.contentsOfDirectory(
      at: directoryURL,
      includingPropertiesForKeys: Array(keys),
      options: [.skipsPackageDescendants])
    let sortedChildren = children.sorted { left, right in
      let leftValues = try? left.resourceValues(forKeys: keys)
      let rightValues = try? right.resourceValues(forKeys: keys)
      let leftIsDirectory = leftValues?.isDirectory == true
      let rightIsDirectory = rightValues?.isDirectory == true
      if leftIsDirectory != rightIsDirectory {
        return leftIsDirectory && !rightIsDirectory
      }
      return left.lastPathComponent.localizedStandardCompare(right.lastPathComponent) == .orderedAscending
    }
    var directoriesToRecurse: [(url: URL, relativePath: String)] = []
    for child in sortedChildren {
      if entries.count >= manageFileListMaxEntries {
        return
      }
      let name = child.lastPathComponent
      if name == ".DS_Store" {
        continue
      }
      let values = try? child.resourceValues(forKeys: keys)
      let isDirectory = values?.isDirectory == true
      let isSymbolicLink = values?.isSymbolicLink == true
      if isDirectory && manageIgnoredDirectoryNames.contains(name) {
        continue
      }
      let resolvedChild = child.standardizedFileURL.resolvingSymlinksInPath()
      if !manageURLIsInsideProjectRoot(resolvedChild, rootURL: rootURL) {
        continue
      }
      let relativePath = relativeDirectoryPath.isEmpty ? name : "\(relativeDirectoryPath)/\(name)"
      entries.append(
        ManageFileEntry(
          depth: depth,
          kind: isDirectory ? "directory" : "file",
          modifiedAt: manageISOString(values?.contentModificationDate),
          name: name,
          path: relativePath,
          size: isDirectory ? nil : values?.fileSize.map(Int64.init)))
      if isDirectory && !isSymbolicLink && depth < manageFileListMaxDepth {
        directoriesToRecurse.append((url: child, relativePath: relativePath))
      }
    }
    for directory in directoriesToRecurse {
      if entries.count >= manageFileListMaxEntries {
        return
      }
      try manageAppendProjectFileEntries(
        entries: &entries,
        rootURL: rootURL,
        directoryURL: directory.url,
        relativeDirectoryPath: directory.relativePath,
        depth: depth + 1)
    }
  }

  private nonisolated static func manageProjectFilePreview(
    rootURL: URL,
    path: String?
  ) throws -> ManageFilePreview {
    /*
     CDXC:Manage 2026-06-20-06:14:
