    let data = try Data(contentsOf: target.url, options: [.mappedIfSafe])
    if data.contains(0) {
      return ManageFilePreview(
        content: nil,
        error: "Binary files are not previewed.",
        gitBaseline: nil,
        kind: "unsupported",
        modifiedAt: manageISOString(values.contentModificationDate),
        name: name,
        path: target.relativePath,
        size: size)
    }
    guard let text = String(data: data, encoding: .utf8) else {
      return ManageFilePreview(
        content: nil,
        error: "This file is not valid UTF-8 text.",
        gitBaseline: nil,
        kind: "unsupported",
        modifiedAt: manageISOString(values.contentModificationDate),
        name: name,
        path: target.relativePath,
        size: size)
    }
    return ManageFilePreview(
      content: text,
      error: nil,
      gitBaseline: manageGitBaselinePayload(
        rootURL: rootURL,
        fileURL: target.url,
        relativePath: target.relativePath),
      kind: "text",
      modifiedAt: manageISOString(values.contentModificationDate),
      name: name,
      path: target.relativePath,
      size: size)
  }

