          getLocalEnvironmentBearerToken: async () => {
            const cached =
              typeof window.__VSMUX_T3_OWNER_BEARER_TOKEN__ === "string"
                ? window.__VSMUX_T3_OWNER_BEARER_TOKEN__.trim()
                : "";
            if (cached) {
              return cached;
            }
            const token = await requestNativeBridgeValue("getLocalEnvironmentBearerToken");
            const normalized = typeof token === "string" ? token.trim() : "";
            if (!normalized) {
              throw new Error("Native T3 bridge returned an empty bearer token.");
            }
            window.__VSMUX_T3_OWNER_BEARER_TOKEN__ = normalized;
            return normalized;
          },
          getWsUrl: () => wsUrl(),
          getSavedEnvironmentRegistry: async () => [],
          getSavedEnvironmentSecret: async () => null,
          getServerExposureState: async () => serverExposureState,
          notifications: {
            isSupported: async () => false,
            show: async () => false
          },
          getUpdateState: async () => updateState,
          installUpdate: async () => ({ accepted: false, completed: false, state: updateState }),
          checkForUpdate: async () => ({ checked: false, state: updateState }),
          downloadUpdate: async () => ({ accepted: false, completed: false, state: updateState }),
          onMenuAction: () => () => undefined,
          onUpdateState: () => () => undefined,
          openExternal: async (url) => {
            try {
              window.open(String(url), "_blank", "noopener,noreferrer");
              return true;
            } catch {
              return false;
            }
          },
          pickFolder: async () => null,
          removeSavedEnvironmentSecret: async () => undefined,
          setClientSettings: async () => undefined,
          setSavedEnvironmentRegistry: async () => undefined,
          setSavedEnvironmentSecret: async () => false,
          setServerExposureMode: async () => serverExposureState,
          setTheme: async () => undefined,
          showContextMenu: async () => null
