      })();
      """
  }

  private static func javascriptStringLiteral(_ value: String) -> String {
    guard let data = try? JSONSerialization.data(withJSONObject: [value], options: []),
      let json = String(data: data, encoding: .utf8),
      json.hasPrefix("["),
      json.hasSuffix("]")
    else {
      return "\"\""
    }
    return String(json.dropFirst().dropLast())
  }

  private static func cefDragHoverBridgeScript(
    x: CGFloat,
    y: CGFloat,
    phase: String,
    sourceX: CGFloat?,
    sourceY: CGFloat?
  ) -> String {
    let xLiteral = String(format: "%.2f", Double(x))
    let yLiteral = String(format: "%.2f", Double(y))
    let phaseLiteral = javascriptStringLiteral(phase)
    let sourceXLiteral = sourceX.map { String(format: "%.2f", Double($0)) } ?? "null"
    let sourceYLiteral = sourceY.map { String(format: "%.2f", Double($0)) } ?? "null"
    return """
      (() => {
        const x = \(xLiteral);
        const y = \(yLiteral);
        const phase = \(phaseLiteral);
        const sourceX = \(sourceXLiteral);
        const sourceY = \(sourceYLiteral);
        const bridge = window.__ghostexCEFDragHoverBridge ||= {
          dataTransfer: null,
          lastTarget: null,
          sourceTarget: null
        };
        const stableTargetSelectors = [
          ".pane",
          ".composite",
          ".part.sidebar",
          ".part.activitybar",
          ".monaco-list-row",
          ".monaco-list",
          ".action-item",
          "[role='treeitem']",
          "[draggable='true']"
        ];
        const sourceTargetSelectors = [
          "[draggable='true']",
          ".pane-header",
          ".action-item",
          ".monaco-list-row",
          ".pane"
        ];
        const asElement = (node) => node instanceof Element ? node : node?.parentElement || null;
        const closestByPriority = (element, selectors) => {
          for (const selector of selectors) {
            const match = element.closest(selector);
            if (match) {
              return match;
            }
          }
          return null;
        };
        const stableTargetFor = (rawTarget, selectors = stableTargetSelectors) => {
          const element = asElement(rawTarget);
          if (!element) {
            return null;
          }
          return closestByPriority(element, selectors) || element;
        };
        const makeDataTransfer = () => {
          if (bridge.dataTransfer) {
            return bridge.dataTransfer;
          }
          try {
            bridge.dataTransfer = new DataTransfer();
            try {
              bridge.dataTransfer.effectAllowed = "move";
              bridge.dataTransfer.dropEffect = "move";
            } catch {}
            return bridge.dataTransfer;
          } catch {
            return null;
          }
        };
        const dispatchDragEvent = (target, type) => {
          if (!target) {
            return false;
          }
          const dataTransfer = makeDataTransfer();
          const init = {
            bubbles: true,
            cancelable: true,
            clientX: x,
            clientY: y,
            composed: true,
            dataTransfer,
            screenX: window.screenX + x,
            screenY: window.screenY + y,
            view: window
          };
          let event;
          try {
            event = new DragEvent(type, init);
          } catch {
            event = document.createEvent("DragEvent");
            event.initMouseEvent(type, true, true, window, 0, 0, 0, x, y, false, false, false, false, 0, null);
          }
          return target.dispatchEvent(event);
        };
        if (phase === "cancel") {
          dispatchDragEvent(bridge.lastTarget, "dragleave");
          dispatchDragEvent(bridge.sourceTarget || bridge.lastTarget, "dragend");
          bridge.lastTarget = null;
          bridge.sourceTarget = null;
          bridge.dataTransfer = null;
          return;
        }
        const target = document.elementFromPoint(x, y);
        const stableTarget = stableTargetFor(target);
        if (!stableTarget) {
          return;
        }
        if (phase === "start") {
          const sourceTarget = sourceX === null || sourceY === null ? null : document.elementFromPoint(sourceX, sourceY);
          bridge.sourceTarget = stableTargetFor(sourceTarget, sourceTargetSelectors) || stableTarget;
        }
        if (bridge.lastTarget !== stableTarget) {
          dispatchDragEvent(bridge.lastTarget, "dragleave");
          dispatchDragEvent(stableTarget, "dragenter");
          bridge.lastTarget = stableTarget;
        }
        dispatchDragEvent(stableTarget, "dragover");
        if (phase === "drop") {
          dispatchDragEvent(stableTarget, "drop");
          dispatchDragEvent(bridge.sourceTarget || stableTarget, "dragend");
          bridge.lastTarget = null;
          bridge.sourceTarget = null;
          bridge.dataTransfer = null;
        }
      })();
      """
  }

  private static func sourceCEFDragDiagnosticsScript(reason: String, nativeDragId: UInt64? = nil) -> String {
    let prefixLiteral = javascriptStringLiteral(sourceCEFDragDiagnosticConsolePrefix)
    let reasonLiteral = javascriptStringLiteral(reason)
    let nativeDragIdLiteral = nativeDragId.map { String($0) } ?? "null"
    return """
      (() => {
        const prefix = \(prefixLiteral);
        const installReason = \(reasonLiteral);
        const nativeDragId = \(nativeDragIdLiteral);
        const existing = window.__ghostexSourceCEFDragDiagnostics;
        if (existing?.installed) {
          existing.installReason = installReason;
          existing.nativeDragId = nativeDragId;
          try {
            console.info(prefix + JSON.stringify({
              type: "install-skip",
              installReason,
              nativeDragId,
              readyState: String(document.readyState || ""),
              hasFocus: document.hasFocus(),
              performanceNow: Math.round(performance.now())
            }));
          } catch {}
          return;
        }
        /*
        CDXC:SourceCEFDragDrop 2026-06-11-07:31:
        Source CEF tab-drag diagnostics must prove whether code-server receives pointer/mouse and DOM drag events. Log only structural element metadata and event flags; never log tab text, editor content, URLs, labels, titles, or file paths.

        CDXC:SourceCEFDragDrop 2026-06-11-19:40:
        Ghostex now needs to compare the working minimal CEF/WKWebView app with the full macOS shell. Keep this probe read-only while summarizing each native-correlated HTML drag sequence, including whether `dragenter`, `dragover`, and `drop` ever reach VS Code's tab container.
        */
        const state = window.__ghostexSourceCEFDragDiagnostics = {
          currentDrag: null,
          dragSequenceId: 0,
          installReason,
          installed: true,
          lastByType: Object.create(null),
          nativeDragId
        };
        const selectorChecks = [
          ["workbench", ".monaco-workbench"],
          ["partEditor", ".part.editor"],
          ["editorGroups", ".editor-groups-container"],
          ["tabsContainer", ".tabs-container"],
          ["tab", ".tab"],
          ["tabDraggable", ".tab[draggable='true']"],
          ["tabBorderTop", ".tab-border-top-container"],
          ["monacoListRow", ".monaco-list-row"],
          ["draggable", "[draggable='true']"]
        ];
        const asElement = (value) => value instanceof Element ? value : value?.parentElement || null;
        const summarizeElement = (value) => {
          const element = asElement(value);
          if (!element) {
            return { tag: "none", role: "", draggable: false, classTokens: [], matches: [] };
          }
          const classTokens = Array.from(element.classList || [])
            .filter((token) => /^[a-zA-Z0-9_-]{1,48}$/.test(token))
            .slice(0, 8);
          const matches = [];
          for (const [name, selector] of selectorChecks) {
            try {
              if (element.matches(selector) || element.closest(selector)) {
                matches.push(name);
              }
            } catch {}
          }
          return {
            tag: String(element.tagName || "").toLowerCase(),
            role: String(element.getAttribute("role") || ""),
            draggable: element.draggable === true || element.getAttribute("draggable") === "true",
            classTokens,
            matches
          };
        };
        const numeric = (value) => Number.isFinite(value) ? Math.round(value) : 0;
        const viewportSummary = () => ({
          devicePixelRatio: Number.isFinite(window.devicePixelRatio) ? Number(window.devicePixelRatio.toFixed(3)) : 0,
          innerHeight: numeric(window.innerHeight),
          innerWidth: numeric(window.innerWidth),
          scrollX: numeric(window.scrollX),
          scrollY: numeric(window.scrollY)
        });
        const elementFromEventPoint = (event) => {
          try {
            if (!Number.isFinite(event.clientX) || !Number.isFinite(event.clientY)) {
              return null;
            }
            return document.elementFromPoint(event.clientX, event.clientY);
          } catch {
            return null;
          }
        };
        const dataTransferSummary = (event) => event.dataTransfer ? {
          dropEffect: String(event.dataTransfer.dropEffect || ""),
          effectAllowed: String(event.dataTransfer.effectAllowed || ""),
          typesCount: event.dataTransfer.types ? event.dataTransfer.types.length : 0
        } : null;
        const eventSnapshot = (event) => ({
          button: typeof event.button === "number" ? event.button : -1,
          buttons: typeof event.buttons === "number" ? event.buttons : 0,
          cancelable: event.cancelable === true,
          clientX: numeric(event.clientX),
          clientY: numeric(event.clientY),
          dataTransfer: dataTransferSummary(event),
          defaultPrevented: event.defaultPrevented === true,
          target: summarizeElement(event.target),
          type: event.type,
          underPointer: summarizeElement(elementFromEventPoint(event))
        });
        const emptyCounts = () => Object.create(null);
        const startDragSummary = (event) => {
          const summary = state.currentDrag = {
            counts: emptyCounts(),
            dragSequenceId: ++state.dragSequenceId,
            dragoverCancelableCount: 0,
            dragoverDefaultPreventedCount: 0,
            first: eventSnapshot(event),
            last: null,
            lastDragover: null,
            lastDrop: null,
            nativeDragId: state.nativeDragId,
            startedAt: performance.now()
          };
          return summary;
        };
        const recordDragEvent = (event) => {
          if (!event.type.startsWith("drag") && event.type !== "drop") {
            return state.currentDrag;
          }
          const summary = event.type === "dragstart"
            ? startDragSummary(event)
            : (state.currentDrag || startDragSummary(event));
          summary.counts[event.type] = (summary.counts[event.type] || 0) + 1;
          const snapshot = eventSnapshot(event);
          summary.last = snapshot;
          if (event.type === "dragover") {
            summary.lastDragover = snapshot;
            if (event.cancelable === true) {
              summary.dragoverCancelableCount += 1;
            }
            if (event.defaultPrevented === true) {
              summary.dragoverDefaultPreventedCount += 1;
            }
          } else if (event.type === "drop") {
            summary.lastDrop = snapshot;
          }
          return summary;
        };
        const shouldThrottle = (event) => {
          if (!["pointermove", "mousemove", "dragover"].includes(event.type)) {
            return false;
          }
          const previous = state.lastByType[event.type];
          const now = performance.now();
          const x = numeric(event.clientX);
          const y = numeric(event.clientY);
          if (previous) {
            const elapsed = now - previous.now;
            const distance = Math.hypot(x - previous.x, y - previous.y);
            if (elapsed < 200 && distance < 12) {
              return true;
            }
          }
          state.lastByType[event.type] = { now, x, y };
          return false;
        };
        const phaseName = (phase) => {
          if (phase === Event.CAPTURING_PHASE) return "capture";
          if (phase === Event.AT_TARGET) return "target";
          if (phase === Event.BUBBLING_PHASE) return "bubble";
          return "none";
        };
        const postDragSummary = (event, summary) => {
          try {
            if (!summary) {
              return;
            }
            const counts = {};
            for (const [key, value] of Object.entries(summary.counts)) {
              counts[key] = value;
            }
            console.info(prefix + JSON.stringify({
              type: "drag-sequence-summary",
              completedBy: event.type,
              counts,
              dragSequenceId: summary.dragSequenceId,
              dragoverCancelableCount: summary.dragoverCancelableCount,
              dragoverDefaultPreventedCount: summary.dragoverDefaultPreventedCount,
              durationMs: Math.round(performance.now() - summary.startedAt),
              first: summary.first,
              hasDrop: counts.drop > 0,
              hasDragover: counts.dragover > 0,
              installReason: state.installReason,
              last: summary.last,
              lastDragover: summary.lastDragover,
              lastDrop: summary.lastDrop,
              nativeDragId: summary.nativeDragId,
              performanceNow: Math.round(performance.now()),
              readyState: String(document.readyState || ""),
              viewport: viewportSummary()
            }));
          } catch {}
        };
        const post = (event) => {
          try {
            const dragSummary = recordDragEvent(event);
            if (shouldThrottle(event)) {
              return;
            }
            const payload = {
              type: event.type,
              dragSequenceId: dragSummary?.dragSequenceId || null,
              installReason: state.installReason,
              nativeDragId: state.nativeDragId,
              readyState: String(document.readyState || ""),
              hasFocus: document.hasFocus(),
              eventPhase: phaseName(event.eventPhase),
              button: typeof event.button === "number" ? event.button : -1,
              buttons: typeof event.buttons === "number" ? event.buttons : 0,
              clientX: numeric(event.clientX),
              clientY: numeric(event.clientY),
              defaultPrevented: event.defaultPrevented === true,
              cancelable: event.cancelable === true,
              dataTransfer: dataTransferSummary(event),
              target: summarizeElement(event.target),
              activeElement: summarizeElement(document.activeElement),
              underPointer: summarizeElement(elementFromEventPoint(event)),
              viewport: viewportSummary(),
              performanceNow: Math.round(performance.now())
            };
            console.info(prefix + JSON.stringify(payload));
            if (event.type === "drop" || event.type === "dragend") {
              postDragSummary(event, dragSummary);
              if (event.type === "dragend") {
                state.currentDrag = null;
              }
            }
          } catch {}
        };
        for (const type of [
          "pointerdown",
          "pointermove",
          "pointerup",
          "mousedown",
          "mousemove",
          "mouseup",
          "dragstart",
          "dragenter",
          "dragover",
          "dragleave",
          "drop",
          "dragend"
        ]) {
          window.addEventListener(type, post, true);
        }
        console.info(prefix + JSON.stringify({
          type: "install",
          installReason,
          nativeDragId,
          readyState: String(document.readyState || ""),
          hasFocus: document.hasFocus(),
          viewport: viewportSummary(),
          performanceNow: Math.round(performance.now())
        }));
      })();
      """
  }

  private static let t3WebPaneDiagnosticsScript = """
    (() => {
      const handler = window.webkit?.messageHandlers?.\(T3CodePaneDiagnosticsBridge.messageHandlerName);
      if (!handler) {
        return;
      }
      const summarize = (value) => {
        try {
          if (value instanceof Error) {
            return value.stack || value.message || String(value);
          }
          if (typeof value === "object" && value !== null) {
            return JSON.stringify(value);
          }
          return String(value);
        } catch {
          return String(value);
        }
      };
      const post = (payload) => {
        try {
          handler.postMessage({
            href: String(location.href || ""),
            readyState: String(document.readyState || ""),
            timestamp: new Date().toISOString(),
            ...payload
          });
        } catch {}
      };
      window.addEventListener("error", (event) => {
        const target = event.target;
        const isResourceError = target && target !== window;
        post({
          column: event.colno || 0,
          line: event.lineno || 0,
          message: String(event.message || ""),
          resourceHref: isResourceError ? String(target.src || target.href || "") : "",
          source: String(event.filename || ""),
          stack: event.error && event.error.stack ? String(event.error.stack) : "",
          type: isResourceError ? "resource-error" : "error"
        });
      }, true);
      window.addEventListener("unhandledrejection", (event) => {
        post({
          message: summarize(event.reason),
          stack: event.reason && event.reason.stack ? String(event.reason.stack) : "",
          type: "unhandledrejection"
        });
      });
      for (const method of ["error", "warn"]) {
        const original = console[method]?.bind(console);
        console[method] = (...args) => {
          post({ message: args.map(summarize).join(" "), type: `console.${method}` });
          original?.(...args);
        };
      }
      post({ type: "diagnostics-ready" });
    })();
    """

  private func searchBarFrame(in terminalRect: CGRect) -> CGRect {
    let width = min(CGFloat(300), max(terminalRect.width - 16, 180))
    let height = CGFloat(34)
    return CGRect(
      x: terminalRect.maxX - width - 8,
      y: terminalRect.maxY - height - 8,
      width: width,
      height: height
    )
  }

  private func logTerminalResizeIfNeeded(
    session: TerminalSession,
    paneRect: CGRect,
    titleBarRect: CGRect,
    availableTerminalRect: CGRect,
    terminalRect: CGRect
  ) {
    /**
     CDXC:NativeTerminalResize 2026-04-29-02:22
     Narrow-pane Claude Code rendering regressions need geometry diagnostics
     from every native resize layer. Log only changed signatures so PTY size,
     Ghostty surface size, scroll content size, and visible pane dimensions can
     be compared without flooding the app log during no-op layout passes.
     */
    let nestedScrollView = firstNestedScrollView(in: session.scrollView)
    let publishedSurfaceSize = session.view.surfaceSize
    let surfaceSize = session.view.surface.map { ghostty_surface_size($0) } ?? publishedSurfaceSize
    let surfacePadding = session.view.surface.map { ghostty_surface_padding($0) }
    let cellSize = session.view.cellSize
    let estimatedColumns =
      cellSize.width > 0 ? Int(floor(terminalRect.width / cellSize.width)) : nil
    let estimatedRows =
      cellSize.height > 0 ? Int(floor(terminalRect.height / cellSize.height)) : nil
    /**
     CDXC:NativeTerminalResize 2026-04-29-07:50
     Claude Code/Ink rerenders from the PTY rows and columns that Ghostty
     reports after subtracting terminal padding. Log synchronous core size,
     published AppKit size, backing-pixel metrics, actual Ghostty padding, and
     residual non-grid space so resize bugs can distinguish stale Swift state
     from Ghostty grid math.
     */
    let coreSurfaceSize = surfaceSize.map { size in
      session.view.convertFromBacking(
        NSSize(width: Double(size.width_px), height: Double(size.height_px)))
    }
    let inferredHorizontalPaddingPx = surfaceSize.map {
      Int($0.width_px) - Int($0.columns) * Int($0.cell_width_px)
    }
    let inferredVerticalPaddingPx = surfaceSize.map {
      Int($0.height_px) - Int($0.rows) * Int($0.cell_height_px)
    }
    let inferredPadding = inferredPaddingPoints(
      view: session.view,
      horizontalPx: inferredHorizontalPaddingPx,
      verticalPx: inferredVerticalPaddingPx)
    let actualPadding = actualPaddingPoints(view: session.view, padding: surfacePadding)
    let paddingAwareEstimatedColumns = paddingAwareEstimatedCellCount(
      available: terminalRect.width,
      padding: actualPadding?.width,
      cell: cellSize.width)
    let paddingAwareEstimatedRows = paddingAwareEstimatedCellCount(
      available: terminalRect.height,
      padding: actualPadding?.height,
      cell: cellSize.height)
    let signature = [
      roundedSignature(paneRect.size.width),
      roundedSignature(paneRect.size.height),
      roundedSignature(terminalRect.size.width),
      roundedSignature(terminalRect.size.height),
      roundedSignature(session.scrollView.bounds.size.width),
      roundedSignature(session.scrollView.bounds.size.height),
      roundedSignature(session.view.frame.size.width),
      roundedSignature(session.view.frame.size.height),
      String(surfaceSize?.columns ?? 0),
      String(surfaceSize?.rows ?? 0),
      String(estimatedColumns ?? 0),
      String(estimatedRows ?? 0),
      String(paddingAwareEstimatedColumns ?? 0),
      String(paddingAwareEstimatedRows ?? 0),
      String(surfaceSize?.width_px ?? 0),
      String(surfaceSize?.height_px ?? 0),
    ].joined(separator: "x")
    if resizeLogSignatureBySessionId[session.sessionId] == signature {
      return
    }
    resizeLogSignatureBySessionId[session.sessionId] = signature
    TerminalFocusDebugLog.append(
      event: "nativeWorkspace.terminalResize",
      details: [
        "cellSize": describeSize(cellSize),
        "coreSurfaceSizeLogical": coreSurfaceSize.map { describeSize($0) } ?? NSNull(),
        "coreSurfaceSizePixels": surfaceSize.map {
          ["height": Int($0.height_px), "width": Int($0.width_px)]
        } ?? NSNull(),
        "coreSurfaceCellSizePixels": surfaceSize.map {
          ["height": Int($0.cell_height_px), "width": Int($0.cell_width_px)]
        } ?? NSNull(),
        "coreSurfaceGridSizePixels": surfaceSize.map {
          [
            "height": Int($0.rows) * Int($0.cell_height_px),
            "width": Int($0.columns) * Int($0.cell_width_px),
          ]
        } ?? NSNull(),
        "estimatedColumns": nullableInt(estimatedColumns),
        "estimatedRows": nullableInt(estimatedRows),
        "focusedSessionId": nullableString(focusedSessionId),
        "inferredPaddingPixels": inferredHorizontalPaddingPx.map { horizontal in
          [
            "horizontal": horizontal,
            "vertical": inferredVerticalPaddingPx ?? 0,
          ]
        } ?? NSNull(),
        "inferredPaddingPoints": inferredPadding.map { describeSize($0) } ?? NSNull(),
        "surfacePaddingPixels": surfacePadding.map {
          [
            "bottom": Int($0.bottom_px),
            "left": Int($0.left_px),
            "right": Int($0.right_px),
            "top": Int($0.top_px),
          ]
        } ?? NSNull(),
        "surfacePaddingPoints": actualPadding.map { describeSize($0) } ?? NSNull(),
        "nestedScrollContentSize": nestedScrollView.map { describeSize($0.contentSize) }
          ?? NSNull(),
        "nestedScrollDocumentVisibleRect": nestedScrollView.map {
          describeFrame($0.contentView.documentVisibleRect)
        } ?? NSNull(),
        "paneGap": Double(paneGap),
        "paneRect": describeFrame(paneRect),
        "paddingAwareEstimatedColumns": nullableInt(paddingAwareEstimatedColumns),
        "paddingAwareEstimatedRows": nullableInt(paddingAwareEstimatedRows),
        "publishedSurfaceSizeColumns": publishedSurfaceSize.map { Int($0.columns) } ?? NSNull(),
        "publishedSurfaceSizeRows": publishedSurfaceSize.map { Int($0.rows) } ?? NSNull(),
        "rawTerminalRect": describeFrame(availableTerminalRect),
        "scrollViewBounds": describeFrame(session.scrollView.bounds),
        "scrollViewFrame": describeFrame(session.scrollView.frame),
        "sessionId": session.sessionId,
        "surfaceFrame": describeFrame(session.view.frame),
        "surfaceSizeColumns": surfaceSize.map { Int($0.columns) } ?? NSNull(),
        "surfaceSizeRows": surfaceSize.map { Int($0.rows) } ?? NSNull(),
        "terminalRect": describeFrame(terminalRect),
        "titleBarRect": describeFrame(titleBarRect),
        "visibleSessionIds": orderedVisibleSessionIds(),
      ])
  }

  private func inferredPaddingPoints(
    view: NSView,
    horizontalPx: Int?,
    verticalPx: Int?
  ) -> NSSize? {
    guard let horizontalPx, let verticalPx else {
      return nil
    }
    let backingSize = NSSize(width: Double(horizontalPx), height: Double(verticalPx))
    return view.convertFromBacking(backingSize)
  }

  private func actualPaddingPoints(
    view: NSView,
    padding: ghostty_surface_padding_s?
  ) -> NSSize? {
    guard let padding else {
      return nil
    }
    let backingSize = NSSize(
      width: Double(padding.left_px + padding.right_px),
      height: Double(padding.top_px + padding.bottom_px))
    return view.convertFromBacking(backingSize)
  }

  private func paddingAwareEstimatedCellCount(
    available: CGFloat,
    padding: CGFloat?,
    cell: CGFloat
  ) -> Int? {
    guard let padding, cell > 0 else {
      return nil
    }
    return Int(floor(max(available - padding, 0) / cell))
  }

  private func firstNestedScrollView(in view: NSView) -> NSScrollView? {
    if let scrollView = view as? NSScrollView {
      return scrollView
    }
    for subview in view.subviews {
      if let scrollView = firstNestedScrollView(in: subview) {
        return scrollView
      }
    }
    return nil
  }

  private func roundedSignature(_ value: CGFloat) -> String {
    String(Int(value.rounded()))
  }

  private func nativeLayoutSignature(
    activeSessionIds: Set<String>,
    activeProjectEditorId: String?,
    layout: NativeTerminalLayout?,
    paneGap: CGFloat,
    terminalPaneHorizontalPaddingPx: CGFloat,
    terminalPaneVerticalPaddingPx: CGFloat,
    poppedOutSessionIds: Set<String>
  ) -> String {
    [
      "active=\(activeSessionIds.sorted().joined(separator: ","))",
      "editor=\(activeProjectEditorId ?? "")",
      "gap=\(roundedSignature(paneGap * 100))",
      "layout=\(nativeLayoutNodeSignature(layout))",
      "terminalPadding=\(roundedSignature(terminalPaneHorizontalPaddingPx)),\(roundedSignature(terminalPaneVerticalPaddingPx))",
      "popped=\(poppedOutSessionIds.sorted().joined(separator: ","))",
    ].joined(separator: "|")
  }

  private func nativeLayoutNodeSignature(_ layout: NativeTerminalLayout?) -> String {
    guard let layout else {
      return "none"
    }
    switch layout {
    case .leaf(let sessionId):
      return "leaf:\(sessionId)"
    case .tabs(let activeSessionId, let sessionIds):
      return "tabs:\(activeSessionId ?? "nil"):[\(sessionIds.joined(separator: ","))]"
    case .split(let direction, let ratio, let children):
      let ratioSignature = ratio.map { String(format: "%.5f", $0) } ?? "nil"
      return
        "split:\(direction.rawValue):\(ratioSignature):[\(children.map { nativeLayoutNodeSignature($0) }.joined(separator: ","))]"
    }
  }

  private func appendLayoutLayeringDebugLog(
    _ event: String,
    details: [String: Any] = [:],
    force: Bool = false
  ) {
    /*
     CDXC:WorkspaceLayeringDiagnostics 2026-05-28-04:36:
     Browser-pane click-through repros need the native view ordering and
     hit-test owner beside sidebar paneLayout traces. Keep the payload
     metadata-only and write it to the dedicated layout/layering log so
     terminal focus diagnostics stay readable.
     */
    var payload = details
    payload["activeProjectEditorId"] = nullableString(activeProjectEditorId)
    payload["activeSessionIds"] = Array(activeSessionIds).sorted()
    payload["focusedSessionId"] = nullableString(focusedSessionId)
    payload["responder"] = responderSnapshot()
    payload["visiblePaneOwnerSessionIds"] = orderedVisiblePaneOwnerSessionIds()
    payload["visibleProjectEditorInteractionSessionIds"] = visibleProjectEditorInteractionSessionIds
    payload["visibleSurfaces"] = visibleWorkspaceSurfaceSummary()
    NativeLayoutLayeringDebugLog.append(event: event, details: payload, force: force)
  }

  private func visibleWorkspaceSurfaceSummary() -> [[String: Any]] {
    var surfaces: [[String: Any]] = []
    for (sessionId, session) in sessions {
      if session.containerView.window != nil || !session.containerView.isHidden {
        surfaces.append(surfaceSummary(
          kind: "terminal",
          id: sessionId,
          view: session.containerView,
          contentView: session.scrollView))
      }
    }
    for (sessionId, session) in webPaneSessions {
      if session.containerView.window != nil || !session.containerView.isHidden {
        surfaces.append(surfaceSummary(
          kind: "browser",
          id: sessionId,
          view: session.containerView,
          contentView: session.hostView))
      }
    }
    for (projectId, session) in projectEditorPaneSessions {
      if session.hostView.window != nil || !session.hostView.isHidden {
        surfaces.append(surfaceSummary(
          kind: "projectEditor.\(session.mode)",
          id: projectId,
          view: session.hostView,
          contentView: session.hostView))
      }
    }
    return surfaces.sorted {
      (($0["kind"] as? String) ?? "") + ":" + (($0["id"] as? String) ?? "")
        < (($1["kind"] as? String) ?? "") + ":" + (($1["id"] as? String) ?? "")
    }
  }

  private func surfaceSummary(kind: String, id: String, view: NSView, contentView: NSView) -> [String: Any] {
    [
      "alpha": Double(view.alphaValue),
      "contentFrame": describeFrame(contentView.frame),
      "frame": describeFrame(view.frame),
      "hidden": view.isHidden,
      "id": id,
      "kind": kind,
      "superviewIndex": view.superview?.subviews.firstIndex(of: view) ?? -1,
      "windowAttached": view.window != nil,
      "zPosition": Double(view.layer?.zPosition ?? 0),
    ]
  }

  private func moveOffscreen(_ view: NSView) {
    let size =
      view.frame.size.width > 1 && view.frame.size.height > 1
      ? view.frame.size
      : bounds.size
    let nextFrame = CGRect(
      x: bounds.maxX + 10_000,
      y: bounds.maxY + 10_000,
      width: max(size.width, 1),
      height: max(size.height, 1)
    )
    if !rectsMatch(view.frame, nextFrame) {
      view.frame = nextFrame
    }
  }

  private func moveOffscreen(_ layer: CALayer) {
    let size =
      layer.frame.size.width > 1 && layer.frame.size.height > 1
      ? layer.frame.size
      : bounds.size
    let nextFrame = CGRect(
      x: bounds.maxX + 10_000,
      y: bounds.maxY + 10_000,
      width: max(size.width, 1),
      height: max(size.height, 1)
    )
    if !rectsMatch(layer.frame, nextFrame) {
      performWithoutLayerActions {
        layer.frame = nextFrame
      }
    }
  }

  private func applyWorkspaceBackgroundColor(_ value: String?) {
    let nextValue = value ?? ""
    guard workspaceBackgroundColorValue != nextValue else {
      return
    }
    /**
    CDXC:NativeGpu 2026-05-08-16:45
     Passive metadata sync can arrive without a visual workspace change.
     Reassign the AppKit backing-layer color only when the configured value
     changes so repeated status updates do not dirty the whole workspace layer.
     */
    workspaceBackgroundColorValue = nextValue
    let color = workspaceBackgroundColor(value)
    layer?.backgroundColor = color.cgColor
    for session in sessions.values {
      session.containerView.setBackgroundColor(color)
    }
  }

  private func terminalPaneBackgroundColor() -> NSColor {
    workspaceBackgroundColor(workspaceBackgroundColorValue)
  }

  private func terminalPaneContentRect(in availableTerminalRect: CGRect) -> CGRect {
    /*
     CDXC:TerminalPanePadding 2026-06-25-21:27:
     Clamp native insets against the current pane body so extreme or stale
     settings cannot collapse the Ghostty surface below one point. This keeps
     padding a real layout inset instead of hiding the renderer behind an
     overlay or fallback path.
     */
    let horizontalInset = min(
      terminalPaneHorizontalPaddingPx,
      max((availableTerminalRect.width - 1) / 2, 0))
    let verticalInset = min(
      terminalPaneVerticalPaddingPx,
      max((availableTerminalRect.height - 1) / 2, 0))
    return availableTerminalRect.insetBy(dx: horizontalInset, dy: verticalInset)
  }

  private func setHidden(_ hidden: Bool, for view: NSView) {
    guard view.isHidden != hidden else {
      return
    }
    view.isHidden = hidden
  }

  private func setHidden(_ hidden: Bool, for layer: CALayer) {
    guard layer.isHidden != hidden else {
      return
    }
    performWithoutLayerActions {
      layer.isHidden = hidden
    }
  }

  private func setPaneBorderFrame(
    _ frame: CGRect,
    for borderLayer: TerminalPaneBorderLayer
  ) {
    guard !rectsMatch(borderLayer.frame, frame) else {
      return
    }
    /*
     CDXC:NativePaneChrome 2026-06-13-23:19:
     Focused border geometry is a status indicator, not motion. Assign border
     frames with implicit Core Animation actions disabled so reused pane border
     layers cannot visibly travel from stale or offscreen positions.
     */
    performWithoutLayerActions {
      borderLayer.frame = frame
    }
  }

  private func performWithoutLayerActions(_ updates: () -> Void) {
    CATransaction.begin()
    CATransaction.setDisableActions(true)
    updates()
    CATransaction.commit()
  }

  private func updateAllTerminalBorders() {
    cancelIneligibleFocusedPaneBorderSettlements()
    for sessionId in sessions.keys {
      updateTerminalBorder(for: sessionId)
    }
    for sessionId in webPaneSessions.keys {
      updateTerminalBorder(for: sessionId)
    }
    for sessionId in sleepingPanePlaceholderSessions.keys {
      updateSleepingPanePlaceholderBorder(for: sessionId)
    }
  }

  private func updateTerminalOrPlaceholderBorder(for sessionId: String) {
    if sleepingPanePlaceholderSessions[sessionId] != nil {
      updateSleepingPanePlaceholderBorder(for: sessionId)
    } else {
      updateTerminalBorder(for: sessionId)
    }
  }

  func beginSidebarFocusBorderHandoff(reason: String) {
    let preservedSessionIds = focusedPaneBorderSettledSessionIds.filter {
      isSidebarFocusBorderHandoffDrawable(sessionId: $0)
    }
    guard !preservedSessionIds.isEmpty else {
      return
    }
    sidebarFocusBorderHandoffPreservedSessionIds = Set(preservedSessionIds)
    sidebarFocusBorderHandoffTargetSessionId = nil
    sidebarFocusBorderHandoffGeneration &+= 1
    let generation = sidebarFocusBorderHandoffGeneration
    DispatchQueue.main.asyncAfter(
      deadline: .now() + .milliseconds(Self.sidebarFocusBorderHandoffTimeoutMs)
    ) { [weak self] in
      guard let self,
        self.sidebarFocusBorderHandoffGeneration == generation,
        self.hasSidebarFocusBorderHandoff
      else {
        return
      }
      self.cancelSidebarFocusBorderHandoff(reason: "timeout.\(reason)")
    }
  }

  func setSidebarFocusBorderHandoffTarget(sessionId rawSessionId: String, reason: String) {
    let sessionId = ghostexNativeFocusSessionId(from: rawSessionId) ?? rawSessionId
    guard hasSidebarFocusBorderHandoff else {
      return
    }
    sidebarFocusBorderHandoffTargetSessionId = sessionId
    sidebarFocusBorderHandoffGeneration &+= 1
  }

  func cancelSidebarFocusBorderHandoff(reason: String) {
    guard hasSidebarFocusBorderHandoff else {
      return
    }
    let affectedSessionIds = sidebarFocusBorderHandoffAffectedSessionIds()
    let preservedSessionIds = sidebarFocusBorderHandoffPreservedSessionIds
    let targetSessionId = sidebarFocusBorderHandoffTargetSessionId
    sidebarFocusBorderHandoffPreservedSessionIds.removeAll()
    sidebarFocusBorderHandoffTargetSessionId = nil
    sidebarFocusBorderHandoffGeneration &+= 1
    cancelIneligibleFocusedPaneBorderSettlements()
    updateSidebarFocusBorderHandoffAffectedBorders(affectedSessionIds)
  }

  private var hasSidebarFocusBorderHandoff: Bool {
    !sidebarFocusBorderHandoffPreservedSessionIds.isEmpty
      || sidebarFocusBorderHandoffTargetSessionId != nil
  }

  private func preserveSidebarFocusBorderHandoffIfNeeded(
    responderSessionId: String?,
    reason: String
  ) -> Bool {
    guard hasSidebarFocusBorderHandoff else {
      return false
    }
    if let responderSessionId,
      let targetSessionId = sidebarFocusBorderHandoffTargetSessionId,
      responderSessionId != targetSessionId
    {
      cancelSidebarFocusBorderHandoff(
        reason: "unexpectedResponder.\(reason).\(responderSessionId)")
      return false
    }
    return true
  }

  private func completeSidebarFocusBorderHandoffIfTargetFocused(
    sessionId: String,
    reason: String
  ) -> Bool {
    guard hasSidebarFocusBorderHandoff,
      sidebarFocusBorderHandoffTargetSessionId == sessionId,
      currentResponderSessionId() == sessionId
    else {
      return false
    }
    superview?.layoutSubtreeIfNeeded()
    layoutSubtreeIfNeeded()
    let isEligible = isFocusedPaneBorderEligible(for: sessionId)
    let isGeometrySettled = isEligible && isFocusedPaneBorderGeometrySettled(for: sessionId)
    guard isEligible, isGeometrySettled else {
      if isEligible {
        scheduleFocusedPaneBorderSettlementIfNeeded(
          for: sessionId,
          reason: "sidebarFocusBorderHandoff.\(reason)")
      }
      return false
    }
    let affectedSessionIds = sidebarFocusBorderHandoffAffectedSessionIds()
    let preservedSessionIds = sidebarFocusBorderHandoffPreservedSessionIds
    sidebarFocusBorderHandoffPreservedSessionIds.removeAll()
    sidebarFocusBorderHandoffTargetSessionId = nil
    sidebarFocusBorderHandoffGeneration &+= 1
    scheduledFocusedPaneBorderSettlementSessionIds.removeAll()
    focusedPaneBorderSettledSessionIds = [sessionId]
    focusedPaneBorderSettlementGeneration &+= 1
    return true
  }

  private func shouldShowSidebarFocusBorderHandoffBorder(for sessionId: String) -> Bool {
    guard hasSidebarFocusBorderHandoff,
      isSidebarFocusBorderHandoffDrawable(sessionId: sessionId)
    else {
      return false
    }
    if let targetSessionId = sidebarFocusBorderHandoffTargetSessionId,
      currentResponderSessionId() == targetSessionId
    {
      return sessionId == targetSessionId
    }
    return sidebarFocusBorderHandoffPreservedSessionIds.contains(sessionId)
  }

  private func isSidebarFocusBorderHandoffDrawable(sessionId: String) -> Bool {
    if commandsPanelActiveSessionIds.contains(sessionId) {
      return commandsPanelIsVisible || commandsPanelFocusedSessionId == sessionId
    }
    return activeSessionIds.contains(sessionId)
      || isPlaceholderPaneSession(sessionId)
      || sessions[sessionId] != nil
      || webPaneSessions[sessionId] != nil
      || sleepingPanePlaceholderSessions[sessionId] != nil
  }

  private func sidebarFocusBorderHandoffAffectedSessionIds() -> Set<String> {
    var sessionIds = sidebarFocusBorderHandoffPreservedSessionIds
    if let targetSessionId = sidebarFocusBorderHandoffTargetSessionId {
      sessionIds.insert(targetSessionId)
    }
    return sessionIds
  }

  private func updateSidebarFocusBorderHandoffAffectedBorders(_ sessionIds: Set<String>) {
    for sessionId in sessionIds {
      updateTerminalOrPlaceholderBorder(for: sessionId)
    }
  }

  private func updateSleepingPanePlaceholderBorder(for sessionId: String) {
    guard let session = sleepingPanePlaceholderSessions[sessionId] else {
      return
    }
    session.titleBarView.setState(activity: sessionActivities[sessionId])
    session.titleBarView.setTabActivities(sessionActivities)
    session.titleBarView.setTabZmxInactiveSessionIds(zmxInactiveSessionIds)
    session.titleBarView.setTabDelayedSendRemainingLabels(sessionDelayedSendRemainingLabels)
    session.titleBarView.setTabIdentityIcons(
      faviconDataUrls: sessionFaviconDataUrls,
      agentIconDataUrls: sessionAgentIconDataUrls,
      agentIconColors: sessionAgentIconColors)
    let titleBarFocused = focusedSessionId == sessionId
    let isFocusedBorder = shouldShowFocusedPaneBorder(for: sessionId)
    let isAttention = attentionSessionIds.contains(sessionId)
    session.titleBarView.setFocusedPane(titleBarFocused)
    session.borderView.setState(
      isFocused: isFocusedBorder,
      isAttention: isAttention)
    scheduleFocusedPaneBorderSettlementIfNeeded(for: sessionId, reason: "updateSleepingPanePlaceholderBorder")
  }

  private func updateTerminalBorder(for sessionId: String) {
    if let session = webPaneSessions[sessionId] {
      let isActive = activeSessionIds.contains(sessionId)
      setHidden(!isActive, for: session.hostView)
      setHidden(!isActive, for: session.titleBarView)
      setHidden(!isActive, for: session.borderView)
      session.titleBarView.setState(activity: sessionActivities[sessionId])
      session.titleBarView.setTabActivities(sessionActivities)
      session.titleBarView.setTabZmxInactiveSessionIds(zmxInactiveSessionIds)
      session.titleBarView.setTabDelayedSendRemainingLabels(sessionDelayedSendRemainingLabels)
      session.titleBarView.setTabIdentityIcons(
        faviconDataUrls: sessionFaviconDataUrls,
        agentIconDataUrls: sessionAgentIconDataUrls,
        agentIconColors: sessionAgentIconColors)
      let titleBarFocused = focusedSessionId == sessionId
      let isFocusedBorder = shouldShowFocusedPaneBorder(for: sessionId)
      let isAttention = attentionSessionIds.contains(sessionId)
      session.titleBarView.setFocusedPane(titleBarFocused)
      session.borderView.setState(
        isFocused: isFocusedBorder,
        isAttention: isAttention
      )
      scheduleFocusedPaneBorderSettlementIfNeeded(for: sessionId, reason: "updateTerminalBorder.web")
      return
    }

    guard let session = sessions[sessionId] else {
      return
    }
    let isCommandActive = commandsPanelActiveSessionIds.contains(sessionId)
    let isActive = activeSessionIds.contains(sessionId) || isCommandActive
    setHidden(!isActive, for: session.titleBarView)
    setHidden(!isActive || session.view.searchState == nil, for: session.searchBarView)
    setHidden(!isActive, for: session.borderView)
    session.titleBarView.setState(
      activity: sessionActivities[sessionId]
    )
    session.titleBarView.setTabActivities(sessionActivities)
    session.titleBarView.setTabZmxInactiveSessionIds(zmxInactiveSessionIds)
    session.titleBarView.setTabDelayedSendRemainingLabels(sessionDelayedSendRemainingLabels)
    session.titleBarView.setTabIdentityIcons(
      faviconDataUrls: sessionFaviconDataUrls,
      agentIconDataUrls: sessionAgentIconDataUrls,
      agentIconColors: sessionAgentIconColors)
    let isCommandFocused = isCommandActive && commandPanelFocusedResponderSessionId() == sessionId
    let titleBarFocused = focusedSessionId == sessionId || isCommandFocused
    let isFocusedBorder = shouldShowFocusedPaneBorder(for: sessionId)
    let isAttention = attentionSessionIds.contains(sessionId)
    session.titleBarView.setFocusedPane(titleBarFocused)
    session.borderView.setState(
      isFocused: isFocusedBorder,
      isAttention: isAttention
    )
    scheduleFocusedPaneBorderSettlementIfNeeded(for: sessionId, reason: "updateTerminalBorder.terminal")
  }

  private func shouldShowFocusedPaneBorder(for sessionId: String) -> Bool {
    /**
     CDXC:NativePaneResize 2026-05-11-09:48
     Focused pane borders were temporarily suppressed while diagnosing split
     resize misses from the focused pane side. That test did not change the
     failure, so keep the selected-pane border enabled and fix resize event
     ownership instead of hiding focus chrome.

     CDXC:NativePaneChrome 2026-05-15-08:08:
     Earlier single-pane workspaces suppressed active pane borders because focus
     chrome was used only for split disambiguation. That constraint is retained
     here as historical context because the 2026-06-13 typing-target rule below
     intentionally supersedes it.

     CDXC:NativePaneChrome 2026-06-13-22:17:
     The focused border must literally mean keyboard input routes to this pane.
     Show it for single-pane Agents layouts and Source/Browser/Kanban companion
     panes only when AppKit's live first responder maps to the same selected
     pane; hide it when typing belongs to project-editor, sidebar, titlebar, or
     modal chrome even if sidebar selection still points at a terminal.

     CDXC:NativePaneChrome 2026-06-13-23:19:
     The outline must not animate in from stale pane geometry. Require a
     deferred settled pass after focus/layout changes so the border appears only
     once the pane frame is valid and still matches the live typing target.
     */
    if shouldShowSidebarFocusBorderHandoffBorder(for: sessionId) {
      return true
    }
    guard focusedPaneBorderSettledSessionIds.contains(sessionId) else {
      return false
    }
    return isFocusedPaneBorderEligible(for: sessionId)
  }

  private func isFocusedPaneBorderEligible(for sessionId: String) -> Bool {
    let isCommandPanelSession = commandsPanelActiveSessionIds.contains(sessionId)
    if isCommandPanelSession {
      return commandsPanelFocusedSessionId == sessionId
        && commandPanelFocusedResponderSessionId() == sessionId
    }
    guard !commandPanelOwnsResponder(),
      focusedSessionId == sessionId,
      currentResponderSessionId() == sessionId
    else {
      return false
    }
    if activeProjectEditorId != nil,
      projectEditorCompanionIsVisible,
      projectEditorCompanionSessionId == sessionId
    {
      return true
    }
    return activeSessionIds.contains(sessionId) || isPlaceholderPaneSession(sessionId)
  }

  private func invalidateFocusedPaneBorderSettlement(reason: String) {
    guard !focusedPaneBorderSettledSessionIds.isEmpty
      || !scheduledFocusedPaneBorderSettlementSessionIds.isEmpty
    else {
      return
    }
    focusedPaneBorderSettledSessionIds.removeAll()
    scheduledFocusedPaneBorderSettlementSessionIds.removeAll()
    focusedPaneBorderSettlementGeneration &+= 1
  }

  private func cancelIneligibleFocusedPaneBorderSettlements() {
    let nextSettledSessionIds = focusedPaneBorderSettledSessionIds.filter {
      isFocusedPaneBorderEligible(for: $0)
        || shouldShowSidebarFocusBorderHandoffBorder(for: $0)
    }
    let nextScheduledSessionIds = scheduledFocusedPaneBorderSettlementSessionIds.filter {
      isFocusedPaneBorderEligible(for: $0)
        || shouldShowSidebarFocusBorderHandoffBorder(for: $0)
    }
    guard nextSettledSessionIds.count != focusedPaneBorderSettledSessionIds.count
      || nextScheduledSessionIds.count != scheduledFocusedPaneBorderSettlementSessionIds.count
    else {
      return
    }
    focusedPaneBorderSettledSessionIds = Set(nextSettledSessionIds)
    scheduledFocusedPaneBorderSettlementSessionIds = Set(nextScheduledSessionIds)
    focusedPaneBorderSettlementGeneration &+= 1
  }

  private func scheduleFocusedPaneBorderSettlementIfNeeded(for sessionId: String, reason: String) {
    let isEligible = isFocusedPaneBorderEligible(for: sessionId)
    let isAlreadySettled = focusedPaneBorderSettledSessionIds.contains(sessionId)
    let isAlreadyScheduled = scheduledFocusedPaneBorderSettlementSessionIds.contains(sessionId)
    guard isEligible, !isAlreadySettled, !isAlreadyScheduled else {
      return
    }
    scheduledFocusedPaneBorderSettlementSessionIds.insert(sessionId)
    let generation = focusedPaneBorderSettlementGeneration
    DispatchQueue.main.async { [weak self] in
      guard let self else {
        return
      }
      guard self.focusedPaneBorderSettlementGeneration == generation,
        self.scheduledFocusedPaneBorderSettlementSessionIds.contains(sessionId)
      else {
        return
      }
      self.superview?.layoutSubtreeIfNeeded()
      self.layoutSubtreeIfNeeded()
      self.scheduledFocusedPaneBorderSettlementSessionIds.remove(sessionId)
      let isEligibleAfterLayout = self.isFocusedPaneBorderEligible(for: sessionId)
      let isGeometrySettledAfterLayout =
        isEligibleAfterLayout && self.isFocusedPaneBorderGeometrySettled(for: sessionId)
      guard isEligibleAfterLayout, isGeometrySettledAfterLayout else {
        return
      }
      self.focusedPaneBorderSettledSessionIds = [sessionId]
      self.updateAllTerminalBorders()
    }
  }

  private func isFocusedPaneBorderGeometrySettled(for sessionId: String) -> Bool {
    if let session = sessions[sessionId] {
      return isPaneBorderGeometrySettled(
        borderLayer: session.borderView,
        containerView: session.containerView)
    }
    if let session = webPaneSessions[sessionId] {
      return isPaneBorderGeometrySettled(
        borderLayer: session.borderView,
        containerView: session.containerView)
    }
    if let session = sleepingPanePlaceholderSessions[sessionId] {
      return isPaneBorderGeometrySettled(
        borderLayer: session.borderView,
        containerView: session.containerView)
    }
    return false
  }

  private func isPaneBorderGeometrySettled(
    borderLayer: TerminalPaneBorderLayer,
    containerView: TerminalPaneLeafContainerView
  ) -> Bool {
    if borderLayer.superlayer === layer {
      return !borderLayer.isHidden && borderLayer.frame.width > 1 && borderLayer.frame.height > 1
    }
    guard let containerLayer = containerView.layer,
      borderLayer.superlayer === containerLayer,
      containerView.window != nil,
      !isViewHiddenFromWindow(containerView),
      containerView.bounds.width > 1,
      containerView.bounds.height > 1,
      !borderLayer.isHidden
    else {
      return false
    }
    return rectsMatch(borderLayer.frame, containerView.bounds)
  }

  private func commandPanelOwnsResponder() -> Bool {
    commandPanelFocusedResponderSessionId() != nil
  }

  private func commandPanelFocusedResponderSessionId() -> String? {
    guard let responderSessionId = currentResponderSessionId(),
      commandsPanelActiveSessionIds.contains(responderSessionId)
    else {
      return nil
    }
    return responderSessionId
  }

  private func keyboardRouteDebugPayload(
    surfaceSessionId: String?,
    event: NSEvent? = nil
  ) -> [String: Any] {
    let responderSessionId = currentResponderSessionId()
    var mismatchTypes: [String] = []
    if let surfaceSessionId, let focusedSessionId, surfaceSessionId != focusedSessionId {
      mismatchTypes.append("surfaceSessionDiffersFromFocusRing")
    }
    if let responderSessionId, let focusedSessionId, responderSessionId != focusedSessionId {
      mismatchTypes.append("firstResponderDiffersFromFocusRing")
    }
    if let surfaceSessionId, let responderSessionId, surfaceSessionId != responderSessionId {
      mismatchTypes.append("surfaceSessionDiffersFromFirstResponder")
    }

    var payload: [String: Any] = [
      "activeProjectEditorId": nullableString(activeProjectEditorId),
      "activeSessionIds": Array(activeSessionIds).sorted(),
      "focusedSessionId": nullableString(focusedSessionId),
      "lastEmittedFocusedSessionId": nullableString(lastEmittedFocusedSessionId),
      "mismatchTypes": mismatchTypes,
      "poppedOutSessionIds": Array(poppedOutSessionIds).sorted(),
      "responder": responderSnapshot(),
      "responderMatchesFocusedSession": nullableBool(
        responderSessionId.flatMap { responder in focusedSessionId.map { responder == $0 } }),
      "responderSessionId": nullableString(responderSessionId),
      "surfaceMatchesFocusedSession": nullableBool(
        surfaceSessionId.flatMap { surface in focusedSessionId.map { surface == $0 } }),
      "surfaceMatchesResponderSession": nullableBool(
        surfaceSessionId.flatMap { surface in responderSessionId.map { surface == $0 } }),
      "surfaceSessionId": nullableString(surfaceSessionId),
      "visibleSessionIds": orderedVisibleSessionIds(),
      "windowIsKey": window?.isKeyWindow ?? false,
      "windowNumber": window?.windowNumber ?? 0,
    ]

    if let event {
      payload["charactersIgnoringModifiersLength"] = event.charactersIgnoringModifiers?.count ?? 0
      payload["charactersLength"] = event.characters?.count ?? 0
      payload["eventTimestamp"] = event.timestamp
      payload["eventWindowNumber"] = event.window?.windowNumber ?? 0
      payload["isARepeat"] = event.isARepeat
      payload["keyCode"] = Int(event.keyCode)
      payload["modifierFlags"] = Self.keyboardModifierNames(event.modifierFlags)
    }

    return payload
  }

  private func focusedSurfaceSessionIds() -> [String] {
    sessions.keys.sorted().compactMap { sessionId in
      guard sessions[sessionId]?.view.focused == true else {
        return nil
      }
      return sessionId
    }
  }

  @discardableResult
  private func restorePassiveLayoutTerminalFirstResponderIfNeeded(
    previousResponderSessionId: String?,
    responderSessionIdAfterLayout: String?,
    shouldRelayout: Bool,
    commandHadFocusRequest: Bool
  ) -> Bool {
    /*
     CDXC:NativeTerminalFocus 2026-06-10-17:52:
     Passive setActiveTerminalSet relayouts must preserve the terminal AppKit first responder the user was already typing into. When removing/sleeping a neighboring pane makes AppKit drop first responder to the window shell, restore only that exact pre-layout terminal after validating it is still the selected visible target.
     */
    guard shouldRelayout,
      !commandHadFocusRequest,
      let previousResponderSessionId,
      sessions[previousResponderSessionId] != nil,
      responderSessionIdAfterLayout == nil,
      passiveLayoutDroppedFirstResponderToWorkspaceShell()
    else {
      return false
    }
    let didRestore = reinforceWorkspaceFocus(
      sessionId: previousResponderSessionId,
      reason: "setActiveTerminalSet.passiveLayoutFirstResponderDropped",
      logEventPrefix: "nativeFocusTrace.passiveLayoutFirstResponderRestore")
    if didRestore {
      rememberTerminalFirstResponderSessionId(previousResponderSessionId)
    }
    return didRestore
  }

  private func passiveLayoutDroppedFirstResponderToWorkspaceShell() -> Bool {
    guard let responder = window?.firstResponder else {
      return true
    }
    if let currentWindow = window, responder === currentWindow {
      return true
    }
    guard let responderView = responder as? NSView else {
      return false
    }
    return responderView === self
  }

  @discardableResult
  func reinforceSidebarWorkspaceFocus(sessionId: String, reason: String) -> Bool {
    reinforceWorkspaceFocus(
      sessionId: sessionId,
      reason: reason,
      logEventPrefix: "nativeFocusTrace.sidebarFocusReinforce")
  }

  func canDirectlyRestorePromptEditorFocus(sessionId rawSessionId: String) -> Bool {
    /*
     CDXC:PromptEditor 2026-06-09-11:19:
     Closing the Ctrl+G Monaco prompt editor can directly focus the launching terminal only when that native session is already the selected, visible workspace target. Logs around 2026-06-09 11:15 showed a visible launcher that was no longer selected could be overwritten by sidebar focus state after close, so hidden or deselected launchers must return through the sidebar click-equivalent focus path.

     CDXC:PromptEditor 2026-06-09-21:50:
     Accept gxserver S:P:G refs at this native focus boundary, but normalize to
     P:G before checking AppKit workspace maps because native pane state remains
     local to the current window.
     */
    let sessionId = ghostexNativeFocusSessionId(from: rawSessionId) ?? rawSessionId
    let focusTarget = workspaceFocusTarget(sessionId: sessionId)
    guard focusTarget.isExpectedSelection else {
      return false
    }
    guard let targetView = focusTarget.view, targetView.window != nil else {
      return false
    }
    return !isViewHiddenFromWindow(targetView) && !targetView.bounds.isEmpty
  }

  func isWorkspaceFocusOwnedBySession(_ rawSessionId: String) -> Bool {
    /*
     CDXC:SidebarSessionFocus 2026-06-27-21:08:
     Sidebar focus reinforcement is a repair for WebKit stealing first
     responder after a row click. Let AppDelegate skip that repair when the
     selected workspace surface already owns AppKit focus so successful
     switches settle immediately.
     */
    let sessionId = ghostexNativeFocusSessionId(from: rawSessionId) ?? rawSessionId
    let focusTarget = workspaceFocusTarget(sessionId: sessionId)
    guard focusTarget.isExpectedSelection, let targetView = focusTarget.view else {
      return false
    }
    return responder(targetView.window?.firstResponder, isInside: targetView)
  }

  @discardableResult
  func reinforceWorkspaceFocus(
    sessionId rawSessionId: String,
    reason: String,
    logEventPrefix: String = "nativeFocusTrace.workspaceFocusReinforce"
  ) -> Bool {
    /*
     CDXC:SidebarSessionFocus 2026-06-05-22:12:
     A sidebar session click must leave the clicked session ready for keyboard input. The sidebar WebKit view can regain first responder after the normal focus command, so this method performs a narrow, idempotent first-responder repair only when the requested session is still the selected visible workspace target.

     CDXC:PromptEditor 2026-06-09-09:05:
     Monaco rich prompt editor dismissal uses the same validated first-responder repair after the modal WKWebView closes. Keep the helper generic so focus restoration can target the selected visible terminal without emitting sidebar-specific diagnostics for prompt-editor saves.

     CDXC:PromptEditor 2026-06-09-21:50:
     gxserver global S:P:G refs are accepted at this boundary for prompt-editor
     return focus, but native focus repair still operates on local P:G ids.
     */
    let sessionId = ghostexNativeFocusSessionId(from: rawSessionId) ?? rawSessionId
    let focusTarget = workspaceFocusTarget(sessionId: sessionId)
    guard focusTarget.isExpectedSelection else {
      TerminalFocusDebugLog.append(
        event: "\(logEventPrefix)Skipped",
        details: [
          "activeProjectEditorId": nullableString(activeProjectEditorId),
          "commandsPanelFocusedSessionId": nullableString(commandsPanelFocusedSessionId),
          "focusedSessionId": nullableString(focusedSessionId),
          "reason": reason,
          "requestedSessionId": sessionId,
          "responder": responderSnapshot(),
          "role": focusTarget.role,
          "skipReason": focusTarget.skipReason ?? "selectionMismatch",
        ])
      return false
    }
    guard let targetView = focusTarget.view, let targetWindow = targetView.window else {
      TerminalFocusDebugLog.append(
        event: "\(logEventPrefix)Skipped",
        details: [
          "reason": reason,
          "requestedSessionId": sessionId,
          "responder": responderSnapshot(),
          "role": focusTarget.role,
          "skipReason": focusTarget.view == nil ? "missingTargetView" : "missingTargetWindow",
        ])
      return false
    }
    guard !isViewHiddenFromWindow(targetView), !targetView.bounds.isEmpty else {
      TerminalFocusDebugLog.append(
        event: "\(logEventPrefix)Skipped",
        details: [
          "boundsHeight": targetView.bounds.height,
          "boundsWidth": targetView.bounds.width,
          "reason": reason,
          "requestedSessionId": sessionId,
          "responder": responderSnapshot(),
          "role": focusTarget.role,
          "skipReason": isViewHiddenFromWindow(targetView) ? "targetHidden" : "emptyTargetBounds",
        ])
      return false
    }

    let responderBefore = targetWindow.firstResponder
    if responder(responderBefore, isInside: targetView) {
      TerminalFocusDebugLog.append(
        event: "\(logEventPrefix)AlreadyFocused",
        details: [
          "reason": reason,
          "requestedSessionId": sessionId,
          "responder": responderSnapshot(),
          "role": focusTarget.role,
        ])
      invalidateFocusedPaneBorderSettlement(reason: "\(logEventPrefix).alreadyFocused")
      updateAllTerminalBorders()
      return true
    }

    programmaticFocusDepth += 1
    let didFocus = targetWindow.makeFirstResponder(targetView)
    programmaticFocusDepth -= 1
    TerminalFocusDebugLog.append(
      event: "\(logEventPrefix)Applied",
      details: [
        "didFocus": didFocus,
        "reason": reason,
        "requestedSessionId": sessionId,
        "responderAfter": responderSnapshot(),
        "responderBeforeClass": responderBefore.map { String(describing: type(of: $0)) } ?? "nil",
        "role": focusTarget.role,
        "windowIsKey": targetWindow.isKeyWindow,
        "windowNumber": targetWindow.windowNumber,
      ])
    if didFocus || responder(targetWindow.firstResponder, isInside: targetView) {
      invalidateFocusedPaneBorderSettlement(reason: "\(logEventPrefix).applied")
      updateAllTerminalBorders()
    }
    return didFocus
  }

  private func workspaceFocusTarget(
    sessionId: String
  ) -> (view: NSView?, role: String, isExpectedSelection: Bool, skipReason: String?) {
    if activeProjectEditorId != nil,
      projectEditorCompanionIsVisible,
      projectEditorCompanionSessionId == sessionId
    {
      return (
        projectEditorCompanionFocusTargetView(sessionId: sessionId),
        "projectEditorCompanion",
        true,
        nil)
    }
    if commandsPanelActiveSessionIds.contains(sessionId), let session = sessions[sessionId] {
      return (
        session.view,
        "commandTerminal",
        commandsPanelFocusedSessionId == sessionId,
        commandsPanelFocusedSessionId == sessionId ? nil : "commandFocusMismatch")
    }
    if let session = sessions[sessionId] {
      let isExpected = focusedSessionId == sessionId && activeSessionIds.contains(sessionId)
      return (
        session.view,
        "terminal",
        isExpected,
        isExpected ? nil : "workspaceFocusMismatch")
    }
    if let session = webPaneSessions[sessionId] {
      let isExpected = focusedSessionId == sessionId && activeSessionIds.contains(sessionId)
      return (
        session.browserContentView,
        "webPane",
        isExpected,
        isExpected ? nil : "workspaceFocusMismatch")
    }
    if let session = sleepingPanePlaceholderSessions[sessionId],
      isPlaceholderPaneSession(sessionId)
    {
      let isCommandPlaceholder =
        commandsPanelIsVisible && orderedVisibleCommandPaneOwnerSessionIds().contains(sessionId)
      let isExpected = isCommandPlaceholder
        ? commandsPanelFocusedSessionId == sessionId
        : focusedSessionId == sessionId
      let role = isMountingPlaceholderSession(sessionId)
        ? "mountingPlaceholder"
        : isCommandPlaceholder ? "sleepingCommandPlaceholder" : "sleepingPlaceholder"
      return (
        session.contentView,
        role,
        isExpected,
        isExpected ? nil : "placeholderFocusMismatch")
    }
    return (nil, "missing", false, "missingSession")
  }

  private func isViewHiddenFromWindow(_ view: NSView) -> Bool {
    var current: NSView? = view
    while let candidate = current {
      if candidate.isHidden {
        return true
      }
      current = candidate.superview
    }
    return false
  }

  private func responder(_ responder: NSResponder?, isInside view: NSView) -> Bool {
    guard responder !== view else {
      return true
    }
    guard let responderView = responder as? NSView else {
      return false
    }
    return responderView === view || responderView.isDescendant(of: view)
  }

  func activationDebugSnapshot() -> [String: Any] {
    /**
     CDXC:FocusStealDiagnostics 2026-05-15-10:54:
     App activation can steal focus without changing the selected terminal session.
     Expose a compact workspace snapshot for native lifecycle logs so later repros can compare selected session, first responder, visible panes, and Ghostty focused flags at the exact app activation boundary.
     */
    return [
      "activeProjectEditorId": nullableString(activeProjectEditorId),
      "activeSessionIds": Array(activeSessionIds).sorted(),
      "commandsPanelFocusedSessionId": nullableString(commandsPanelFocusedSessionId),
      "focusedSessionId": nullableString(focusedSessionId),
      "focusedSurfaceSessionIds": focusedSurfaceSessionIds(),
      "lastEmittedFocusedSessionId": nullableString(lastEmittedFocusedSessionId),
      "responder": responderSnapshot(),
      "responderSessionId": nullableString(currentResponderSessionId()),
      "visibleSessionIds": orderedVisibleSessionIds(),
      "windowIsKey": window?.isKeyWindow ?? false,
      "windowNumber": window?.windowNumber ?? 0,
    ]
  }

  private func focusSurfaceStateSnapshot() -> [[String: Any]] {
    sessions.keys.sorted().compactMap { sessionId in
      guard let session = sessions[sessionId] else {
        return nil
      }
      let surfaceWindow = session.view.window
      return [
        "borderFocused": shouldShowFocusedPaneBorder(for: sessionId),
        "frame": describeFrame(session.view.frame),
        "isActive": activeSessionIds.contains(sessionId),
        "isFirstResponder": surfaceWindow?.firstResponder === session.view,
        "isPoppedOut": poppedOutSessionIds.contains(sessionId),
        "scrollViewHidden": session.scrollView.isHidden,
        "sessionId": sessionId,
        "surfaceFocusedFlag": session.view.focused,
        "surfaceWindowIsKey": surfaceWindow?.isKeyWindow ?? false,
        "surfaceWindowNumber": surfaceWindow?.windowNumber ?? 0,
        "titleBarFocused": focusedSessionId == sessionId,
        "titleBarHidden": session.titleBarView.isHidden,
      ]
    }
  }

  private func logFocusSurfaceState(
    event: String,
    reason: String,
    details: [String: Any] = [:]
  ) {
    guard NativeDiagnosticLogging.isScenarioEnabled(.nativeTerminalFocus) else {
      return
    }
    let surfaceFocusIds = focusedSurfaceSessionIds()
    var payload = details
    /**
     CDXC:NativeTerminalStartupFocus 2026-05-11-12:31
     Startup focus repros need one snapshot that compares the sidebar-selected
     pane, AppKit first responder, and Ghostty's per-surface focused flag. Log
     this only through the native.terminal.focus scenario so normal terminal startup remains quiet.
    */
    payload["activeSessionIds"] = Array(activeSessionIds).sorted()
    payload["focusedSessionId"] = nullableString(focusedSessionId)
    payload["focusedSurfaceCount"] = surfaceFocusIds.count
    payload["focusedSurfaceSessionIds"] = surfaceFocusIds
    payload["lastEmittedFocusedSessionId"] = nullableString(lastEmittedFocusedSessionId)
    payload["reason"] = reason
    payload["responder"] = responderSnapshot()
    payload["surfaces"] = focusSurfaceStateSnapshot()
    payload["visibleSessionIds"] = orderedVisibleSessionIds()
    payload["workspaceWindowIsKey"] = window?.isKeyWindow ?? false
    payload["workspaceWindowNumber"] = window?.windowNumber ?? 0
    TerminalFocusDebugLog.append(event: event, details: payload)
  }

  private static func keyboardModifierNames(_ flags: NSEvent.ModifierFlags) -> [String] {
    let normalizedFlags = flags.intersection(.deviceIndependentFlagsMask)
    var names: [String] = []
    if normalizedFlags.contains(.capsLock) {
      names.append("capsLock")
    }
    if normalizedFlags.contains(.shift) {
      names.append("shift")
    }
    if normalizedFlags.contains(.control) {
      names.append("control")
    }
    if normalizedFlags.contains(.option) {
      names.append("option")
    }
    if normalizedFlags.contains(.command) {
      names.append("command")
    }
    if normalizedFlags.contains(.numericPad) {
      names.append("numericPad")
    }
    if normalizedFlags.contains(.help) {
      names.append("help")
    }
    if normalizedFlags.contains(.function) {
      names.append("function")
    }
    return names
  }

  private static func textInputLength(_ value: Any) -> Int {
    if let string = value as? String {
      return string.count
    }
    if let attributedString = value as? NSAttributedString {
      return attributedString.string.count
    }
    return 0
  }

  private func responderSnapshot() -> [String: Any] {
    guard let responder = window?.firstResponder else {
      return [
        "className": "nil",
        "sessionId": NSNull(),
      ]
    }
    return [
      "className": String(describing: type(of: responder)),
      "sessionId": nullableString(sessionId(containing: responder)),
    ]
  }

  private func currentResponderSessionId() -> String? {
    guard let responder = window?.firstResponder else {
      return nil
    }
    return sessionId(containing: responder)
  }

  func nativeHotkeySourceSessionId() -> String? {
    /**
     CDXC:PaneFocus 2026-06-13-21:47:
     Directional native hotkeys should use the pane that owns AppKit first
     responder as their source. This keeps Cmd+Opt+Arrow aligned with the
     terminal the user can type into when the Commands pane and workspace panes
     both have remembered focus state.
     */
    let candidates = [
      currentResponderSessionId(),
      recentTerminalUserInputSessionId(),
      focusedSessionId,
      commandsPanelFocusedSessionId,
      lastEmittedFocusedSessionId,
    ].compactMap { $0 }
    return candidates.first { sessionId in
      let isKnownPane =
        sessions[sessionId] != nil
        || webPaneSessions[sessionId] != nil
        || sleepingPanePlaceholderSessions[sessionId] != nil
      return isKnownPane
        && (activeSessionIds.contains(sessionId) || commandsPanelActiveSessionIds.contains(sessionId))
    }
  }

  @discardableResult
  func handleFocusedChromiumZoomShortcut(_ event: NSEvent) -> Bool {
    guard event.type == .keyDown,
      let shortcut = Self.chromiumZoomShortcut(for: event),
      let target = focusedChromiumZoomTarget()
    else {
      return false
    }
    /*
     CDXC:ChromiumBrowserPanes 2026-06-10-15:55:
     Cmd+=, Cmd+-, and Cmd+0 should behave like Chrome for the currently focused embedded Chromium pane only. Resolve focus from the live AppKit responder first so side-by-side CEF panes do not share one app-wide zoom command.
     */
    switch shortcut {
    case .zoomIn:
      target.chromiumView.zoomIn()
    case .zoomOut:
      target.chromiumView.zoomOut()
    case .reset:
      target.chromiumView.resetZoom()
    }
    target.hostView?.refreshPageZoomState(reason: "keyboardShortcut")
    DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) { [weak targetHostView = target.hostView] in
      targetHostView?.refreshPageZoomState(reason: "keyboardShortcutDelayed")
    }
    return true
  }

  @discardableResult
  func handleFocusedChromiumFindShortcut(_ event: NSEvent) -> Bool {
    guard event.type == .keyDown,
      let shortcut = Self.chromiumFindShortcut(for: event),
      let target = focusedChromiumFindTarget()
    else {
      return false
    }
    if isSourceProjectEditorChromiumFindTarget(target) {
      /*
       CDXC:BrowserSearch 2026-06-24-13:13:
       Source view is a CEF host for embedded VS Code, but Cmd+F must stay with VS Code's editor search instead of Ghostex's browser find bar.
       Return false so AppKit continues dispatching the key event to code-server.
       */
      return false
    }
    /*
     CDXC:BrowserSearch 2026-06-13-00:00:
     Cmd+F, Cmd+G, and Cmd+Shift+G in focused CEF panes should use Chromium page search for the current browser pane only.
     Resolve the host view before handling the key so terminal search, app modals, and non-CEF text inputs keep their existing shortcut behavior.
     */
    switch shortcut {
    case .open:
      return target.hostView.openBrowserFind(reason: "keyboardShortcut")
    case .next:
      return target.hostView.findNextInBrowser()
    case .previous:
      return target.hostView.findPreviousInBrowser()
    }
  }

  private static func chromiumZoomShortcut(for event: NSEvent) -> ChromiumZoomShortcut? {
    let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
    guard flags.contains(.command),
      flags.isDisjoint(with: [.control, .option])
    else {
      return nil
    }
    switch event.keyCode {
    case 24:
      return .zoomIn
    case 27:
      return .zoomOut
    case 29 where !flags.contains(.shift):
      return .reset
    default:
      return nil
    }
  }

  private static func chromiumFindShortcut(for event: NSEvent) -> ChromiumFindShortcut? {
    let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
    guard flags.contains(.command),
      flags.isDisjoint(with: [.control, .option])
    else {
      return nil
    }
    switch event.charactersIgnoringModifiers?.lowercased() {
    case "f":
      return flags.contains(.shift) ? nil : .open
    case "g":
      return flags.contains(.shift) ? .previous : .next
    default:
      return nil
    }
  }

  private func focusedChromiumZoomTarget() -> (chromiumView: GhostexCEFBrowserView, hostView: WebPaneHostView?)? {
    if let responderView = window?.firstResponder as? NSView {
      guard responderView === self || responderView.isDescendant(of: self) else {
        return nil
      }
      if let hostView = chromiumHostView(containing: responderView), let chromiumView = hostView.hostedChromiumView {
        return (chromiumView, hostView)
      }
      if let chromiumView = chromiumBrowserView(containing: responderView) {
        return (chromiumView, hostView(for: chromiumView))
      }
    }
    if let responderSessionId = currentResponderSessionId() {
      if let session = webPaneSessions[responderSessionId], let chromiumView = session.chromiumView {
        return (chromiumView, session.hostView)
      }
      return nil
    }
    let candidateSessionIds = [
      focusedSessionId,
    ].compactMap { $0 }
    for sessionId in candidateSessionIds {
      if let session = webPaneSessions[sessionId], let chromiumView = session.chromiumView {
        return (chromiumView, session.hostView)
      }
    }
    if let activeProjectEditorId,
      let session = projectEditorPaneSessions[activeProjectEditorId],
      let chromiumView = session.chromiumView
    {
      return (chromiumView, session.hostView)
    }
    return nil
  }

  private func focusedChromiumFindTarget() -> (chromiumView: GhostexCEFBrowserView, hostView: WebPaneHostView)? {
    guard let target = focusedChromiumZoomTarget(), let hostView = target.hostView else {
      return nil
    }
    return (target.chromiumView, hostView)
  }

  private func isSourceProjectEditorChromiumFindTarget(
    _ target: (chromiumView: GhostexCEFBrowserView, hostView: WebPaneHostView)
  ) -> Bool {
    projectEditorPaneSessions.values.contains { session in
      session.mode == "code"
        && (
          session.hostView === target.hostView
            || session.chromiumView.map { $0 === target.chromiumView } == true
        )
    }
  }

  private func chromiumHostView(containing responderView: NSView) -> WebPaneHostView? {
    var currentView: NSView? = responderView
    while let view = currentView {
      if let hostView = view as? WebPaneHostView {
        return hostView
      }
      currentView = view.superview
    }
    return nil
  }

  private func chromiumBrowserView(containing responderView: NSView) -> GhostexCEFBrowserView? {
    var currentView: NSView? = responderView
    while let view = currentView {
      if let chromiumView = view as? GhostexCEFBrowserView {
        return chromiumView
      }
      currentView = view.superview
    }
    return nil
  }

  private func hostView(for chromiumView: GhostexCEFBrowserView) -> WebPaneHostView? {
    for session in webPaneSessions.values where session.chromiumView.map({ $0 === chromiumView }) == true {
      return session.hostView
    }
    for (projectId, _) in projectEditorPaneSessions {
      if let hostView = projectEditorHostView(projectId: projectId, chromiumView: chromiumView) {
        return hostView
      }
    }
    return nil
  }

  func passiveSidebarReturnFocusTerminalSessionId() -> String? {
    /**
     CDXC:NativeTerminalFocus 2026-06-09-23:14:
     Sidebar hydration and patch updates are background UI maintenance, not app-modal dismissal. Passive sidebar first-responder recovery must use the live or last real terminal first responder so stale command-panel focus state cannot receive keyboard focus when the user was typing in a workspace terminal.

     CDXC:NativeTerminalFocus 2026-06-13-16:32:
     If terminal key input arrived immediately before passive sidebar WKWebView churn, that input terminal is the only correct recovery target. Prefer it before querying the current AppKit responder because the first-responder callback can still expose stale terminal state while reporting SidebarWebView as the new responder.
     */
    let responderSessionId = currentResponderSessionId()
    let recentUserInputSessionId = recentTerminalUserInputSessionId()
    let candidates = [
      activeWorkspaceTerminalCandidate(recentUserInputSessionId),
      commandPanelTerminalCandidate(recentUserInputSessionId),
      activeWorkspaceTerminalCandidate(responderSessionId),
      commandPanelTerminalCandidate(responderSessionId),
      activeWorkspaceTerminalCandidate(lastTerminalFirstResponderSessionId),
      commandPanelTerminalCandidate(lastTerminalFirstResponderSessionId),
      activeWorkspaceTerminalCandidate(focusedSessionId),
      activeWorkspaceTerminalCandidate(lastEmittedFocusedSessionId),
    ].compactMap { $0 }
    return candidates.first
  }

  func appModalReturnFocusTerminalSessionId() -> String? {
    /**
     CDXC:AppModals 2026-05-28-14:52:
     Modal dismissal must return keyboard input to the terminal that owned focus when the modal opened. Prefer the live first-responder terminal, then the command-panel and workspace focus stores, because opening a modal from sidebar or titlebar chrome can move first responder away before the selected terminal changes.
     */
    let candidates = [
      currentResponderSessionId(),
      commandsPanelFocusedSessionId,
      focusedSessionId,
      lastEmittedFocusedSessionId,
    ].compactMap { $0 }
    return candidates.first { sessionId in
      sessions[sessionId] != nil
        && (activeSessionIds.contains(sessionId) || commandsPanelActiveSessionIds.contains(sessionId))
    }
  }

  private func rememberTerminalUserInputOwner(surfaceView: GhostexGhosttySurfaceView) {
    let now = Date()
    guard let sessionId = surfaceView.ghostexSessionId,
      isActiveTerminalSession(sessionId)
    else {
      return
    }
    lastTerminalUserInputSessionId = sessionId
    lastTerminalUserInputAt = now
    rememberTerminalFirstResponderSessionId(sessionId)
  }

  private func recentTerminalUserInputSessionId(now: Date = Date()) -> String? {
    guard let sessionId = lastTerminalUserInputSessionId,
      let inputAt = lastTerminalUserInputAt,
      now.timeIntervalSince(inputAt) <= Self.passiveSidebarUserInputReturnFocusWindow,
      lastTerminalFirstResponderSessionId == sessionId
    else {
      return nil
    }
    return sessionId
  }

  private func rememberTerminalFirstResponderSessionId(_ sessionId: String?) {
    guard let sessionId,
      isActiveTerminalSession(sessionId)
    else {
      return
    }
    lastTerminalFirstResponderSessionId = sessionId
  }

  private func isActiveTerminalSession(_ sessionId: String) -> Bool {
    sessions[sessionId] != nil
      && (activeSessionIds.contains(sessionId) || commandsPanelActiveSessionIds.contains(sessionId))
  }

  private func activeWorkspaceTerminalCandidate(_ sessionId: String?) -> String? {
    guard let sessionId, sessions[sessionId] != nil, activeSessionIds.contains(sessionId) else {
      return nil
    }
    return sessionId
  }

  private func commandPanelTerminalCandidate(_ sessionId: String?) -> String? {
    guard let sessionId, sessions[sessionId] != nil, commandsPanelActiveSessionIds.contains(sessionId)
    else {
      return nil
    }
    return sessionId
  }

  private func shouldPreserveNonTerminalFirstResponder(
    forRequestedFocusSessionId requestedFocusSessionId: String
  ) -> Bool {
    NativeTerminalFocusRequestPolicy.shouldPreserveExplicitFocus(
      responderScope: explicitFocusResponderScope(),
      requestedTargetIsVisible: isPaneSessionLayoutVisible(requestedFocusSessionId)
        || isCommandPaneSessionLayoutVisible(requestedFocusSessionId))
  }

  private func explicitLayoutFocusRequestDidApply(to sessionId: String) -> Bool {
    let focusTarget = workspaceFocusTarget(sessionId: sessionId)
    guard let targetView = focusTarget.view else {
      return false
    }
    return responder(targetView.window?.firstResponder, isInside: targetView)
  }

  private func recordAppliedExplicitLayoutFocusRequestIfNeeded(
    focusRequestId: Int,
    requestedSessionId: String,
    focusSurfaceKind: String
  ) {
    guard explicitLayoutFocusRequestDidApply(to: requestedSessionId) else {
      TerminalFocusDebugLog.append(
        event: "nativeWorkspace.setActiveTerminalSet.focusSkipped",
        details: [
          "focusRequestId": focusRequestId,
          "focusSurfaceKind": focusSurfaceKind,
          "reason": "focusRequestNotApplied",
          "requestedSessionId": requestedSessionId,
          "responder": responderSnapshot(),
        ])
      return
    }
    lastAppliedLayoutFocusRequestId = focusRequestId
  }

  private func explicitFocusResponderScopeDescription() -> String {
    switch explicitFocusResponderScope() {
    case .noResponder:
      return "noResponder"
    case .paneSession:
      return "paneSession"
    case .workspaceShell:
      return "workspaceShell"
    case .externalChrome:
      return "externalChrome"
    case .protectedInput:
      return "protectedInput"
    case .unknownNonTerminal:
      return "unknownNonTerminal"
    }
  }

  private func explicitFocusResponderScope() -> NativeTerminalExplicitFocusResponderScope {
    guard let responder = window?.firstResponder else {
      return .noResponder
    }
    if sessionId(containing: responder) != nil {
      return .paneSession
    }
    if let currentWindow = window, responder === currentWindow {
      return .workspaceShell
    }
    guard let responderView = responder as? NSView else {
      return .unknownNonTerminal
    }
    if responderView is NSTextView || responderView is NSTextField {
      return .protectedInput
    }
    guard responderView === self || responderView.isDescendant(of: self) else {
      return .externalChrome
    }
    if responderView === self {
      return .workspaceShell
    }
    if isProtectedWorkspaceInputResponder(responderView) {
      return .protectedInput
    }
    return .unknownNonTerminal
  }

  private func isProtectedWorkspaceInputResponder(_ responderView: NSView) -> Bool {
    if let floatingEditorOverlayView,
      responderView === floatingEditorOverlayView || responderView.isDescendant(of: floatingEditorOverlayView)
    {
      return true
    }
    if projectEditorId(containing: responderView) != nil {
      return true
    }
    if responderView is NSTextView || responderView is NSTextField {
      return true
    }
    return hasWebViewAncestorInsideWorkspace(responderView)
  }

  private func hasWebViewAncestorInsideWorkspace(_ responderView: NSView) -> Bool {
    var currentView: NSView? = responderView
    while let view = currentView {
      if view is WKWebView {
        return true
      }
      if view === self {
        return false
      }
      currentView = view.superview
    }
    return false
  }

  private func sessionId(containing responder: NSResponder) -> String? {
    guard let responderView = responder as? NSView else {
      return sessions.first { _, session in responder === session.view }?.key
    }
    for (sessionId, session) in sessions {
      if responderView === session.containerView || responderView.isDescendant(of: session.containerView)
        || responderView === session.view || responderView.isDescendant(of: session.view)
      {
        return sessionId
      }
    }
    for (sessionId, session) in webPaneSessions {
      let contentView = session.browserContentView
      if responderView === session.containerView || responderView.isDescendant(of: session.containerView)
        || responderView === session.hostView || responderView.isDescendant(of: session.hostView)
        || responderView === contentView || responderView.isDescendant(of: contentView)
      {
        return sessionId
      }
    }
    for (sessionId, session) in sleepingPanePlaceholderSessions {
      if responderView === session.containerView || responderView.isDescendant(of: session.containerView)
        || responderView === session.contentView || responderView.isDescendant(of: session.contentView)
        || responderView === session.titleBarView || responderView.isDescendant(of: session.titleBarView)
      {
        return sessionId
      }
    }
    return nil
  }

  private func projectEditorId(containing responder: NSResponder) -> String? {
    guard let responderView = responder as? NSView else {
      return nil
    }
    for (projectEditorId, session) in projectEditorPaneSessions {
      let targetResponder = projectEditorFocusTargetResponder(for: session)
      let targetView = targetResponder as? NSView
      if responderView === session.hostView || responderView.isDescendant(of: session.hostView)
        || targetView.map({ responderView === $0 || responderView.isDescendant(of: $0) }) == true
      {
        return projectEditorId
      }
    }
    return nil
  }

  private func emitFocusedSessionIfNeeded(for responder: NSResponder, reason: String) {
    /**
     CDXC:NativeTerminalFocus 2026-04-26-22:22
     Only user/AppKit-originated first-responder changes should update the
     sidebar focus store. Programmatic focus calls from setActiveTerminalSet
     already came from sidebar state; echoing them back creates a feedback
     loop where each layout sync can make another pane active.
     */
    guard let focusedSessionId = sessionId(containing: responder) else {
      TerminalFocusDebugLog.append(
        event: "nativeWorkspace.focusedResponderIgnored",
        details: [
          "reason": reason,
          "responder": String(describing: type(of: responder)),
        ])
      return
    }
    guard activeSessionIds.contains(focusedSessionId)
      || commandsPanelActiveSessionIds.contains(focusedSessionId)
    else {
      TerminalFocusDebugLog.append(
        event: "nativeWorkspace.focusedInactiveSessionIgnored",
        details: [
          "activeSessionIds": Array(activeSessionIds).sorted(),
          "commandsPanelActiveSessionIds": Array(commandsPanelActiveSessionIds).sorted(),
          "reason": reason,
          "sessionId": focusedSessionId,
        ])
      return
    }
    emitFocusedSessionSelectionIfNeeded(sessionId: focusedSessionId, reason: reason)
  }

  private func emitFocusedSessionSelectionIfNeeded(sessionId focusedSessionId: String, reason: String) {
    let localFocusedSessionId = commandsPanelActiveSessionIds.contains(focusedSessionId)
      ? commandsPanelFocusedSessionId
      : self.focusedSessionId
    if lastEmittedFocusedSessionId == focusedSessionId, localFocusedSessionId == focusedSessionId {
      TerminalFocusDebugLog.append(
        event: "nativeWorkspace.terminalFocused.duplicateSkipped",
        details: [
          "reason": reason,
          "sessionId": focusedSessionId,
        ])
      return
    }
    if lastEmittedFocusedSessionId == focusedSessionId, localFocusedSessionId != focusedSessionId {
      /**
       CDXC:NativeTerminalFocus 2026-05-13-07:41
       A previous native focus emission can be followed by sidebar/layout sync
       repainting the local focused pane back to an older session. In that stale
       local state, the next matching responder focus is not a behavioral
       duplicate; re-apply and re-emit it so the border and store converge.
       */
      TerminalFocusDebugLog.append(
        event: "nativeFocusTrace.duplicateFocusWithStaleBorderState",
        details: [
          "emittedFocusedSessionId": focusedSessionId,
          "lastEmittedFocusedSessionId": nullableString(lastEmittedFocusedSessionId),
          "localFocusedSessionId": nullableString(localFocusedSessionId),
          "reason": reason,
          "responder": responderSnapshot(),
        ])
    }
    lastEmittedFocusedSessionId = focusedSessionId
    if commandsPanelActiveSessionIds.contains(focusedSessionId) {
      commandsPanelFocusedSessionId = focusedSessionId
    } else {
      self.focusedSessionId = focusedSessionId
    }
    let shouldPreserveSidebarFocusBorderHandoff =
      hasSidebarFocusBorderHandoff
        && sidebarFocusBorderHandoffTargetSessionId == focusedSessionId
        && currentResponderSessionId() == focusedSessionId
    if shouldPreserveSidebarFocusBorderHandoff {
      _ = completeSidebarFocusBorderHandoffIfTargetFocused(
        sessionId: focusedSessionId,
        reason: "emitFocusedSessionSelection.\(reason)")
    } else {
      invalidateFocusedPaneBorderSettlement(reason: "emitFocusedSessionSelection.\(reason)")
    }
    updateAllTerminalBorders()
    TerminalFocusDebugLog.append(
      event: "nativeWorkspace.terminalFocused.emitted",
      details: [
        "reason": reason,
        "sessionId": focusedSessionId,
      ])
    TerminalFocusDebugLog.append(
      event: "nativeFocusTrace.terminalFocusedEmitted",
      details: [
        "activeSessionIds": Array(activeSessionIds).sorted(),
        "commandsPanelActiveSessionIds": Array(commandsPanelActiveSessionIds).sorted(),
        "commandsPanelFocusedSessionId": nullableString(commandsPanelFocusedSessionId),
        "focusedSessionId": focusedSessionId,
        "reason": reason,
        "responder": responderSnapshot(),
        "visibleSessionIds": orderedVisibleSessionIds(),
      ])
    sendEvent(.terminalFocused(sessionId: focusedSessionId))
  }

  private func describeFrame(_ frame: CGRect) -> [String: Double] {
    [
      "height": Double(frame.height),
      "maxX": Double(frame.maxX),
      "maxY": Double(frame.maxY),
      "minX": Double(frame.minX),
      "minY": Double(frame.minY),
      "width": Double(frame.width),
    ]
  }

  private func describePoint(_ point: CGPoint) -> [String: Double] {
    [
      "x": Double(point.x),
      "y": Double(point.y),
    ]
  }

  private func describeSize(_ size: CGSize) -> [String: Double] {
    [
      "height": Double(size.height),
      "width": Double(size.width),
    ]
  }

  private static func eventTypeName(_ eventType: NSEvent.EventType) -> String {
    switch eventType {
    case .leftMouseDown: return "leftMouseDown"
    case .leftMouseDragged: return "leftMouseDragged"
    case .leftMouseUp: return "leftMouseUp"
    default: return String(describing: eventType)
    }
  }

  private func summarizeTerminalText(_ text: String) -> String {
    String(
      text.replacingOccurrences(of: "\r", with: "\\r")
        .replacingOccurrences(of: "\n", with: "\\n")
        .prefix(160))
  }

  private func nullableString(_ value: String?) -> Any {
    value ?? NSNull()
  }

  private func nullableInt(_ value: Int?) -> Any {
    value ?? NSNull()
  }

  private func nullableBool(_ value: Bool?) -> Any {
    value ?? NSNull()
  }

  private static func clampedPaneGap(_ value: Double?) -> CGFloat {
    guard let value, value.isFinite else {
      return defaultPaneGap
    }
    return CGFloat(min(48, max(0, value)))
  }

  private static func clampedTerminalPanePaddingPx(_ value: Double?) -> CGFloat {
    guard let value, value.isFinite else {
      return 0
    }
    return CGFloat(min(64, max(0, value.rounded())))
  }

  private func clampedCommandsPanelHeightRatio(_ value: Double?) -> CGFloat {
    guard let value, value.isFinite else {
      return defaultCommandsPanelHeightRatio(for: bounds.height)
    }
    return Self.clampedCommandsPanelHeightRatio(value)
  }

  private func defaultCommandsPanelHeightRatio(for workspaceHeight: CGFloat) -> CGFloat {
    Self.defaultCommandsPanelHeightRatio(
      for: workspaceHeight,
      defaultHeightPoints: commandsPanelDefaultHeightPoints)
  }

  private static func defaultCommandsPanelHeightRatio(
    for workspaceHeight: CGFloat,
    defaultHeightPoints: CGFloat = fallbackCommandsPanelDefaultHeightPoints
  ) -> CGFloat {
    let resolvedWorkspaceHeight =
      workspaceHeight > 0 ? workspaceHeight : defaultCommandsPanelReferenceWorkspaceHeight
    let minimumHeight = resolvedWorkspaceHeight * minimumCommandsPanelHeightRatio
    let maximumHeight = max(minimumHeight, resolvedWorkspaceHeight * maximumCommandsPanelHeightRatio)
    let defaultHeight = min(
      max(defaultHeightPoints, minimumHeight),
      maximumHeight)
    return clampedCommandsPanelHeightRatio(Double(defaultHeight / resolvedWorkspaceHeight))
  }

  private static func clampedCommandsPanelHeightRatio(_ value: Double) -> CGFloat {
    CGFloat(
      min(
        Double(maximumCommandsPanelHeightRatio),
        max(Double(minimumCommandsPanelHeightRatio), value)))
  }

  private func workspaceBackgroundColor(_ value: String?) -> NSColor {
    guard let color = Self.parseHexColor(value?.trimmingCharacters(in: .whitespacesAndNewlines)) else {
      return defaultWorkspaceBackgroundColor
    }
    return color
  }

  private static func parseHexColor(_ value: String?) -> NSColor? {
    guard let value else {
      return nil
    }
    let pattern = #"^#?([0-9a-fA-F]{6})$"#
    guard
      let match = value.range(of: pattern, options: .regularExpression),
      match == value.startIndex..<value.endIndex
    else {
      return nil
    }
    let hex = value.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
    guard let rawValue = Int(hex, radix: 16) else {
      return nil
    }
    return NSColor(
      calibratedRed: CGFloat((rawValue >> 16) & 0xff) / 255,
      green: CGFloat((rawValue >> 8) & 0xff) / 255,
      blue: CGFloat(rawValue & 0xff) / 255,
      alpha: 1
    )
  }

  private func startExitPollingIfNeeded() {
    guard exitPollTimer == nil else { return }
    exitPollTimer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in
      MainActor.assumeIsolated {
        self?.pollExitedSurfaces()
      }
    }
  }

  private func stopExitPollingIfIdle() {
    if sessions.isEmpty {
      exitPollTimer?.invalidate()
      exitPollTimer = nil
    }
  }

  private func pollExitedSurfaces() {
    let exitedSessionIds = sessions.compactMap { sessionId, session in
      session.view.processExited ? sessionId : nil
    }
    for sessionId in exitedSessionIds {
      closeTerminal(sessionId: sessionId, requestGhosttyClose: false, reason: "processExitedPoll")
    }
  }

  private func leafSessionIds(_ node: NativeTerminalLayout) -> [String] {
    switch node {
    case .leaf(let sessionId):
      return [sessionId]
    case .tabs(_, let sessionIds):
      return sessionIds
    case .split(_, _, let children):
      return children.flatMap(leafSessionIds)
    }
  }

  private func prunedLayout(removing sessionId: String, from node: NativeTerminalLayout?)
    -> NativeTerminalLayout?
  {
    guard let node else { return nil }
    switch node {
    case .leaf(let existingSessionId):
      return existingSessionId == sessionId ? nil : node
    case .tabs(let activeSessionId, let sessionIds):
      let nextSessionIds = sessionIds.filter { $0 != sessionId }
      if nextSessionIds.isEmpty {
        return nil
      }
      if nextSessionIds.count == 1 {
        return .leaf(sessionId: nextSessionIds[0])
      }
      return .tabs(
        activeSessionId: activeSessionId.flatMap { nextSessionIds.contains($0) ? $0 : nil }
          ?? nextSessionIds[0],
        sessionIds: nextSessionIds)
    case .split(let direction, let ratio, let children):
      let nextChildren = children.compactMap { prunedLayout(removing: sessionId, from: $0) }
      if nextChildren.count == 1 {
        return nextChildren[0]
      }
      return nextChildren.isEmpty
        ? nil : .split(direction: direction, ratio: ratio, children: nextChildren)
    }
  }
}

extension TerminalWorkspaceView: WKNavigationDelegate {
  func webView(_ webView: WKWebView, didStartProvisionalNavigation navigation: WKNavigation!) {
    if let sessionId = sessionId(for: webView) {
      completedWebPaneLoadSessionIds.remove(sessionId)
    }
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.navigation.start", [
      "sessionId": sessionId(for: webView) ?? NSNull(),
      "url": webView.url?.absoluteString ?? NSNull(),
    ])
  }

  func webView(_ webView: WKWebView, didCommit navigation: WKNavigation!) {
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.navigation.commit", [
      "sessionId": sessionId(for: webView) ?? NSNull(),
      "url": webView.url?.absoluteString ?? NSNull(),
    ])
  }

  func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
    let sessionId = sessionId(for: webView)
    if let sessionId {
      completedWebPaneLoadSessionIds.insert(sessionId)
    }
    updateWebPanePageMetadata(for: webView, reason: "navigationFinish")
    finishProjectEditorWebKitNavigation(for: webView, reason: "navigationFinish")
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.navigation.finish", [
      "sessionId": sessionId ?? NSNull(),
      "title": webView.title ?? NSNull(),
      "url": webView.url?.absoluteString ?? NSNull(),
    ])
  }

  func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
    if let sessionId = sessionId(for: webView) {
      completedWebPaneLoadSessionIds.remove(sessionId)
    }
    failProjectEditorWebKitNavigation(for: webView, error: error, reason: "navigationFail")
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.navigation.fail", [
      "error": error.localizedDescription,
      "errorCode": (error as NSError).code,
      "errorDomain": (error as NSError).domain,
      "sessionId": sessionId(for: webView) ?? NSNull(),
      "url": webView.url?.absoluteString ?? NSNull(),
    ])
  }

  func webView(
    _ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!,
    withError error: Error
  ) {
    if let sessionId = sessionId(for: webView) {
      completedWebPaneLoadSessionIds.remove(sessionId)
    }
    failProjectEditorWebKitNavigation(for: webView, error: error, reason: "provisionalNavigationFail")
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.navigation.provisionalFail", [
      "error": error.localizedDescription,
      "errorCode": (error as NSError).code,
      "errorDomain": (error as NSError).domain,
      "sessionId": sessionId(for: webView) ?? NSNull(),
      "url": webView.url?.absoluteString ?? NSNull(),
    ])
  }

  func webView(
    _ webView: WKWebView,
    decidePolicyFor navigationAction: WKNavigationAction,
    decisionHandler: @escaping (WKNavigationActionPolicy) -> Void
  ) {
    let requestedUrl = navigationAction.request.url
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.navigation.action", [
      "isMainFrame": navigationAction.targetFrame?.isMainFrame ?? false,
      "method": navigationAction.request.httpMethod ?? NSNull(),
      "navigationType": String(describing: navigationAction.navigationType),
      "sessionId": sessionId(for: webView) ?? NSNull(),
      "targetFrameMissing": navigationAction.targetFrame == nil,
      "url": requestedUrl?.absoluteString ?? NSNull(),
    ])
    if navigationAction.targetFrame == nil,
      let requestedUrl,
      requestedUrl.scheme == "http" || requestedUrl.scheme == "https"
    {
      /**
       CDXC:BrowserPanes 2026-05-03-03:59
       Embedded browser panes are single-pane browsers. Links that ask WebKit
       for a new tab/window, including many search-result links, must retarget
       into the existing WKWebView because ghostex does not create overlay windows
       for browser-pane navigation.
       */
      NativeT3CodePaneReproLog.append("nativeWorkspace.browserPane.navigation.retargetBlank", [
        "sessionId": sessionId(for: webView) ?? NSNull(),
        "url": requestedUrl.absoluteString,
      ])
      webView.load(navigationAction.request)
      decisionHandler(.cancel)
      return
    }
    decisionHandler(.allow)
  }

  func webView(
    _ webView: WKWebView,
    decidePolicyFor navigationResponse: WKNavigationResponse,
    decisionHandler: @escaping (WKNavigationResponsePolicy) -> Void
  ) {
    let httpResponse = navigationResponse.response as? HTTPURLResponse
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.navigation.response", [
      "isForMainFrame": navigationResponse.isForMainFrame,
      "mimeType": navigationResponse.response.mimeType ?? NSNull(),
      "sessionId": sessionId(for: webView) ?? NSNull(),
      "statusCode": httpResponse?.statusCode ?? 0,
      "url": navigationResponse.response.url?.absoluteString ?? NSNull(),
    ])
    decisionHandler(.allow)
  }

  func webViewWebContentProcessDidTerminate(_ webView: WKWebView) {
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.process.terminated", [
      "sessionId": sessionId(for: webView) ?? NSNull(),
      "url": webView.url?.absoluteString ?? NSNull(),
    ])
  }
}

extension TerminalWorkspaceView: WKUIDelegate {
