    drawIdentityIconIfNeeded()
    drawTitle()
    if !isTabHovered {
      drawActivityIndicatorIfNeeded()
      drawCommandSeparatorIfNeeded()
      return
    }
    /**
     CDXC:PaneTabs 2026-05-11-02:02
