  var onTabSleepRequested: ((String, PaneTabSleepScope) -> Void)?
  var onTabFocusRequested: ((String) -> Void)?
  var onTabActionRequested: ((String, TerminalTitleBarAction) -> Void)?

  override var isFlipped: Bool {
    true
