  func setTitle(_ title: String) {
    if titleLabel.stringValue != title {
      titleLabel.stringValue = title
      needsLayout = true
    }
  }

  func setProjectEditorCompanionChromeVisible(_ shouldUseCompanionChrome: Bool) {
    let didChange = usesProjectEditorCompanionChrome != shouldUseCompanionChrome
    guard didChange || shouldUseCompanionChrome else {
      return
    }
    /**
     CDXC:ProjectEditorCompanion 2026-05-16-11:46:
     Source, Browser, Kanban, and Docs companion panes should not show the
     generic pane overflow menu in their titlebar. Agents view panes still use
     the normal action menu because they do not enable companion controls.

     CDXC:ProjectEditorCompanion 2026-06-12-03:18:
     Companion panes no longer render a local collapse control. Keep only this
     chrome state so selected companion titlebars can suppress generic pane
     actions while the React titlebar toggle owns hiding and expanding.

     CDXC:ProjectEditorCompanion 2026-06-30-00:27:
     Companion titlebar background chrome should be authoritative on each sync.
     Reapply the companion chrome even when the flag is already enabled so
     theme updates cannot leave themed backgrounds on the companion pane.
     */
    usesProjectEditorCompanionChrome = shouldUseCompanionChrome
    applyCustomSidebarTitlebarChrome()
  }

  func setActions(_ actions: [TerminalTitleBarAction]) {
    guard actionButtons.map(\.action) != actions else {
      return
    }

    for item in actionButtons {
      item.button.removeFromSuperview()
    }
    actionButtons = actions.map { action in
      (action, Self.makeActionButton(for: action))
    }
    for item in actionButtons {
      item.button.target = self
      item.button.action = #selector(performTitleBarAction(_:))
      (item.button as? TerminalTitleBarActionButton)?.debugActionKind = item.action.rawValue
      addSubview(item.button)
    }
    syncCommandTabBarActionButtonChrome()
    if actionMenuButton.superview == nil {
      addSubview(actionMenuButton)
    }
    syncActionSeparators()
    updateActionButtonVisibility()
    needsLayout = true
    if let window {
      window.invalidateCursorRects(for: self)
    }
  }

  func setFavicon(_ image: NSImage?) {
    faviconImage = image
    needsLayout = true
  }

  func setAgentIconDataUrl(_ dataUrl: String?, colorHex: String?) {
    guard agentIconDataUrl != dataUrl || agentIconColorHex != colorHex else {
      return
    }
    /**
     CDXC:NativeGpu 2026-05-08-16:45
     Native pane chrome receives frequent sidebar metadata syncs. Decode SVG
     masks and relayout the title bar only when the icon payload actually
     changes, otherwise repeated status updates keep AppKit layers dirty.
     */
    agentIconDataUrl = dataUrl
    agentIconColorHex = colorHex
    agentIconImage = nativePaneImage(fromDataUrl: dataUrl, isTemplate: true)
    agentIconColor = nativePaneColor(fromHex: colorHex)
    needsLayout = true
  }

  func setState(activity nextActivity: NativeTerminalActivity?) {
    guard activity != nextActivity else {
      return
    }
    activity = nextActivity
    switch nextActivity {
    case .attention:
      activityIndicatorLayer.isHidden = false
      activityIndicatorLayer.backgroundColor = Self.attentionIndicatorColor
    case .working:
      activityIndicatorLayer.isHidden = false
      activityIndicatorLayer.backgroundColor = Self.workingIndicatorColor
    case .sleeping:
      activityIndicatorLayer.isHidden = true
      activityIndicatorLayer.backgroundColor = NSColor.clear.cgColor
    case .none:
      activityIndicatorLayer.isHidden = true
      activityIndicatorLayer.backgroundColor = NSColor.clear.cgColor
    }
    needsLayout = true
  }

  @objc private func performTitleBarAction(_ sender: NSButton) {
    guard let item = actionButtons.first(where: { $0.button === sender }),
      isActionButtonVisible(item.action)
