  )
  private let profileButton = WebPaneHostView.makeToolbarButton(
    systemSymbolName: "person.crop.circle",
    fallbackTitle: "P",
    tooltip: "Browser Profile"
  )
  private var navigationObservations: [NSKeyValueObservation] = []
  private var isEditingAddress = false

  init(
    browserView: NSView,
    chromiumView: GhostexCEFBrowserView? = nil,
    webView: WKWebView? = nil,
    showsBrowserToolbar: Bool = false,
    showsInitialLoadingOverlay: Bool = false,
    initialAddress: String? = nil,
    browserFeedbackTool: String? = nil,
    showBetaFeatures: Bool = false,
    onFocus: (() -> Void)? = nil,
    onOpenDevTools: (() -> Void)? = nil,
    onInjectFeedbackTool: (() -> Void)? = nil,
    onShowProfilePicker: (() -> Void)? = nil,
    onShowImportSettings: (() -> Void)? = nil,
    onAddressNavigation: ((URL) -> Bool)? = nil,
    onHistoryNavigation: ((URL) -> Bool)? = nil
  ) {
    self.browserView = browserView
    self.chromiumView = chromiumView
    self.webView = webView
    self.browserFindBar = chromiumView.map { BrowserFindBarView(chromiumView: $0) }
    self.showsBrowserToolbar = showsBrowserToolbar
    self.browserFeedbackTool = BrowserFeedbackTool.normalized(browserFeedbackTool)
    self.showBetaFeatures = showBetaFeatures
    self.initialLoadingOverlayView =
      showsInitialLoadingOverlay ? ProjectEditorInitialLoadingOverlayView(frame: .zero) : nil
    self.onFocus = onFocus
    self.onOpenDevTools = onOpenDevTools
    self.onInjectFeedbackTool = onInjectFeedbackTool
    self.onShowProfilePicker = onShowProfilePicker
    self.onShowImportSettings = onShowImportSettings
    self.onAddressNavigation = onAddressNavigation
    self.onHistoryNavigation = onHistoryNavigation
    super.init(frame: .zero)
    translatesAutoresizingMaskIntoConstraints = true
    autoresizesSubviews = true
    wantsLayer = true
    layer?.backgroundColor = NSColor(calibratedRed: 0.086, green: 0.086, blue: 0.086, alpha: 1)
      .cgColor
    layer?.masksToBounds = true
    browserView.translatesAutoresizingMaskIntoConstraints = true
    browserView.autoresizingMask = []
    browserView.frame = bounds
    applySystemBrowserPageAppearanceIfNeeded()
    if showsBrowserToolbar {
      configureBrowserToolbar(initialAddress: initialAddress)
      addSubview(toolbarView)
    }
    addSubview(browserView)
    if let initialLoadingOverlayView {
      addSubview(initialLoadingOverlayView)
    }
    if let browserFindBar {
      chromiumView?.findResultHandler = { [weak browserFindBar] count, activeMatchOrdinal, finalUpdate in
        browserFindBar?.setFindResult(
          count: count,
          activeMatchOrdinal: activeMatchOrdinal,
          finalUpdate: finalUpdate)
      }
      addSubview(browserFindBar)
    }
    updateBrowserToolbarState()
  }

  /*
   CDXC:SourceCEFDragDrop 2026-06-11-21:10:
   WebPaneHostView should not force CEF/WKWebView as the hit owner when their
   native child hit tests return nil. Let AppKit traverse toolbar, browser, and
   visual-only loader subviews directly so embedded VS Code drag/drop follows
   the same ownership model as the minimal harness.
   */
  required init?(coder: NSCoder) {
    fatalError("init(coder:) is not supported")
  }

  override func layout() {
    super.layout()
    if showsBrowserToolbar, toolbarView.superview !== self {
      toolbarView.removeFromSuperview()
      addSubview(toolbarView)
    }
    if browserView.superview !== self {
      browserView.removeFromSuperview()
      addSubview(browserView)
    }
    let toolbarHeight: CGFloat
    let webFrame: CGRect
    if showsBrowserToolbar {
      toolbarHeight = min(Self.browserToolbarHeight, max(0, bounds.height))
      toolbarView.frame = CGRect(
        x: 0,
        y: bounds.height - toolbarHeight,
        width: bounds.width,
        height: toolbarHeight
      )
      layoutBrowserToolbar()
      webFrame = CGRect(x: 0, y: 0, width: bounds.width, height: max(0, bounds.height - toolbarHeight))
    } else {
      toolbarHeight = 0
      webFrame = bounds
    }
    let browserFrame: CGRect
    if let chromiumLiveResizeBackingHeight, chromiumView != nil {
      /**
       CDXC:ChromiumBrowserPanes 2026-05-21-12:38:
       Dragging the bottom command-pane handle can emit dozens of top-anchored editor-height changes in one gesture; pinning the CEF child origin is not enough because Chromium's macOS backing layer can still crawl during continuous resizes.
       Keep the CEF viewport at a stable top-anchored backing height while the host view clips to the live command-pane boundary, then commit the final CEF height once the drag ends.
       */
      let backingWebHeight = max(webFrame.height, chromiumLiveResizeBackingHeight - toolbarHeight)
      browserFrame = CGRect(
        x: webFrame.minX,
        y: webFrame.maxY - backingWebHeight,
        width: webFrame.width,
        height: backingWebHeight)
    } else {
      browserFrame = webFrame
    }
    browserView.frame = browserFrame
    /**
     CDXC:ChromiumBrowserPanes 2026-05-21-11:09:
     Code/Git browser hosts still shrink when the bottom command pane reserves space, so no page content is hidden behind the command pane.
     Force the embedded CEF child back to the host's local origin after that resize so repeated command-pane toggles cannot accumulate an upward compositor offset.
     */
    chromiumView?.pinHostedViewToBounds()
    layoutInitialLoadingOverlay(webFrame: webFrame)
    layoutBrowserFindBar(webFrame: webFrame)
  }

  func refreshBrowserToolbar(reason: String) {
    updateBrowserToolbarState()
  }

  var hostedChromiumView: GhostexCEFBrowserView? {
    chromiumView
  }

  func replaceHostedBrowserView(
    browserView nextBrowserView: NSView,
    chromiumView nextChromiumView: GhostexCEFBrowserView?,
    webView nextWebView: WKWebView?,
    reason: String
  ) {
    /*
     CDXC:ProjectBrowserTabs 2026-06-15-20:48:
     A New Tab placeholder becomes a real browser only after address-bar navigation. Replace the hosted content view in place so AppKit layout, toolbar hit-testing, and the tab strip keep the same ownership boundaries while CEF is created just-in-time.
     */
    navigationObservations.removeAll()
    browserFindBar?.removeFromSuperview()
    browserFindBar = nil
    browserView.removeFromSuperview()
    browserView = nextBrowserView
    chromiumView = nextChromiumView
    webView = nextWebView
    browserView.translatesAutoresizingMaskIntoConstraints = true
    browserView.autoresizingMask = []
    applySystemBrowserPageAppearanceIfNeeded()
    addSubview(browserView)
    if let chromiumView {
      let findBar = BrowserFindBarView(chromiumView: chromiumView)
      chromiumView.findResultHandler = { [weak findBar] count, activeMatchOrdinal, finalUpdate in
        findBar?.setFindResult(
          count: count,
          activeMatchOrdinal: activeMatchOrdinal,
          finalUpdate: finalUpdate)
      }
      browserFindBar = findBar
      addSubview(findBar)
    }
    refreshHostedWebView(reason: reason)
    updateBrowserToolbarState()
  }

  func focusAddressField(selectAll: Bool) {
    guard showsBrowserToolbar else {
      return
    }
    window?.makeFirstResponder(addressField)
    if selectAll {
      addressField.selectText(nil)
    }
  }

  var browserFeedbackToolRawValue: String {
    browserFeedbackTool.rawValue
  }

  var showsBetaFeatureToolbarButtons: Bool {
    showBetaFeatures
  }

  private var toolbarButtons: [TerminalTitleBarActionButton] {
    [
      backButton,
      forwardButton,
      reloadButton,
      zoomButton,
      reactGrabButton,
      historyButton,
      profileButton,
      devToolsButton,
    ]
  }

  func setBrowserFeedbackTool(_ value: String?) {
    browserFeedbackTool = BrowserFeedbackTool.normalized(value)
    updateBrowserFeedbackToolButton()
  }

  func setShowBetaFeatures(_ value: Bool) {
    guard showBetaFeatures != value else {
      return
    }
    showBetaFeatures = value
    updateBrowserBetaFeatureButtonVisibility()
  }

  fileprivate func setCustomSidebarTitlebarChrome(_ chrome: NativeSidebarTitlebarChromeColors) {
    guard customSidebarTitlebarChrome != chrome else {
      return
    }
    customSidebarTitlebarChrome = chrome
    applyCustomSidebarTitlebarChrome()
  }

  private func applyCustomSidebarTitlebarChrome() {
    guard showsBrowserToolbar else {
      return
    }
    toolbarView.layer?.backgroundColor = browserToolbarBackgroundColor().cgColor
    for button in toolbarButtons {
      if customSidebarTitlebarChrome.enabled {
        button.setTabBarIconChrome(
          backgroundColor: customSidebarTitlebarChrome.background.cgColor,
          tintColor: customSidebarTitlebarChrome.foreground)
      } else {
        button.resetTabBarIconChrome()
        button.normalBackgroundColor = nil
        button.hoverBackgroundColor = NSColor.clear.cgColor
        button.activeBackgroundColor = NSColor.clear.cgColor
        button.normalContentTintColor = Self.browserToolbarDefaultButtonTintColor
        button.hoverContentTintColor = Self.browserToolbarDefaultButtonTintColor
        button.activeContentTintColor = Self.browserToolbarDefaultButtonTintColor
      }
    }
    securityIcon.contentTintColor = browserToolbarSecurityTintColor()
    addressField.textColor = browserToolbarAddressTextColor()
    needsDisplay = true
  }

  private func browserToolbarBackgroundColor() -> NSColor {
    customSidebarTitlebarChrome.enabled
      ? customSidebarTitlebarChrome.background
      : Self.browserToolbarDefaultBackgroundColor
  }

  private func browserToolbarSecurityTintColor() -> NSColor {
    customSidebarTitlebarChrome.enabled
      ? customSidebarTitlebarChrome.foreground.withAlphaComponent(0.9)
      : Self.browserToolbarDefaultSecurityTintColor
  }

  private func browserToolbarAddressTextColor() -> NSColor {
    customSidebarTitlebarChrome.enabled
      ? customSidebarTitlebarChrome.foreground.withAlphaComponent(0.95)
      : Self.browserToolbarDefaultAddressTextColor
  }

  func setBrowserHistoryItems(_ items: [NativeBrowserHistoryItem]) {
    /*
     CDXC:BrowserHistory 2026-06-15-10:25:
     The toolbar history menu displays the latest project-family links supplied
     by the sidebar. Keep the host's visible page size bounded so opening the
     menu starts at the most recent 20 links, with explicit Show More paging.
     */
    browserHistoryItems = items
    browserHistoryVisibleLimit = min(
      max(Self.browserHistoryPageSize, min(browserHistoryVisibleLimit, items.count)),
      max(Self.browserHistoryPageSize, items.count))
  }

  private func applySystemBrowserPageAppearanceIfNeeded() {
    guard showsBrowserToolbar else {
      return
    }
    /*
     CDXC:BrowserPageAppearance 2026-06-19-18:13:
     Browser address bars no longer expose manual System/Light/Dark controls or persist per-origin choices. Browser panes follow macOS effective appearance for renderer media queries.

     CDXC:BrowserPageAppearance 2026-06-24-13:16:
     The default document canvas should remain Chrome-like white for toolbar browser pages, so plain HTML and transparent pages without an authored background do not reveal Ghostex's dark pane chrome.
     */
    webView?.appearance = nil
    chromiumView?.setUsesSystemPageAppearance(true)
  }

  func refreshHostedWebView(reason: String) {
    /**
     CDXC:EditorPanes 2026-05-08-13:02
     VS Code editor crashes during sidebar resize need before/after logging
     around hosted Chromium frame refresh, including whether refresh forces
     immediate layout/display on the CEF NSView.
     */
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.host.refresh.start", [
      "browserFrameBefore": Self.describeFrame(browserView.frame),
      "hostBounds": Self.describeFrame(bounds),
      "hostFrame": Self.describeFrame(frame),
      "reason": reason,
      "showsBrowserToolbar": showsBrowserToolbar,
      "webUrl": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    if showsBrowserToolbar, toolbarView.superview !== self {
      toolbarView.removeFromSuperview()
      addSubview(toolbarView)
    }
    if browserView.superview !== self {
      browserView.removeFromSuperview()
      addSubview(browserView)
    }
    let toolbarHeight = showsBrowserToolbar ? min(Self.browserToolbarHeight, max(0, bounds.height)) : 0
    if showsBrowserToolbar {
      toolbarView.frame = CGRect(
        x: 0,
        y: bounds.height - toolbarHeight,
        width: bounds.width,
        height: toolbarHeight
      )
      layoutBrowserToolbar()
    }
    let webFrame = CGRect(x: 0, y: 0, width: bounds.width, height: max(0, bounds.height - toolbarHeight))
    browserView.frame = webFrame
    layoutInitialLoadingOverlay(webFrame: webFrame)
    layoutBrowserFindBar(webFrame: webFrame)
    updateBrowserToolbarState()
    needsLayout = true
    needsDisplay = true
    browserView.needsLayout = true
    browserView.needsDisplay = true
    /**
     CDXC:EditorPanes 2026-05-08-13:13
     Hosted Chromium frame refresh is a state update, not a synchronous paint
     command. Forcing layout/display here can re-enter CEF while AppKit is
     already processing sidebar or workspace resize, which crashes the visible
     VS Code pane. Mark the views dirty and let the run loop flush them.
     */
    NativeT3CodePaneReproLog.append("nativeWorkspace.t3WebPane.host.refresh.end", [
      "hostFrame": Self.describeFrame(frame),
      "reason": reason,
      "webFrame": Self.describeFrame(browserView.frame),
      "webUrl": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
  }

  override func mouseDown(with event: NSEvent) {
    if showsBrowserToolbar {
      let localPoint = convert(event.locationInWindow, from: nil)
      let toolbarPoint = convert(localPoint, to: toolbarView)
      logBrowserToolbarInteraction("mouseDown.host", details: [
        "clickCount": event.clickCount,
        "eventLocation": Self.describePoint(event.locationInWindow),
        "hitTarget": toolbarView.frame.contains(localPoint) ? toolbarTargetName(at: toolbarPoint) : "outside-toolbar",
        "localPoint": Self.describePoint(localPoint),
        "toolbarPoint": Self.describePoint(toolbarPoint),
        "windowNumber": window?.windowNumber ?? NSNull(),
      ])
    }
    onFocus?()
    super.mouseDown(with: event)
  }

  func setInitialLoadingOverlayVisible(_ visible: Bool, reason: String) {
    guard let initialLoadingOverlayView else {
      return
    }
    if visible {
      initialLoadingOverlayView.startAnimating()
      layoutInitialLoadingOverlay(webFrame: browserView.frame)
    } else {
      initialLoadingOverlayView.stopAnimating()
    }
    NativeT3CodePaneReproLog.append("nativeWorkspace.projectEditor.loadingOverlay.visibilityChanged", [
      "reason": reason,
      "visible": visible,
      "webUrl": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
  }

  func setInitialLoadingOverlayError(_ message: String, reason: String) {
    guard let initialLoadingOverlayView else {
      return
    }
    initialLoadingOverlayView.showError(message: message)
    layoutInitialLoadingOverlay(webFrame: browserView.frame)
    NativeT3CodePaneReproLog.append("nativeWorkspace.projectEditor.loadingOverlay.errorShown", [
      "message": message,
      "reason": reason,
      "webUrl": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
  }

  private func layoutInitialLoadingOverlay(webFrame: CGRect) {
    guard let initialLoadingOverlayView else {
      return
    }
    /**
     CDXC:EditorPanes 2026-05-07-08:29
     The VS Code startup loader is a native overlay above the embedded Chromium
     view. It is created only for project editor panes, does not participate in
     browser layout or code-server startup, and ignores hit testing so it cannot
     add interaction or startup latency.
     */
    if initialLoadingOverlayView.superview !== self {
      addSubview(initialLoadingOverlayView)
    }
    if subviews.last !== initialLoadingOverlayView {
      initialLoadingOverlayView.removeFromSuperview()
      addSubview(initialLoadingOverlayView)
    }
    initialLoadingOverlayView.frame = webFrame
    initialLoadingOverlayView.needsLayout = true
  }

  private func layoutBrowserFindBar(webFrame: CGRect) {
    guard let browserFindBar else {
      return
    }
    if browserFindBar.superview !== self {
      addSubview(browserFindBar)
    }
    if subviews.last !== browserFindBar {
      browserFindBar.removeFromSuperview()
      addSubview(browserFindBar)
    }
    /**
     CDXC:BrowserSearch 2026-06-13-00:54:
     The CEF browser find box should sit 18px farther left than the terminal-style right inset while keeping the top inset unchanged.
     Split horizontal and vertical margins so this placement adjustment does not move the box down.
     */
    let horizontalMargin: CGFloat = 26
    let verticalMargin: CGFloat = 8
    let preferredSize = browserFindBar.preferredSize
    let width = min(preferredSize.width, max(0, webFrame.width - horizontalMargin * 2))
    let height = min(preferredSize.height, max(0, webFrame.height))
    guard width > 0, height > 0 else {
      browserFindBar.frame = .zero
      return
    }
    browserFindBar.frame = CGRect(
      x: webFrame.maxX - width - horizontalMargin,
      y: webFrame.maxY - height - verticalMargin,
      width: width,
      height: height)
    browserFindBar.needsLayout = true
  }

  @discardableResult
  func openBrowserFind(reason: String) -> Bool {
    guard let browserFindBar else {
      return false
    }
    onFocus?()
    browserFindBar.openFind(reason: reason)
    return true
  }

  @discardableResult
  func findNextInBrowser() -> Bool {
    guard let browserFindBar else {
      return false
    }
    onFocus?()
    browserFindBar.findNext()
    return true
  }

  @discardableResult
  func findPreviousInBrowser() -> Bool {
    guard let browserFindBar else {
      return false
    }
    onFocus?()
    browserFindBar.findPrevious()
    return true
  }

  func controlTextDidBeginEditing(_ obj: Notification) {
    isEditingAddress = true
    logBrowserToolbarInteraction("address.beginEditing", details: [
      "addressFieldFrame": Self.describeFrame(addressField.frame),
      "fieldValue": addressField.stringValue,
      "firstResponder": (window?.firstResponder).map { String(describing: type(of: $0)) } ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
  }

  func controlTextDidEndEditing(_ obj: Notification) {
    isEditingAddress = false
    logBrowserToolbarInteraction("address.endEditing", details: [
      "fieldValue": addressField.stringValue,
      "isReturnTextMovement": isReturnTextMovement(obj),
      "movement": obj.userInfo?["NSTextMovement"] ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    if isReturnTextMovement(obj) {
      /**
       CDXC:BrowserPanes 2026-05-03-04:09
       AppKit can finish NSTextField editing on Return without sending the
       target/action first. Commit here too so typed browser URLs navigate
       instead of being overwritten by the previous WKWebView URL.
       */
      commitAddress()
      return
    }
    updateBrowserToolbarState()
  }

  private func isReturnTextMovement(_ notification: Notification) -> Bool {
    guard let movement = notification.userInfo?["NSTextMovement"] as? Int else {
      return false
    }
    return movement == NSReturnTextMovement
  }

  func control(
    _ control: NSControl,
    textView: NSTextView,
    doCommandBy commandSelector: Selector
  ) -> Bool {
    guard control === addressField else {
      return false
    }
    logBrowserToolbarInteraction("address.command", details: [
      "commandSelector": NSStringFromSelector(commandSelector),
      "fieldValue": addressField.stringValue,
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    if commandSelector == #selector(NSResponder.insertNewline(_:)) {
      /**
       CDXC:BrowserPanes 2026-05-03-03:59
       Address-bar Return must always drive pane browser navigation. Handling the
       text command directly avoids AppKit swallowing the field action after a
       page focus transition or autocomplete interaction.

       CDXC:BrowserPanes 2026-05-11-20:24
       Return/keypad Enter are owned by the address field's AppKit delegate
       command path, not a local key monitor. This keeps browser address commits
       scoped to the editing field editor and prevents unrelated key events from
       being consumed outside responder dispatch.
       */
      commitAddress()
      window?.makeFirstResponder(browserView)
      return true
    }
    if commandSelector == #selector(NSResponder.insertNewlineIgnoringFieldEditor(_:)) {
      commitAddress()
      window?.makeFirstResponder(browserView)
      return true
    }
    if commandSelector == #selector(NSResponder.cancelOperation(_:)) {
      isEditingAddress = false
      updateBrowserToolbarState()
      window?.makeFirstResponder(browserView)
      return true
    }
    return false
  }

  private func configureBrowserToolbar(initialAddress: String?) {
    toolbarView.translatesAutoresizingMaskIntoConstraints = true
    toolbarView.autoresizesSubviews = false
    toolbarView.wantsLayer = true
    toolbarView.layer?.backgroundColor = browserToolbarBackgroundColor().cgColor

    toolbarButtons.forEach {
      button in
      button.target = self
      toolbarView.addSubview(button)
    }
    zoomButton.action = #selector(resetPageZoom)
    zoomButton.isHidden = true
    backButton.action = #selector(goBack)
    forwardButton.action = #selector(goForward)
    reloadButton.action = #selector(reloadPage)
    devToolsButton.action = #selector(openDevTools)
    reactGrabButton.action = #selector(injectFeedbackTool)
    historyButton.action = #selector(showHistoryMenu)
    updateBrowserFeedbackToolButton()
    profileButton.action = #selector(showProfilePicker)
    updateBrowserBetaFeatureButtonVisibility()

    securityIcon.image = NSImage(systemSymbolName: "lock.fill", accessibilityDescription: "Secure connection")
    securityIcon.contentTintColor = browserToolbarSecurityTintColor()
    securityIcon.imageScaling = .scaleProportionallyDown
    toolbarView.addSubview(securityIcon)

    addressField.cell = BrowserAddressTextFieldCell(textCell: "")
    addressField.stringValue = initialAddress ?? ""
    addressField.delegate = self
    addressField.target = self
    addressField.action = #selector(commitAddress)
    addressField.isBordered = false
    addressField.drawsBackground = false
    addressField.isEditable = true
    addressField.isSelectable = true
    addressField.focusRingType = .none
    addressField.font = NSFont.systemFont(ofSize: 13, weight: .medium)
    addressField.textColor = browserToolbarAddressTextColor()
    addressField.placeholderString = "Search or enter address"
    addressField.lineBreakMode = .byTruncatingMiddle
    addressField.cell?.lineBreakMode = .byTruncatingMiddle
    addressField.cell?.usesSingleLineMode = true
    addressField.cell?.wraps = false
    toolbarView.addSubview(addressField)
    applyCustomSidebarTitlebarChrome()

    /**
     CDXC:BrowserPanes 2026-05-02-17:03
     The address bar is native AppKit chrome for embedded browser panes. It
     normalizes typed URLs/searches and drives the pane's own browser renderer,
     keeping browser navigation inside the pane instead of opening external overlays.
     */
    if let webView {
      navigationObservations = [
        webView.observe(\.url, options: [.initial, .new]) { [weak self] _, _ in
          Task { @MainActor in self?.updateBrowserToolbarState() }
        },
        webView.observe(\.canGoBack, options: [.initial, .new]) { [weak self] _, _ in
          Task { @MainActor in self?.updateBrowserToolbarState() }
        },
        webView.observe(\.canGoForward, options: [.initial, .new]) { [weak self] _, _ in
          Task { @MainActor in self?.updateBrowserToolbarState() }
        },
        webView.observe(\.isLoading, options: [.initial, .new]) { [weak self] _, _ in
          Task { @MainActor in self?.updateBrowserToolbarState() }
        },
      ]
    }
  }

  private func layoutBrowserToolbar() {
    guard showsBrowserToolbar else {
      return
    }
    let height = toolbarView.bounds.height
    var x = Self.toolbarHorizontalPadding
    let buttonY = floor((height - Self.toolbarButtonSize.height) / 2)
    for button in [backButton, forwardButton, reloadButton] {
      button.frame = CGRect(origin: CGPoint(x: x, y: buttonY), size: Self.toolbarButtonSize)
      x += Self.toolbarButtonSize.width + Self.toolbarItemGap
    }

    /**
     CDXC:BrowserPanes 2026-05-02-17:13
     The browser address row should match the reference chrome exactly: the
     selected feedback tool, history, profile, and DevTools live to the right of the URL field.
     Import remains a profile-menu action instead of a fifth always-visible
     toolbar button so the pane chrome does not drift from the expected layout.

     CDXC:BrowserHistory 2026-06-15-10:25:
     The History button belongs immediately left of the profile button in the
     real toolbar layout. Keep it in the right-button run instead of overlaying
     the address field so hit-testing remains normal AppKit sibling geometry.

     CDXC:BetaFeatures 2026-06-16-13:08:
     The profile button remains in this normal right-button run only when Show
     Beta features is enabled; when hidden, the address field takes its space
     through the same sibling-frame calculation.

     CDXC:BrowserPageAppearance 2026-06-19-18:13:
     The browser appearance menu was removed. Page appearance follows the macOS
     effective appearance at the CEF/WKWebView boundary instead of exposing a
     stateful toolbar choice.
     */
    let rightButtons = [zoomButton, reactGrabButton, historyButton, profileButton, devToolsButton].filter { !$0.isHidden }
    var rightX = toolbarView.bounds.width - Self.toolbarHorizontalPadding
    for button in rightButtons.reversed() {
      rightX -= Self.toolbarButtonSize.width
      button.frame = CGRect(origin: CGPoint(x: rightX, y: buttonY), size: Self.toolbarButtonSize)
      rightX -= Self.toolbarItemGap
    }

    let addressX = x + 18
    let addressRight = rightX - 14
    let availableAddressWidth = max(0, addressRight - addressX)
    /**
     CDXC:BrowserPanes 2026-05-03-01:58
     The embedded browser URL text must read like toolbar chrome, not a page
     heading. Keep the field compact and vertically centered next to the lock
     icon so long URLs do not dominate the pane.
     */
    let addressHeight: CGFloat = 20
    let addressY = floor((height - addressHeight) / 2)
    securityIcon.frame = CGRect(x: addressX, y: floor((height - 14) / 2), width: 14, height: 14)
    addressField.frame = CGRect(
      x: addressX + 22,
      y: addressY,
      width: max(0, availableAddressWidth - 22),
      height: addressHeight
    )
  }

  private func updateBrowserToolbarState() {
    guard showsBrowserToolbar else {
      return
    }
    backButton.isEnabled = canGoBack()
    forwardButton.isEnabled = canGoForward()
    reloadButton.toolTip = NativeTooltip.text(isPageLoading() ? "Stop Loading" : "Reload")
    updatePageZoomButton()
    updateBrowserBetaFeatureButtonVisibility()
    updateBrowserFeedbackToolButton()
    let lockSymbol = URL(string: currentURLString() ?? "")?.scheme == "https" ? "lock.fill" : "globe"
    securityIcon.image = NSImage(systemSymbolName: lockSymbol, accessibilityDescription: nil)
    if !isEditingAddress {
      let currentURL = currentURLString()?.trimmingCharacters(in: .whitespacesAndNewlines)
      let existingAddress = addressField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
      /**
       CDXC:ProjectBrowserTabs 2026-06-13-00:28:
       Browser panes seed the native address field with the active restored tab
       URL before CEF finishes its initial about:blank bootstrap. Keep that
       seeded address visible until the browser reports a real URL so first-open
       Browser views do not flash or settle on an about:blank address row.
       */
      if currentURL?.lowercased() == "about:blank", !existingAddress.isEmpty {
        return
      }
      addressField.stringValue = currentURL ?? addressField.stringValue
    }
  }

  private func currentURLString() -> String? {
    chromiumView?.currentURLString ?? webView?.url?.absoluteString
  }

  private static func browserFeedbackToolUnavailable(urlString: String?) -> Bool {
    guard let trimmed = urlString?.trimmingCharacters(in: .whitespacesAndNewlines),
      !trimmed.isEmpty,
      let host = URL(string: trimmed)?.host?.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))
    else {
      return false
    }
    return host == "github.com" || host.hasSuffix(".github.com")
  }

  private func canGoBack() -> Bool {
    chromiumView?.canGoBack ?? webView?.canGoBack ?? false
  }

  private func canGoForward() -> Bool {
    chromiumView?.canGoForward ?? webView?.canGoForward ?? false
  }

  private func isPageLoading() -> Bool {
    chromiumView?.isLoading ?? webView?.isLoading ?? false
  }

  private func isPageZoomed() -> Bool {
    guard let chromiumView else {
      return false
    }
    return abs(chromiumView.zoomLevel) > 0.001
  }

  private func zoomPercentText() -> String {
    guard let chromiumView else {
      return "100%"
    }
    let percent = Int(round(pow(1.2, chromiumView.zoomLevel) * 100))
    return "\(percent)%"
  }

  private func updatePageZoomButton() {
    /**
     CDXC:ChromiumBrowserPanes 2026-06-10-15:59:
     Zoomed CEF pages need visible browser chrome feedback without adding a custom zoom persistence store. Show a compact reset-only toolbar icon when Chromium reports non-default zoom, and let clicking it restore the focused pane through CEF's browser zoom command.
     */
    let shouldShowZoomButton = isPageZoomed()
    if zoomButton.isHidden == shouldShowZoomButton {
      zoomButton.isHidden = !shouldShowZoomButton
      needsLayout = true
    }
    zoomButton.toolTip = NativeTooltip.text(shouldShowZoomButton
      ? "Reset Page Zoom (\(zoomPercentText()))"
      : "Reset Page Zoom")
  }

  func refreshPageZoomState(reason: String) {
    updatePageZoomButton()
  }

  private static func browserPaneNavigationRequest(url: URL) -> URLRequest {
    /**
     CDXC:BrowserPanes 2026-05-03-02:28
     Address-bar navigations create a fresh top-level page, just like restored
     browser panes. Ignore stale local document cache here too so sites that
     vary HTML by user agent do not display old bare-WKWebView markup until the
     user manually reloads.
     */
    URLRequest(url: url, cachePolicy: .reloadIgnoringLocalCacheData, timeoutInterval: 60)
  }

  @objc private func goBack() {
    logBrowserToolbarActionDiagnostics(action: "back", phase: "before", details: [
      "canGoBack": canGoBack(),
      "currentURL": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onFocus?()
    if chromiumView?.canGoBack == true {
      chromiumView?.goBack()
    } else if webView?.canGoBack == true {
      webView?.goBack()
    }
    logBrowserToolbarActionDiagnostics(action: "back", phase: "after")
    scheduleBrowserToolbarActionDiagnostics(action: "back")
  }

  @objc private func goForward() {
    logBrowserToolbarActionDiagnostics(action: "forward", phase: "before", details: [
      "canGoForward": canGoForward(),
      "currentURL": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onFocus?()
    if chromiumView?.canGoForward == true {
      chromiumView?.goForward()
    } else if webView?.canGoForward == true {
      webView?.goForward()
    }
    logBrowserToolbarActionDiagnostics(action: "forward", phase: "after")
    scheduleBrowserToolbarActionDiagnostics(action: "forward")
  }

  @objc private func reloadPage() {
    let action = isPageLoading() ? "stopLoading" : "reload"
    logBrowserToolbarActionDiagnostics(action: action, phase: "before", details: [
      "currentURL": currentURLString() ?? NSNull(),
      "isPageLoading": isPageLoading(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onFocus?()
    if isPageLoading() {
      if let chromiumView {
        chromiumView.stopLoading()
      } else {
        webView?.stopLoading()
      }
    } else {
      if let chromiumView {
        chromiumView.reload()
      } else {
        webView?.reload()
      }
    }
    logBrowserToolbarActionDiagnostics(action: action, phase: "after")
    scheduleBrowserToolbarActionDiagnostics(action: action)
  }

  @objc private func commitAddress() {
    /**
     CDXC:BrowserPanes 2026-05-03-04:36
     Address-bar commits must snapshot the edited text before focusing the pane.
     Focusing can end AppKit field editing and refresh toolbar state from the
     previous WKWebView URL, which made pasted URLs appear accepted but navigate
     back to the old page when Return was pressed.
     */
    let input = addressField.stringValue
    guard let url = Self.url(fromAddressInput: input) else {
      logBrowserToolbarInteraction("address.commit.invalid", details: [
        "input": input,
        "windowNumber": window?.windowNumber ?? NSNull(),
      ])
      NSSound.beep()
      updateBrowserToolbarState()
      return
    }
    logBrowserToolbarInteraction("address.commit", details: [
      "currentURL": currentURLString() ?? NSNull(),
      "input": input,
      "resolvedURL": url.absoluteString,
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onFocus?()
    NativeT3CodePaneReproLog.append("nativeWorkspace.browserPane.address.commit", [
      "input": input,
      "url": url.absoluteString,
    ])
    navigateBrowserToolbar(to: url, reason: "addressCommit")
  }

  private func navigateBrowserToolbar(to url: URL, reason _: String) {
    addressField.stringValue = url.absoluteString
    if onAddressNavigation?(url) == true {
      updateBrowserToolbarState()
    } else if let chromiumView {
      chromiumView.loadURLString(url.absoluteString)
    } else if let webView {
      webView.load(Self.browserPaneNavigationRequest(url: url))
    } else {
      NSSound.beep()
      updateBrowserToolbarState()
    }
  }

  @objc private func resetPageZoom() {
    logBrowserToolbarActionDiagnostics(action: "resetZoom", phase: "before", details: [
      "isZoomed": isPageZoomed(),
      "windowNumber": window?.windowNumber ?? NSNull(),
      "zoomLevel": chromiumView?.zoomLevel ?? 0,
    ])
    onFocus?()
    chromiumView?.resetZoom()
    updateBrowserToolbarState()
    DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) { [weak self] in
      self?.updateBrowserToolbarState()
    }
    logBrowserToolbarActionDiagnostics(action: "resetZoom", phase: "after")
  }

  @objc private func openDevTools() {
    logBrowserToolbarActionDiagnostics(action: "devTools", phase: "before", details: [
      "currentURL": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onOpenDevTools?()
    logBrowserToolbarActionDiagnostics(action: "devTools", phase: "after")
    scheduleBrowserToolbarActionDiagnostics(action: "devTools")
  }

  private func updateBrowserFeedbackToolButton() {
    /**
     CDXC:BrowserFeedbackTools 2026-06-15-01:52:
     GitHub disallows the browser feedback injection tool. Disable the native toolbar feedback button on github.com pages and show "This site disallows using this tool" so users understand the tool is unavailable before clicking.
     */
    let feedbackToolUnavailable = Self.browserFeedbackToolUnavailable(urlString: currentURLString())
    reactGrabButton.isEnabled = !feedbackToolUnavailable
    reactGrabButton.toolTip = NativeTooltip.text(
      feedbackToolUnavailable ? Self.feedbackToolUnavailableTooltip : browserFeedbackTool.tooltip)
    if reactGrabButton.image == nil {
      reactGrabButton.title = browserFeedbackTool.fallbackTitle
    }
  }

  private func updateBrowserBetaFeatureButtonVisibility() {
    /*
     CDXC:BetaFeatures 2026-06-16-13:08:
     Browser Profiles remains a beta address-bar button. Hide the actual AppKit
     button when Show Beta features is off so its hit area and address-field
     width disappear together through normal sibling layout.
     */
    let shouldHideBetaButtons = !showBetaFeatures
    if profileButton.isHidden != shouldHideBetaButtons {
      profileButton.isHidden = shouldHideBetaButtons
      needsLayout = true
    }
  }

  @objc private func injectFeedbackTool() {
    guard !Self.browserFeedbackToolUnavailable(urlString: currentURLString()) else {
      updateBrowserFeedbackToolButton()
      return
    }
    let action = browserFeedbackTool.logAction
    NSLog(
      "Browser feedback toolbar action: %@ url=%@",
      browserFeedbackTool.rawValue,
      NativeLogPrivacy.sanitizeLogLine(currentURLString() ?? "<nil>"))
    logBrowserToolbarActionDiagnostics(action: action, phase: "before", details: [
      "currentURL": currentURLString() ?? NSNull(),
      "feedbackTool": browserFeedbackTool.rawValue,
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onInjectFeedbackTool?()
    logBrowserToolbarActionDiagnostics(action: action, phase: "after")
    scheduleBrowserToolbarActionDiagnostics(action: action)
  }

  @objc private func showHistoryMenu() {
    showBrowserHistoryMenu(resetVisibleLimit: true)
  }

  private func showBrowserHistoryMenu(resetVisibleLimit: Bool) {
    if resetVisibleLimit {
      browserHistoryVisibleLimit = Self.browserHistoryPageSize
      browserHistoryMenuAnchorPointInWindow = resolvedBrowserHistoryMenuAnchorPointInWindow()
    }
    onFocus?()
    let menu = NSMenu(title: "History")
    /*
     CDXC:BrowserHistory 2026-06-16-13:30:
     The History dropdown should keep a stable button-anchored position after Show More, label itself with a top "History" row, top-align favicon/browser glyphs with the first text line, and open selected links in a new tab rather than replacing the current page.
     */
    let titleItem = NSMenuItem(title: "History", action: nil, keyEquivalent: "")
    titleItem.isEnabled = false
    titleItem.attributedTitle = Self.browserHistoryMenuHeaderTitle()
    menu.addItem(titleItem)
    menu.addItem(NSMenuItem.separator())
    let visibleItems = Array(browserHistoryItems.prefix(browserHistoryVisibleLimit))
    if visibleItems.isEmpty {
      let emptyItem = NSMenuItem(title: "No History", action: nil, keyEquivalent: "")
      emptyItem.isEnabled = false
      menu.addItem(emptyItem)
    } else {
      for item in visibleItems {
        let menuItem = NSMenuItem(title: "", action: #selector(openHistoryItem(_:)), keyEquivalent: "")
        menuItem.target = self
        menuItem.representedObject = item.url
        menuItem.attributedTitle = Self.browserHistoryMenuTitle(for: item)
        menuItem.image = Self.browserHistoryMenuImage(faviconDataUrl: item.faviconDataUrl)
        menuItem.toolTip = NativeTooltip.browserHistory(
          title: Self.browserHistoryTitle(for: item),
          url: item.url)
        menu.addItem(menuItem)
      }
      if browserHistoryItems.count > visibleItems.count {
        menu.addItem(NSMenuItem.separator())
        let showMoreItem = NSMenuItem(
          title: "Show More",
          action: #selector(showMoreHistoryItems(_:)),
          keyEquivalent: "")
        showMoreItem.target = self
        showMoreItem.image = NSImage(systemSymbolName: "chevron.down.circle", accessibilityDescription: "Show More")
        menu.addItem(showMoreItem)
      }
    }
    NSMenu.popUpContextMenu(menu, with: browserHistoryMenuEvent(), for: historyButton)
  }

  @objc private func showMoreHistoryItems(_ sender: NSMenuItem) {
    browserHistoryVisibleLimit = min(
      browserHistoryItems.count,
      browserHistoryVisibleLimit + Self.browserHistoryPageSize)
    DispatchQueue.main.async { [weak self] in
      self?.showBrowserHistoryMenu(resetVisibleLimit: false)
    }
  }

  @objc private func openHistoryItem(_ sender: NSMenuItem) {
    guard let urlString = sender.representedObject as? String,
      let url = URL(string: urlString)
    else {
      return
    }
    onFocus?()
    if onHistoryNavigation?(url) == true {
      return
    }
    navigateBrowserToolbar(to: url, reason: "historyMenu")
  }

  private static func browserHistoryTitle(for item: NativeBrowserHistoryItem) -> String {
    let title = item.title.trimmingCharacters(in: .whitespacesAndNewlines)
    if !title.isEmpty, title.lowercased() != "about:blank" {
      return title
    }
    return URL(string: item.url)?.host ?? "Browser"
  }

  private static func browserHistoryMenuHeaderTitle() -> NSAttributedString {
    NSAttributedString(
      string: "History",
      attributes: [
        .font: NSFont.systemFont(ofSize: 13, weight: .semibold),
        .foregroundColor: NSColor.secondaryLabelColor,
      ])
  }

  private static func browserHistoryMenuTitle(for item: NativeBrowserHistoryItem) -> NSAttributedString {
    let titleFont = NSFont.systemFont(ofSize: 13, weight: .semibold)
    let urlFont = NSFont.systemFont(ofSize: 11, weight: .regular)
    let title = truncatedBrowserHistoryMenuText(browserHistoryTitle(for: item), font: titleFont)
    let url = truncatedBrowserHistoryMenuText(item.url, font: urlFont)
    let text = "\(title)\n\(url)"
    let attributed = NSMutableAttributedString(string: text)
    let titleRange = NSRange(location: 0, length: (title as NSString).length)
    let urlRange = NSRange(location: titleRange.length + 1, length: (url as NSString).length)
    attributed.addAttributes(
      [
        .font: titleFont,
        .foregroundColor: NSColor.labelColor,
      ],
      range: titleRange)
    attributed.addAttributes(
      [
        .font: urlFont,
        .foregroundColor: NSColor.secondaryLabelColor,
      ],
      range: urlRange)
    return attributed
  }

  private static func truncatedBrowserHistoryMenuText(_ value: String, font: NSFont) -> String {
    let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
    let maxTextWidth = max(120, browserHistoryMenuMaxWidth - browserHistoryMenuEstimatedChromeWidth)
    guard browserHistoryMenuTextWidth(trimmed, font: font) > maxTextWidth else {
      return trimmed
    }
    let characters = Array(trimmed)
    var lowerBound = 0
    var upperBound = characters.count
    while lowerBound < upperBound {
      let midpoint = (lowerBound + upperBound + 1) / 2
      let candidate = String(characters.prefix(midpoint)).trimmingCharacters(in: .whitespaces)
      if browserHistoryMenuTextWidth("\(candidate)...", font: font) <= maxTextWidth {
        lowerBound = midpoint
      } else {
        upperBound = midpoint - 1
      }
    }
    let prefix = String(characters.prefix(lowerBound)).trimmingCharacters(in: .whitespaces)
    return prefix.isEmpty ? "..." : "\(prefix)..."
  }

  private static func browserHistoryMenuTextWidth(_ value: String, font: NSFont) -> CGFloat {
    (value as NSString).size(withAttributes: [.font: font]).width
  }

  private static func browserHistoryMenuImage(faviconDataUrl: String?) -> NSImage? {
    if let faviconDataUrl,
      let commaIndex = faviconDataUrl.firstIndex(of: ","),
      let data = Data(base64Encoded: String(faviconDataUrl[faviconDataUrl.index(after: commaIndex)...])),
      let image = NSImage(data: data)
    {
      return topAlignedBrowserHistoryMenuImage(image)
    }
    return topAlignedBrowserHistoryMenuImage(browserHistoryFallbackMenuImage())
  }

  private static func topAlignedBrowserHistoryMenuImage(_ sourceImage: NSImage) -> NSImage {
    /*
     CDXC:BrowserHistory 2026-06-16-13:30:
     AppKit centers NSMenuItem images against the full two-line row height. Wrap each 16px favicon or browser fallback in a taller transparent canvas with the glyph drawn near the top so the icon reads aligned with the page-title line.
     */
    let image = NSImage(size: browserHistoryMenuIconCanvasSize)
    image.lockFocus()
    NSGraphicsContext.current?.imageInterpolation = .high
    sourceImage.draw(
      in: NSRect(
        x: 0,
        y: browserHistoryMenuIconCanvasSize.height - browserHistoryMenuIconSize.height - 2,
        width: browserHistoryMenuIconSize.width,
        height: browserHistoryMenuIconSize.height),
      from: .zero,
      operation: .sourceOver,
      fraction: 1)
    image.unlockFocus()
    image.isTemplate = sourceImage.isTemplate
    return image
  }

  private static func browserHistoryFallbackMenuImage() -> NSImage {
    /*
     CDXC:BrowserHistory 2026-06-16-13:05:
     History rows without page favicons still need a visible browser identity icon. Draw a small browser-window glyph locally instead of relying on an optional SF Symbol or SVG decoder path, while preserving real favicons when present.
     */
    let image = NSImage(size: CGSize(width: 16, height: 16))
    image.lockFocus()
    NSGraphicsContext.current?.shouldAntialias = true
    let strokeColor = NSColor(calibratedWhite: 0.86, alpha: 0.9)
    let fillColor = NSColor(calibratedWhite: 0.86, alpha: 0.12)
    let bodyRect = NSRect(x: 2.5, y: 3, width: 11, height: 10)
    let bodyPath = NSBezierPath(roundedRect: bodyRect, xRadius: 2, yRadius: 2)
    fillColor.setFill()
    bodyPath.fill()
    strokeColor.setStroke()
    bodyPath.lineWidth = 1.3
    bodyPath.stroke()
    let toolbarPath = NSBezierPath()
    toolbarPath.move(to: NSPoint(x: 3, y: 10))
    toolbarPath.line(to: NSPoint(x: 13.5, y: 10))
    toolbarPath.lineWidth = 1.1
    toolbarPath.stroke()
    for centerX in [5.0, 7.0, 9.0] {
      NSBezierPath(ovalIn: NSRect(x: centerX - 0.45, y: 11.35, width: 0.9, height: 0.9)).fill()
    }
    image.unlockFocus()
    image.isTemplate = false
    return image
  }

  private func resolvedBrowserHistoryMenuAnchorPointInWindow() -> NSPoint {
    if let currentEvent = NSApp.currentEvent,
      let eventWindow = currentEvent.window,
      let window,
      eventWindow === window
    {
      let hostPoint = convert(currentEvent.locationInWindow, from: nil)
      let toolbarPoint = convert(hostPoint, to: toolbarView)
      if historyButton.frame.contains(toolbarPoint) {
        return currentEvent.locationInWindow
      }
    }
    return historyButton.convert(
      NSPoint(x: historyButton.bounds.midX, y: historyButton.bounds.minY),
      to: nil)
  }

  private func browserHistoryMenuEvent() -> NSEvent {
    let anchorPoint = browserHistoryMenuAnchorPointInWindow ?? resolvedBrowserHistoryMenuAnchorPointInWindow()
    return NSEvent.mouseEvent(
      with: .leftMouseDown,
      location: anchorPoint,
      modifierFlags: [],
      timestamp: ProcessInfo.processInfo.systemUptime,
      windowNumber: window?.windowNumber ?? 0,
      context: nil,
      eventNumber: 0,
      clickCount: 1,
      pressure: 1
    )!
  }

  @objc private func showProfilePicker() {
    logBrowserToolbarActionDiagnostics(action: "profile", phase: "before", details: [
      "currentURL": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onShowProfilePicker?()
    logBrowserToolbarActionDiagnostics(action: "profile", phase: "after")
    scheduleBrowserToolbarActionDiagnostics(action: "profile")
  }

  @objc private func showImportSettings() {
    logBrowserToolbarActionDiagnostics(action: "importSettings", phase: "before", details: [
      "currentURL": currentURLString() ?? NSNull(),
      "windowNumber": window?.windowNumber ?? NSNull(),
    ])
    onShowImportSettings?()
    logBrowserToolbarActionDiagnostics(action: "importSettings", phase: "after")
    scheduleBrowserToolbarActionDiagnostics(action: "importSettings")
  }

  private func toolbarTargetName(at point: CGPoint) -> String {
    if backButton.frame.contains(point) {
      return "backButton"
    }
    if forwardButton.frame.contains(point) {
      return "forwardButton"
    }
    if reloadButton.frame.contains(point) {
      return "reloadButton"
    }
    if securityIcon.frame.contains(point) {
      return "securityIcon"
    }
    if addressField.frame.contains(point) {
      return "addressField"
    }
    if !zoomButton.isHidden, zoomButton.frame.contains(point) {
      return "zoomButton"
    }
    if reactGrabButton.frame.contains(point) {
      return "feedbackToolButton"
    }
    if historyButton.frame.contains(point) {
      return "historyButton"
    }
    if profileButton.frame.contains(point) {
      return "profileButton"
    }
    if devToolsButton.frame.contains(point) {
      return "devToolsButton"
    }
    if toolbarView.bounds.contains(point) {
      return "toolbarBackground"
    }
    return "outsideToolbar"
  }

  private func browserToolbarHitView(at point: CGPoint) -> NSView {
    /**
     CDXC:BrowserToolbarDiagnostics 2026-05-16-12:45:
     Repro logs at 2026-05-16 12:41 showed toolbar hit testing correctly
     classified `backButton`, `reloadButton`, and `addressField`, but
     `toolbarView.hitTest` always returned the toolbar container `NSView`.
     Route directly to the known AppKit controls so browser toolbar clicks
     execute their button actions or start address-field editing in both Git
     project views and normal browser panes.
     */
    if backButton.frame.contains(point) {
      return backButton
    }
    if forwardButton.frame.contains(point) {
      return forwardButton
    }
    if reloadButton.frame.contains(point) {
      return reloadButton
    }
    if addressField.frame.contains(point) {
      return addressField
    }
    if !zoomButton.isHidden, zoomButton.frame.contains(point) {
      return zoomButton
    }
    if reactGrabButton.frame.contains(point) {
      return reactGrabButton
    }
    if historyButton.frame.contains(point) {
      return historyButton
    }
    if profileButton.frame.contains(point) {
      return profileButton
    }
    if devToolsButton.frame.contains(point) {
      return devToolsButton
    }
    return toolbarView
  }

  private func logBrowserToolbarActionDiagnostics(
    action: String,
    phase: String,
    details: [String: Any] = [:]
  ) {
    /**
     CDXC:ChromiumBrowserPanes 2026-05-16-15:48:
     A browser-toolbar click can move CEF page contents upward even when no pane resize occurs, and a full reload can restore the correct visual position.
     Log host geometry and force a CEF/page viewport snapshot before, after, and shortly after toolbar navigation actions so the repro can show whether the click changes AppKit frames, Chromium compositor layers, or only document viewport state.
     */
    var payload = details
    payload["action"] = action
    payload["addressFieldFrame"] = Self.describeFrame(addressField.frame)
    payload["browserFrame"] = Self.describeFrame(browserView.frame)
    if browserView.window != nil {
      payload["browserFrameInWindow"] = Self.describeFrame(browserView.convert(browserView.bounds, to: nil))
    } else {
      payload["browserFrameInWindow"] = NSNull()
    }
    payload["hostBounds"] = Self.describeFrame(bounds)
    payload["hostFrame"] = Self.describeFrame(frame)
    payload["phase"] = phase
    payload["toolbarFrame"] = Self.describeFrame(toolbarView.frame)
    payload["windowNumber"] = window?.windowNumber ?? NSNull()
    logBrowserToolbarInteraction("button.\(action).\(phase)", details: payload)
    chromiumView?.emitToolbarActionDiagnostics(action: action, phase: phase)
  }

  private func scheduleBrowserToolbarActionDiagnostics(action: String) {
    let delayedPhases: [(TimeInterval, String)] = [
      (0.08, "after-80ms"),
      (0.25, "after-250ms"),
      (0.75, "after-750ms"),
    ]
    for (delay, phase) in delayedPhases {
      DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
        self?.logBrowserToolbarActionDiagnostics(action: action, phase: phase)
      }
    }
  }

  private func logBrowserToolbarInteraction(_ phase: String, details: [String: Any] = [:]) {
    var payload = details
    payload["backEnabled"] = backButton.isEnabled
    payload["currentURL"] = currentURLString() ?? NSNull()
    payload["forwardEnabled"] = forwardButton.isEnabled
    payload["isEditingAddress"] = isEditingAddress
    payload["isPageLoading"] = isPageLoading()
    payload["phase"] = phase
    payload["showsBrowserToolbar"] = showsBrowserToolbar
    NativeT3CodePaneReproLog.append("nativeWorkspace.browserToolbar.interaction", payload)
  }

  private static func url(fromAddressInput value: String) -> URL? {
    let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
      return nil
    }
    if let url = URL(string: trimmed), url.scheme != nil {
      return url
    }
    if trimmed == "localhost" || trimmed.hasPrefix("localhost:") || trimmed.hasPrefix("127.0.0.1") {
      return URL(string: "http://\(trimmed)")
    }
    if trimmed.contains(".") && !trimmed.contains(" ") {
      return URL(string: "https://\(trimmed)")
    }
    var components = URLComponents(string: "https://www.google.com/search")
    components?.queryItems = [URLQueryItem(name: "q", value: trimmed)]
    return components?.url
  }

  private static func makeToolbarButton(
    systemSymbolName: String,
    fallbackTitle: String,
    tooltip: String
  ) -> TerminalTitleBarActionButton {
    let button = TerminalTitleBarActionButton(title: "", target: nil, action: nil)
    button.bezelStyle = .texturedRounded
    button.isBordered = false
    button.imagePosition = .imageOnly
    button.toolTip = NativeTooltip.text(tooltip)
    button.normalContentTintColor = Self.browserToolbarDefaultButtonTintColor
    button.hoverContentTintColor = Self.browserToolbarDefaultButtonTintColor
    button.activeContentTintColor = Self.browserToolbarDefaultButtonTintColor
    button.normalBackgroundColor = nil
    button.hoverBackgroundColor = NSColor.clear.cgColor
    button.activeBackgroundColor = NSColor.clear.cgColor
    button.chromeCornerRadius = 0
    button.focusRingType = .none
    if let image = NSImage(systemSymbolName: systemSymbolName, accessibilityDescription: tooltip) {
      button.image = image
    } else {
      button.title = fallbackTitle
      button.font = NSFont.systemFont(ofSize: 12, weight: .semibold)
    }
    return button
  }

  private func syntheticMenuEvent() -> NSEvent {
    if let currentEvent = NSApp.currentEvent {
      return currentEvent
    }
    return NSEvent.mouseEvent(
      with: .rightMouseDown,
      location: NSEvent.mouseLocation,
      modifierFlags: [],
      timestamp: ProcessInfo.processInfo.systemUptime,
      windowNumber: window?.windowNumber ?? 0,
      context: nil,
      eventNumber: 0,
      clickCount: 1,
      pressure: 1
    )!
  }

  private static func describeFrame(_ frame: CGRect) -> [String: Double] {
    [
      "height": Double(frame.height),
      "width": Double(frame.width),
      "x": Double(frame.minX),
      "y": Double(frame.minY),
    ]
  }

  private static func describePoint(_ point: CGPoint) -> [String: Double] {
    [
      "x": Double(point.x),
      "y": Double(point.y),
    ]
  }
}

private final class PoppedOutPaneWindowController: NSWindowController, NSWindowDelegate {
  let sessionId: String
  let titleBarView: TerminalSessionTitleBarView
  private let onReattachRequested: (String) -> Void
  private let onResize: (String) -> Void
  private var isClosingProgrammatically = false

  init(
    sessionId: String,
    titleBarView: TerminalSessionTitleBarView,
    window: NSWindow,
    onReattachRequested: @escaping (String) -> Void,
    onResize: @escaping (String) -> Void
  ) {
    self.sessionId = sessionId
    self.titleBarView = titleBarView
    self.onReattachRequested = onReattachRequested
    self.onResize = onResize
    super.init(window: window)
    /**
     CDXC:PanePopOut 2026-05-11-19:10
     Popped-out panes use the same TerminalSessionTitleBarView action controls
     as in-workspace panes. Pop In must be handled by the title bar's native
     AppKit mouseDown/mouseUp path instead of a window-level event monitor so
     click ownership stays local to the control hierarchy.

     CDXC:ZmxPersistenceRefresh 2026-05-18-15:10:
     Popped-out zmx terminals need the zmx repaint request after
     their standalone NSWindow resize settles, because workspace resize
     observers do not see the popped-out window's content-frame changes.
     */
    window.delegate = self
  }

  required init?(coder: NSCoder) {
    fatalError("init(coder:) is not supported")
  }

  func closeProgrammatically() {
    isClosingProgrammatically = true
    window?.delegate = nil
    window?.close()
  }

  func windowShouldClose(_ sender: NSWindow) -> Bool {
    guard !isClosingProgrammatically else {
      return true
    }
    onReattachRequested(sessionId)
    return false
  }

  func windowDidResize(_ notification: Notification) {
    onResize(sessionId)
  }
}

private final class PoppedOutTerminalPaneContentView: NSView {
  private let scrollView: NSView
  private let searchBarView: NSView
  private let persistenceLabelView: TerminalPanePersistenceLabelLayer
  private let delayedSendLabelView: TerminalPaneDelayedSendLabelLayer
  private let firstPromptTitleOverlayView: NSView
  private let titleBarView: NSView
  private let titleBarHeight: CGFloat

  init(
    scrollView: NSView,
    searchBarView: NSView,
    persistenceLabelView: TerminalPanePersistenceLabelLayer,
    delayedSendLabelView: TerminalPaneDelayedSendLabelLayer,
    firstPromptTitleOverlayView: NSView,
    titleBarView: NSView,
    titleBarHeight: CGFloat
  ) {
    self.scrollView = scrollView
    self.searchBarView = searchBarView
    self.persistenceLabelView = persistenceLabelView
    self.delayedSendLabelView = delayedSendLabelView
    self.firstPromptTitleOverlayView = firstPromptTitleOverlayView
    self.titleBarView = titleBarView
    self.titleBarHeight = titleBarHeight
    super.init(frame: .zero)
    wantsLayer = true
    layer?.backgroundColor = NSColor(calibratedRed: 0.071, green: 0.071, blue: 0.071, alpha: 1).cgColor
    addSubview(scrollView)
    addSubview(searchBarView)
    addSubview(firstPromptTitleOverlayView)
    addSubview(titleBarView)
    installPaneOverlayLayer(persistenceLabelView)
    installPaneOverlayLayer(delayedSendLabelView)
  }

  required init?(coder: NSCoder) {
    fatalError("init(coder:) is not supported")
  }

  override func layout() {
    super.layout()
    installPaneOverlayLayer(persistenceLabelView)
    installPaneOverlayLayer(delayedSendLabelView)
    let titleHeight = min(titleBarHeight, max(bounds.height, 0))
    titleBarView.frame = CGRect(
      x: 0,
      y: bounds.maxY - titleHeight,
      width: bounds.width,
      height: titleHeight)
    scrollView.frame = CGRect(
      x: 0,
      y: 0,
      width: bounds.width,
      height: max(bounds.height - titleHeight, 1))
    searchBarView.frame = CGRect(
      x: max(12, bounds.width - 332),
      y: max(12, bounds.height - titleHeight - 48),
      width: min(320, max(bounds.width - 24, 1)),
      height: 36)
    let labelSize = persistenceLabelView.fittingSize
    let labelWidth = min(ceil(labelSize.width), max(bounds.width - 20, 0))
    let labelHeight = min(max(ceil(labelSize.height), 14), max(bounds.height - titleHeight - 12, 0))
    persistenceLabelView.frame = persistenceLabelView.isHidden
      ? .zero
      : CGRect(
        x: max(10, bounds.maxX - labelWidth - 5),
        y: max(6, bounds.height - titleHeight - labelHeight - 6),
        width: labelWidth,
        height: labelHeight)
    let terminalRect = CGRect(
      x: 0,
      y: 0,
      width: bounds.width,
      height: max(bounds.height - titleHeight, 1))
    if delayedSendLabelView.isHidden {
      delayedSendLabelView.frame = .zero
    } else {
      let delayedSendLabelSize = delayedSendLabelView.fittingSize
      let delayedSendLabelWidth = min(
        ceil(delayedSendLabelSize.width),
        max(terminalRect.width - 32, 0))
      let delayedSendLabelHeight = min(
        max(ceil(delayedSendLabelSize.height), 52),
        max(terminalRect.height - 24, 0))
      delayedSendLabelView.frame = CGRect(
        x: min(
          max(terminalRect.midX - delayedSendLabelWidth / 2, terminalRect.minX),
          terminalRect.maxX - delayedSendLabelWidth),
        y: min(
          max(terminalRect.midY - delayedSendLabelHeight / 2, terminalRect.minY),
          terminalRect.maxY - delayedSendLabelHeight),
        width: delayedSendLabelWidth,
        height: delayedSendLabelHeight)
    }
    firstPromptTitleOverlayView.frame = firstPromptTitleOverlayView.isHidden ? .zero : terminalRect
  }

  private func installPaneOverlayLayer(_ overlayLayer: CALayer & TerminalPaneOwnedOverlayLayer) {
    wantsLayer = true
    guard let rootLayer = layer else {
      return
    }
    overlayLayer.ownerView = self
    guard overlayLayer.superlayer !== rootLayer else {
      return
    }
    overlayLayer.removeFromSuperlayer()
    rootLayer.addSublayer(overlayLayer)
  }
}

