private final class SleepingPanePlaceholderContentView: NSView {
  enum Mode {
    case mounting
    case sleeping
  }

  var onWakeRequested: (() -> Void)?
  private let wakeLabel = NSTextField(wrappingLabelWithString: "Press Any Key to Wake")
  private var mode: Mode = .sleeping

  override var isOpaque: Bool {
    true
  }

  override var acceptsFirstResponder: Bool {
    true
  }

  override init(frame frameRect: NSRect) {
    super.init(frame: frameRect)
    wantsLayer = true
    layer?.backgroundColor = NSColor.black.cgColor
    /*
     CDXC:SleepingPanePlaceholders 2026-06-13-21:26:
     The sleeping-pane affordance should say "Press Any Key to Wake" while waking only for letter and number key presses.
     Keep it centered, use a larger primary-action size, and include draw padding around the measured text instead of relying on a tight text-cell width.
     */
    wakeLabel.font = NSFont.systemFont(ofSize: 13, weight: .medium)
    wakeLabel.textColor = NSColor(calibratedWhite: 0.55, alpha: 1)
    wakeLabel.alignment = .center
    wakeLabel.isSelectable = false
    wakeLabel.lineBreakMode = .byCharWrapping
    wakeLabel.maximumNumberOfLines = 0
    wakeLabel.cell?.wraps = true
    wakeLabel.cell?.isScrollable = false
    addSubview(wakeLabel)
  }

  required init?(coder: NSCoder) {
    fatalError("init(coder:) is not supported")
  }

  override func layout() {
    super.layout()
    let maxLabelWidth = max(bounds.width - 8, 0)
    let maxLabelHeight = max(bounds.height - 16, 0)
    guard maxLabelWidth > 0, maxLabelHeight > 0 else {
      wakeLabel.frame = .zero
      return
    }
    let paragraphStyle = NSMutableParagraphStyle()
    paragraphStyle.alignment = .center
    paragraphStyle.lineBreakMode = .byCharWrapping
    let wakeFont = wakeLabel.font ?? NSFont.systemFont(ofSize: 13, weight: .medium)
    let labelSize = (wakeLabel.stringValue as NSString).boundingRect(
      with: NSSize(width: maxLabelWidth, height: CGFloat.greatestFiniteMagnitude),
      options: [.usesLineFragmentOrigin, .usesFontLeading],
      attributes: [.font: wakeFont, .paragraphStyle: paragraphStyle]
    ).size
    let labelWidth = min(max(ceil(labelSize.width) + 8, 1), maxLabelWidth)
    let labelHeight = min(max(ceil(labelSize.height), 18), maxLabelHeight)
    wakeLabel.frame = CGRect(
      x: bounds.midX - (labelWidth / 2),
      y: bounds.midY - (labelHeight / 2),
      width: labelWidth,
      height: labelHeight)
  }

  override func mouseDown(with event: NSEvent) {
    window?.makeFirstResponder(self)
    guard mode == .sleeping else {
      return
    }
    onWakeRequested?()
  }

  override func acceptsFirstMouse(for event: NSEvent?) -> Bool {
    true
  }

  override func keyDown(with event: NSEvent) {
    guard mode == .sleeping, Self.isAlphanumericWakeKey(event) else {
      super.keyDown(with: event)
      return
    }
    onWakeRequested?()
  }

  func setShowsClickToWake(_ shows: Bool) {
    setMode(.sleeping, clickToWakeEnabled: shows)
  }

  func setMode(_ mode: Mode, clickToWakeEnabled: Bool) {
    self.mode = mode
    switch mode {
    case .mounting:
      /*
       CDXC:TerminalCreationFocus 2026-06-14-18:48:
       A mounting placeholder is not a sleep/wake affordance. It communicates that Ghostty is attaching and ignores click/key wake input until terminalReady swaps in the real terminal.

       CDXC:TerminalCreationFocus 2026-06-14-19:02:
       New-terminal placeholders should be visually quiet: keep the native placeholder black and blank while Ghostty mounts instead of showing centered status text.
       */
      wakeLabel.stringValue = ""
      wakeLabel.isHidden = true
    case .sleeping:
      wakeLabel.stringValue = "Press Any Key to Wake"
      wakeLabel.isHidden = !clickToWakeEnabled
    }
    needsLayout = true
  }

  private static func isAlphanumericWakeKey(_ event: NSEvent) -> Bool {
    guard event.type == .keyDown else {
      return false
    }
    let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
    guard flags.isDisjoint(with: [.command, .control, .option, .function, .help]) else {
      return false
    }
    guard let key = event.charactersIgnoringModifiers?.lowercased(),
      key.count == 1,
      let scalar = key.unicodeScalars.first
    else {
      return false
    }
    return (UInt32(97)...UInt32(122)).contains(scalar.value)
      || (UInt32(48)...UInt32(57)).contains(scalar.value)
  }
}

private protocol TerminalPaneOwnedOverlayLayer: AnyObject {
  var ownerView: NSView? { get set }
}

private final class TerminalPanePersistenceLabelLayer: CATextLayer, TerminalPaneOwnedOverlayLayer {
  private static let labelFont = NSFont.systemFont(ofSize: 10, weight: .medium)
  private var isEnabledBySettings = false
  private var isSuppressedByPaneState = false
  private var labelString = ""
  weak var ownerView: NSView?

  var fittingSize: NSSize {
    guard !labelString.isEmpty else {
      return .zero
    }
    let size = (labelString as NSString).size(withAttributes: [.font: Self.labelFont])
    return NSSize(width: ceil(size.width) + 10, height: 16)
  }

  override init() {
    super.init()
    commonInit()
  }

  override init(layer: Any) {
    super.init(layer: layer)
    if let source = layer as? TerminalPanePersistenceLabelLayer {
      isEnabledBySettings = source.isEnabledBySettings
      isSuppressedByPaneState = source.isSuppressedByPaneState
      labelString = source.labelString
    }
    commonInit()
  }

  required init?(coder: NSCoder) {
    fatalError("init(coder:) is not supported")
  }

  private func commonInit() {
    /*
     CDXC:SessionPersistence 2026-06-13-09:52:
     Provider/session metadata is passive pane chrome. Render it as a CATextLayer so it keeps the same visual position without adding a decorative NSTextField that needs click-through hit testing.
     */
    isHidden = true
    font = Self.labelFont
    fontSize = 10
    foregroundColor = NSColor(calibratedWhite: 0.86, alpha: 0.24).cgColor
    alignmentMode = .left
    truncationMode = .end
    contentsScale = NSScreen.main?.backingScaleFactor ?? 2
    zPosition = 60
    actions = [
      "bounds": NSNull(),
      "hidden": NSNull(),
      "position": NSNull(),
      "string": NSNull(),
    ]
  }

  func setProvider(_ provider: NativeSessionPersistenceProvider?, sessionName: String?) {
    let nextTitle: String
    if let provider, let sessionName = sessionName?.trimmingCharacters(in: .whitespacesAndNewlines),
      !sessionName.isEmpty
    {
      nextTitle = "\(provider.rawValue) - \(sessionName)"
    } else {
      nextTitle = ""
    }
    guard labelString != nextTitle else {
      return
    }
    /*
     CDXC:SessionPersistence 2026-05-15-09:36:
     Provider-backed terminal panes should keep their durable attach identity visible in the pane itself. Render `provider - session` as a dim bottom-left overlay so tmux, zmx, and zellij sessions are identifiable without opening sidebar card details.

     CDXC:SessionPersistence 2026-05-15-09:48:
     The persistence label should stay quieter than terminal content and pane chrome. Use low opacity so it remains available as context without competing with command output.

     CDXC:SessionPersistence 2026-05-15-09:53:
     The provider/session context should sit in the bottom-right corner, away from common left-aligned shell prompts and command output.

     CDXC:SessionPersistence 2026-05-15-09:58:
     Move the provider/session context to the top-right corner so it stays visible without sitting beside prompt input at the bottom of the terminal body.

    CDXC:SessionPersistence 2026-05-16-07:14:
     Shift the top-right provider/session context 5px farther right so the floating label aligns closer to the terminal pane edge.
     */
    labelString = nextTitle
    string = nextTitle
    updateVisibility()
    invalidateOwnerLayout(includeSuperview: false)
  }

  func setSuppressed(_ isSuppressed: Bool) {
    guard isSuppressedByPaneState != isSuppressed else {
      return
    }
    /*
     CDXC:SessionPersistence 2026-05-15-09:44:
     Minimized command panes only show command-tab chrome, not terminal body metadata. Suppress the dim provider/session overlay explicitly while the command pane is collapsed so reused AppKit frames cannot leave stale `zmx - session` text visible.
    */
    isSuppressedByPaneState = isSuppressed
    updateVisibility()
    invalidateOwnerLayout(includeSuperview: false)
  }

  func setEnabledBySettings(_ isEnabled: Bool) {
    guard isEnabledBySettings != isEnabled else {
      return
    }
    /*
     CDXC:SessionPersistence 2026-05-23-00:50:
     The Settings preference defaults on, but this label must still require a
     non-empty provider/session title. That keeps ordinary terminals clean while
     zmx/tmux/zellij panes can show their attach identity.
    */
    isEnabledBySettings = isEnabled
    updateVisibility()
    invalidateOwnerLayout(includeSuperview: false)
  }

  private func updateVisibility() {
    isHidden = !isEnabledBySettings || isSuppressedByPaneState || labelString.isEmpty
  }

  private func invalidateOwnerLayout(includeSuperview: Bool) {
    setNeedsDisplay()
    ownerView?.needsLayout = true
    if includeSuperview {
      ownerView?.superview?.needsLayout = true
    }
  }
}

private final class TerminalPaneDelayedSendLabelLayer: CALayer, TerminalPaneOwnedOverlayLayer {
  private static let labelFont = NSFont.monospacedDigitSystemFont(ofSize: 23, weight: .bold)
  /*
   CDXC:DelayedSend 2026-06-09-14:38:
