     the current pointer, while begin/drag still assert the resize cursor.

     CDXC:NativeLayout 2026-06-13-09:33:
     The split rail is an exact native view and does not need a local hitTest
     override. Normal AppKit traversal should select it from its frame; parent
     prepass cleanup is handled separately after rail z-order is verified.

     CDXC:CommandsPanel 2026-06-13-20:57:
     Command-panel resize rails keep the same non-overlapping AppKit frame, but
     their hover line can be bottom-aligned inside that frame so the drag affordance
     sits flush with the command tab bar without moving the hit target into tab chrome.
     */
    splitDirection = direction.rawValue
    layer?.backgroundColor = NSColor.clear.cgColor
    if self.cursor !== cursor {
      self.cursor = cursor
    }
    resizeHoverIndicator.configure(
      lineAxis: direction == .horizontal ? .vertical : .horizontal,
      explicitLineFrame: explicitHoverLineFrame,
      in: self)
  }

  override func acceptsFirstMouse(for event: NSEvent?) -> Bool {
    true
  }

  override func updateTrackingAreas() {
    super.updateTrackingAreas()
    resizeHoverIndicator.updateTrackingArea(in: self)
  }

  override func layout() {
    super.layout()
    resizeHoverIndicator.layout(in: self)
  }

  override func mouseEntered(with event: NSEvent) {
    cursor.set()
    appendResizeRailLog("nativePaneResize.handle.mouseEntered", event: event)
    resizeHoverIndicator.mouseEntered(in: self)
  }

  override func mouseExited(with event: NSEvent) {
    appendResizeRailLog("nativePaneResize.handle.mouseExited", event: event)
    /*
     CDXC:NativePaneResize 2026-06-12-03:58:
     Resize hover should not leave the resize cursor stuck after the pointer
     exits the five-point rail toward terminal/editor content. Restore the
     default cursor on hover exit, but keep the resize cursor during an active
     drag because real resize gestures naturally leave the rail bounds.
     */
    if !isResizeDragging {
      refreshCursorForCurrentPointer()
    }
    resizeHoverIndicator.mouseExited(in: self)
  }

  override func cursorUpdate(with event: NSEvent) {
    cursor.set()
    appendResizeRailLog("nativePaneResize.handle.cursorUpdate", event: event)
  }

  override func resetCursorRects() {
    super.resetCursorRects()
    /**
     CDXC:ResizeHoverAffordance 2026-06-09-15:32:
     Pane, command, and companion resize rails should show the native resize cursor again while keeping the delayed hover line. Register the full rail bounds with AppKit so cursor feedback matches the drag frame.
     */
    addCursorRect(bounds, cursor: cursor)
  }

  private func appendResizeRailLog(_ eventName: String, event: NSEvent?) {
    var details: [String: Any] = [
      "alphaValue": Double(alphaValue),
      "bounds": nativePaneTabsDebugFrame(bounds),
      "direction": splitDirection,
      "frame": nativePaneTabsDebugFrame(frame),
      "isHidden": isHidden,
      "zPosition": Double(layer?.zPosition ?? 0),
    ]
    if let event {
      details["eventType"] = String(describing: event.type)
      details["locationInWindow"] = nativePaneTabsDebugPoint(event.locationInWindow)
    }
    if let windowNumber = event?.window?.windowNumber ?? window?.windowNumber {
      details["windowNumber"] = windowNumber
    } else {
      details["windowNumber"] = NSNull()
    }
    NativePaneTabDragReproLog.append(event: eventName, details: details)
  }

  func cancelResizeHoverIndicator() {
    isResizeDragging = false
    resizeHoverIndicator.cancel(in: self)
  }

  func needsCursorRefreshBeforeRemoval() -> Bool {
    isResizeDragging || isCurrentPointerInsideVisibleHandle()
  }

  @discardableResult
  func refreshCursorForCurrentPointerIfInside() -> Bool {
    guard isCurrentPointerInsideVisibleHandle() else {
      return false
    }
    cursor.set()
    return true
  }

  private func refreshCursorForCurrentPointer() {
    /*
     CDXC:NativePaneResize 2026-06-13-03:40:
     The concrete resize rail is the only native object allowed to keep the
     resize cursor. When hover or drag ownership ends, leave the resize cursor
     active only if the current pointer is still inside this visible rail.
     */
    if refreshCursorForCurrentPointerIfInside() {
      return
    }
    NSCursor.arrow.set()
  }

  private func isCurrentPointerInsideVisibleHandle() -> Bool {
    guard let window,
      superview != nil,
      !isHidden,
      alphaValue > 0,
      bounds.width > 0,
      bounds.height > 0
    else {
      return false
    }
    return bounds.contains(convert(window.mouseLocationOutsideOfEventStream, from: nil))
  }

  override func draw(_ dirtyRect: NSRect) {
    super.draw(dirtyRect)
    /**
     CDXC:NativePaneResize 2026-05-11-09:45
     Splitter rails are visually transparent. The focused pane border and
     workspace gap remain the intended production separation.
     */
  }

  override func mouseDown(with event: NSEvent) {
    isResizeDragging = true
    cursor.set()
    appendResizeRailLog("nativePaneResize.handle.mouseDown", event: event)
    onMouseDown?(event)
  }

  override func mouseDragged(with event: NSEvent) {
    cursor.set()
    appendResizeRailLog("nativePaneResize.handle.mouseDragged", event: event)
    onMouseDragged?(event)
  }

  override func mouseUp(with event: NSEvent) {
    isResizeDragging = false
    appendResizeRailLog("nativePaneResize.handle.mouseUp", event: event)
    onMouseUp?(event)
    refreshCursorForCurrentPointer()
  }
}

final class TerminalPaneBorderLayer: CAShapeLayer {
  private enum BorderState: Equatable {
    case attention
    case focused
    case none
  }

  private static let focusedBorderColor = NSColor(
    calibratedRed: 0x73 / 255,
    green: 0x73 / 255,
    blue: 0x73 / 255,
    alpha: 0.95
  ).cgColor
  private static let commandBorderColor = NSColor(
    calibratedRed: 0x11 / 255,
    green: 0x11 / 255,
    blue: 0x11 / 255,
    alpha: 1
  ).cgColor
  private static let attentionBorderColor = NSColor(
    calibratedRed: 0x95 / 255,
    green: 0xD7 / 255,
    blue: 0xF6 / 255,
    alpha: 1
  ).cgColor
  private static let roundedBottomCornerRadius: CGFloat = 12
  /*
   CDXC:NativePaneChrome 2026-06-16-19:27:
   Focus chrome should read lighter than attention/done chrome. Keep the
   focused outline one point thinner while preserving the existing attention
   and inactive command border weights.
   */
  private static let focusedBorderWidth: CGFloat = 1
  private static let attentionBorderWidth: CGFloat = 2
  private static let inactiveCommandBorderWidth: CGFloat = 2
  /*
   CDXC:NativePaneChrome 2026-06-17-09:38:
   The one-point focused border can disappear against the pane's clipped top
   and right edges. Pull only those two focused edges inward by one point so the
   full typing-target outline is visible without shifting the left or bottom
   edges.
   */
  private static let focusedTopRightEdgeInset: CGFloat = 1

  private var chromeRole: TerminalPaneChromeRole = .workspace
  private var hidesInactiveCommandBorder = false
  private var roundedBottomCorner: TerminalPaneRoundedBottomCorner = .none
  private var state: BorderState = .none
  private var suppressesFocusedBorder = false

  override init() {
    super.init()
    commonInit()
  }

  override init(layer: Any) {
    super.init(layer: layer)
    if let source = layer as? TerminalPaneBorderLayer {
      chromeRole = source.chromeRole
      hidesInactiveCommandBorder = source.hidesInactiveCommandBorder
      roundedBottomCorner = source.roundedBottomCorner
      state = source.state
      suppressesFocusedBorder = source.suppressesFocusedBorder
    }
    commonInit()
  }

  required init?(coder: NSCoder) {
    fatalError("init(coder:) is not supported")
  }

  override var bounds: CGRect {
    didSet { updateChrome() }
  }

  private func commonInit() {
    /**
     CDXC:NativePaneChrome 2026-06-13-09:52:
     Pane borders are status chrome, not controls. Keep them as layers so terminal, browser, and titlebar clicks follow normal AppKit view dispatch without a full-frame decorative NSView.
     */
    contentsScale = NSScreen.main?.backingScaleFactor ?? 2
    backgroundColor = NSColor.clear.cgColor
    fillColor = nil
    masksToBounds = false
    shadowRadius = 16
    shadowOffset = .zero
    shadowOpacity = 0
    zPosition = 50
    updateChrome()
  }

  fileprivate func setRoundedBottomCorner(_ corner: TerminalPaneRoundedBottomCorner) {
    /**
     CDXC:NativePaneChrome 2026-05-07-15:13
     The active/done pane border must have a real rounded visual bottom corner
     on the workspace side opposite the sidebar. Draw the transparent native
     overlay's border path directly instead of relying on CALayer's single
     corner border masking. In this unflipped AppKit view, visible bottom is
     min-Y, so bottom-left is min-X/min-Y and bottom-right is max-X/min-Y.
     */
    guard roundedBottomCorner != corner else {
      return
    }
    roundedBottomCorner = corner
    updateChrome()
  }

  fileprivate func setChromeRole(_ role: TerminalPaneChromeRole) {
    guard chromeRole != role else {
      return
    }
    chromeRole = role
    updateChrome()
  }

  fileprivate func setHidesInactiveCommandBorder(_ hides: Bool) {
    guard hidesInactiveCommandBorder != hides else {
      return
    }
    hidesInactiveCommandBorder = hides
    updateChrome()
  }

  fileprivate func setSuppressesFocusedBorder(_ suppresses: Bool) {
    /*
     CDXC:ProjectEditorCompanion 2026-06-09-17:46:
     Source, Browser, and Kanban companion panes keep real focus for keyboard
     routing. Earlier builds suppressed their focused border, but the current
     typing-target requirement below supersedes that mode-based suppression.

     CDXC:NativePaneChrome 2026-06-13-22:17:
     Companion panes now show focused chrome when they are the live keyboard
     target. Keep this setter only as a narrow escape hatch for future pane
     chrome; project mode alone must not suppress focused borders.
     */
    guard suppressesFocusedBorder != suppresses else {
      return
    }
    suppressesFocusedBorder = suppresses
    updateChrome()
  }

  func setState(isFocused: Bool, isAttention: Bool) {
    /**
     CDXC:NativeSessionStatus 2026-04-27-08:02
     Native Ghostty panes are outside the React workspace DOM. Mirror the
     existing workspace UX with a selected border and a #95d7f6 border for
     done/attention sessions, without stealing terminal input.

     CDXC:NativeSessionStatus 2026-06-12-02:32:
     The attention border is the native pane's done/attention status indicator;
     keep it on #95d7f6 with the other app surfaces.
     */
    let nextState: BorderState = isAttention ? .attention : isFocused ? .focused : .none
    guard nextState != state else {
      return
    }
    state = nextState
    updateChrome()
  }

  private func updateChrome() {
    CATransaction.begin()
    CATransaction.setDisableActions(true)
    let nextColor = currentBorderColor()
    let nextPath = nextColor == nil ? nil : borderPath(in: bounds)
    path = nextPath
    strokeColor = nextColor
    lineWidth = nextColor == nil ? 0 : currentBorderWidth()
    /*
     CDXC:NativePaneChrome 2026-06-13-11:14:
     Focused pane chrome must keep the existing outline without tinting terminal content. Do not assign the closed pane border path as a CALayer shadowPath; Core Animation treats that rectangle as a filled shadow source and paints a gray wash over the focused pane. Let the layer derive any shadow only from the stroked border pixels.
     */
    shadowPath = nil
    applyShadow(for: state)
    CATransaction.commit()
  }

  private func currentBorderColor() -> CGColor? {
    switch state {
    case .attention:
      return Self.attentionBorderColor
    case .focused:
      if suppressesFocusedBorder {
        return nil
      }
      return Self.focusedBorderColor
    case .none:
      if hidesInactiveCommandBorder {
        return nil
      }
      if chromeRole == .commands {
        return Self.commandBorderColor
      }
      return nil
    }
  }

  private func applyShadow(for state: BorderState) {
    switch state {
    case .attention:
      shadowColor = Self.attentionBorderColor
      shadowOpacity = 0.28
    case .focused:
      if suppressesFocusedBorder {
        shadowColor = nil
        shadowOpacity = 0
      } else {
        shadowColor = Self.focusedBorderColor
        shadowOpacity = 0.18
      }
    case .none:
      shadowColor = nil
      shadowOpacity = 0
    }
  }

  private func currentBorderWidth() -> CGFloat {
    /*
     CDXC:NativePaneChrome 2026-05-14-07:12:
     The dev build must compile after command chrome adds a distinct inactive border width.
     Keep the branch as an explicit return because Swift block methods do not implicitly return ternary expressions.
     */
    if state == .none && hidesInactiveCommandBorder {
      return 0
    }
    switch state {
    case .focused:
      return Self.focusedBorderWidth
    case .attention:
      return Self.attentionBorderWidth
    case .none:
      return chromeRole == .commands ? Self.inactiveCommandBorderWidth : 0
    }
  }

  private func borderPath(in bounds: CGRect) -> CGPath {
    let inset = currentBorderWidth() / 2
    let topRightInset = state == .focused ? Self.focusedTopRightEdgeInset : 0
    let rect = CGRect(
      x: bounds.minX + inset,
      y: bounds.minY + inset,
      width: bounds.width - inset * 2 - topRightInset,
      height: bounds.height - inset * 2 - topRightInset
    )
    guard rect.width > 0, rect.height > 0 else {
      return CGMutablePath()
    }
    let radius = roundedBottomCorner == .none
      ? 0
      : min(Self.roundedBottomCornerRadius, rect.width / 2, rect.height / 2)
    switch roundedBottomCorner {
    case .left:
      return bottomLeftRoundedBorderPath(in: rect, radius: radius)
    case .none:
      let path = CGMutablePath()
      path.addRect(rect)
      return path
    case .right:
      return bottomRightRoundedBorderPath(in: rect, radius: radius)
    }
  }

  private func bottomLeftRoundedBorderPath(in rect: CGRect, radius: CGFloat) -> CGPath {
    let path = CGMutablePath()
    path.move(to: CGPoint(x: rect.minX, y: rect.minY + radius))
    if radius > 0 {
      path.addCurve(
        to: CGPoint(x: rect.minX + radius, y: rect.minY),
        control1: CGPoint(x: rect.minX, y: rect.minY + radius * 0.4477),
        control2: CGPoint(x: rect.minX + radius * 0.4477, y: rect.minY)
      )
    } else {
      path.addLine(to: CGPoint(x: rect.minX, y: rect.minY))
    }
    path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
    path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
    path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
    path.closeSubpath()
    return path
  }

  private func bottomRightRoundedBorderPath(in rect: CGRect, radius: CGFloat) -> CGPath {
    let path = CGMutablePath()
    path.move(to: CGPoint(x: rect.minX, y: rect.minY))
    path.addLine(to: CGPoint(x: rect.maxX - radius, y: rect.minY))
    if radius > 0 {
      path.addCurve(
        to: CGPoint(x: rect.maxX, y: rect.minY + radius),
        control1: CGPoint(x: rect.maxX - radius * 0.4477, y: rect.minY),
        control2: CGPoint(x: rect.maxX, y: rect.minY + radius * 0.4477)
      )
    }
    path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
    path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
    path.closeSubpath()
    return path
  }
}
